window.__D("text/maamarim-melukatim/c003",{"p":[[1500360033,"<h3>בס\"ד. מוצאי שבת בראשית – בחדרו – ה'תשל\"ח<sup data-n=\"2268\">*</sup></h3>\n<b>בראשית</b> ברא אלקים את השמים ואת הארץ, וארז\"ל<sup data-n=\"2269\">1</sup> אמר ר' יצחק לא הי' צריך להתחיל את התורה אלא מהחודש הזה לכם כו', ומה טעם פתח בבראשית משום כח מעשיו הגיד לעמו לתת להם נחלת גוים<sup data-n=\"2270\">2</sup>, שאם יאמרו אומות העולם לישראל לסטים אתם שכבשתם ארצות שבעה גוים הם אומרים להם כל הארץ של הקב\"ה היא הוא בראה ונתנה לאשר ישר בעיניו ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו. ומבואר בזה בדרושי רבותינו נשיאינו<sup data-n=\"2271\">3</sup>, דזה מה שהי' צריך להתחיל את התורה מהחודש הזה לכם הוא, כי ענין \"החודש הזה\" הוא יחוד סובב וממלא. כי חודש הוא בחינת מלכות, חודש אשתו<sup data-n=\"2272\">4</sup>, בחינת ממכ\"ע, ו\"זה\" הוא ענין גילוי [כמרז\"ל<sup data-n=\"2273\">5</sup> מראה באצבעו ואומר זה], יסוד וז\"א, יחוד סוכ\"ע וממכ\"ע. ופירוש \"החודש הזה (לכם)\" הוא שבבחי' ממכ\"ע (חודש) יהי' בו גילוי סוכ\"ע (הזה). והי' צריך להתחיל את התורה מהחודש הזה לכם, כי תכלית התורה ומצוותי' הו\"ע יחוד סובב וממלא.\nב) <b>והנה</b> ענין המשכת הסובב שע\"י תורה ומצוות בשרשו הראשון הוא המשכת אוא\"ס שלפני הצמצום. וכדאיתא בעמק המלך בתחלתו<sup data-n=\"2274\">6</sup>, דבריאת העולמות הי' ע\"י צמצום הראשון שהי' באוא\"ס ונשאר חלל ומקום פנוי, ומזה הוא שרש התהוות הכלים ומציאות העולמות (ענין מעשה בראשית). ומ\"ש<sup data-n=\"2275\">7</sup> ויניחהו בג\"ע לעבדה ולשמרה [שקאי על העבודה דתומ\"צ, לעבדה זה רמ\"ח מ\"ע ולשמרה זה שס\"ה מל\"ת<sup data-n=\"2276\">8</sup>] הוא להמשיך תוספות אורות ע\"י הקו מאוא\"ס שלפני הצמצום, עד שלעתיד יהי' גילוי אוא\"ס במקום החלל כמו שהי' קודם הצמצום. וזהו לא הי' צריך להתחיל את התורה אלא מהחודש הזה לכם כו', כי סיפור מע\"ב הכל הוא אחר הצמצום, ומכיון שענינה של התורה הוא המשכת אוא\"ס שלמעלה מהצמצום, הוצרך להתחיל את התורה (לא במע\"ב, כ\"א) מהחודש הזה שהו\"ע המשכת בחי' הסובב (\"הזה\"), שבשרשו הוא המשכת אוא\"ס שלפני הצמצום.ג) <b>ומה</b> טעם פתח בבראשית משום כח מעשיו הגיד לעמו לתת להם נחלת גוים. והיינו שהענין דכח מעשיו גו' לתת להם נחלת גוים הוא נעלה יותר גם מענין המשכת הסובב, בחי' אוא\"ס שלפני הצמצום. דהנה תכלית הכוונה (דתומ\"צ) הוא להמשיך בחי' אור חדש, היינו בחי' עצמות אוא\"ס שלמעלה מהאור שהי' ממלא מקום החלל<sup data-n=\"2277\">9</sup>. והמשכת אור זה הוא דוקא ע\"י עבודת הבירורים<sup data-n=\"2278\">10</sup>. וזהו היתרון שבכח מעשיו גו' לתת להם נחלת גוים על החודש הזה, כי ענין החודש הזה הוא המשכת אור הסובב, שבשרשו הוא בחי' האור שהי' ממלא מקום החלל, וע\"י<sup data-n=\"2279\">11</sup> עבודת הבירורים דעניני העולם שנפלו מז\"מ, מלכי אדום שברצונו נתנה להם – כמרז\"ל<sup data-n=\"2280\">12</sup> בונה עולמות ומחריבן – ובנ\"י מבררים ויורשים<sup data-n=\"2281\">13</sup> אותם ונעשו נחלת יעקב, ממשיכים בחי' אור חדש שלמעלה מהאור שהי' ממלא מקום החלל. וכמו שהוא בכלל העולם (עולמות בי\"ע, דמשם יפרד) בא ג\"כ בפרט הבירור דכיבוש ארצות שבעה גוים, שישראל מהפכים אותם לארץ ישראל.\nד) <b>והנה</b> מכיון דזה ש\"ברצונו נתנה להם\" (לזמן מסויים) הוא <i>בכדי</i> שיהי' אח\"כ \"ברצונו נטלה מהם ונתנה לנו\", הרי פשוט, שבאם מחליטים בתוקף, אזי מבררים בנקל ביותר את ארצות שבעה גוים, וכל העולם כולו, שיהי' דירה לו ית'. וזה מה שנדמה שצריך לזה יגיעה ועמל, ועד שאומות העולם טוענים בנוגע לכל בירור<sup data-n=\"2282\">14</sup> לסטים אתם הוא מצד גודל ההעלם והסתר, מה שאין נרגש בעולם אשר \"כל הארץ של הקב\"ה היא\" (ו\"כי<sup data-n=\"2283\">15</sup> ממך הכל\"<sup data-n=\"2284\">16</sup>). אבל הרי תכלית הכוונה של ההעלם והסתר הוא בכדי שיהי' ובקשתם <i>משם</i><sup data-n=\"2285\">17</sup>, אַז אידן זאָלן זוכן און געפינען דעם אויבערשטן בכל עניני העולם, בההעלמות וההסתרים<sup data-n=\"2286\">18</sup> [וכמשל האב המסתיר את עצמו מבנו הקטן בכדי להראות את חכמת הבן שמבין שההסתר וההעלם אינו אלא בכדי שיבקשנו וימצאנו<sup data-n=\"2287\">19</sup>], והבטיחה תורה שכאשר ובקשתם משם אז בודאי \"ומצאת\"<sup data-n=\"2288\">20</sup>, שכובשים את כל העולם ועושים ממנו דירה לו ית', עד אשר אז אהפוך אל עמים שפה ברורה וגו' לעבדו שכם אחד<sup data-n=\"2289\">21</sup>. והיתה לה' המלוכה<sup data-n=\"2290\">22</sup>.ה) <b>ויש</b> לקשר זה גם עם ענין ד\"ויעקב הלך לדרכו\" (שבמוצאי שבת בראשית<sup data-n=\"2291\">23</sup>), דהגם שהולך לדרכו (גם) בעניני הרשות ובעובדין דחול במשך כל השנה, מ\"מ אינו יירא מזה, כי אם, הולך לבטח דרכו, ובשמחה ובטוב לבב. וזהו גם מה שבמוצאי שבת [ובפרט במוצאי שבת בראשית, שאז מתחיל (בעיקר) הסדר דויעקב הלך לדרכו<sup data-n=\"2291\">23</sup>] אומרים<sup data-n=\"2292\">24</sup> אל תירא עבדי יעקב<sup data-n=\"2293\">25</sup>, כי \"במוצאי שבת מסתלקת הנשמה יתירה וצריך לחזור ולירד בבחי' יעקב עבדי בכל ששת ימי המעשה לברר בירורים בבי\"ע כו' לכך אומר אל תירא עבדי יעקב כו' מלירד שם, ובזה נותנים כח ועוז כו'\"<sup data-n=\"2294\">26</sup>. והטעם לזה (לענין אל תירא) הוא כי הוי' אלקיו עמו<sup data-n=\"2295\">27</sup>, שכאו\"א מישראל (גם מי שהוא בבחי' יעקב), בכל מקום ובכל זמן ובכל ענין (גם בחו\"ל ובימי החול ובעובדין דחול), הוי' אלקיו (הוא) עמו, ועד שנעשה שותף להקב\"ה במעשה בראשית<sup data-n=\"2296\">28</sup>, שהוא פועל חידוש בהבריאה (כמו הקב\"ה כביכול). כי ע\"י עבודתו בעבודת הבירורים לעשות את העולם דירה לו ית', הוא פועל חידוש בהבריאה [דזהו גם מה שבשבת בראשית קורין בתורה בראשית ברא אלקים את השמים ואת הארץ, שעי\"ז נעשה בריאת השמים והארץ וכל צבאיהם מחדש ובאופן חדש], ועד שיהי' השמים החדשים והארץ החדשה גו'<sup data-n=\"2297\">29</sup>.\n**********",[["2268","*","יצא לאור ב<b>קונטרס מוצאי ש\"פ בראשית – ה'תשל\"ח</b>, \"<i>ר\"ח מ\"ח ה'תשל\"ח</i>\"."],["2269","1","תנחומא (באָבער) יא. ועוד – הובא בפרש\"י עה\"ת."],["2270","2","תהלים קיא, ו."],["2271","3","אוה\"ת בא ע' רסב."],["2272","4","שם ע' רנה, רעח."],["2273","5","תענית בסופה (ובפרש\"י שם). פרש\"י בשלח טו, ב."],["2274","6","הובא באוה\"ת שם. ובארוכה יותר בהמשך תרס\"ו בתחלתו (ס\"ע ג ואילך), ד\"ה יו\"ט של ר\"ה תש\"י ס\"ז. ובכ\"מ."],["2275","7","בראשית ב, טו."],["2276","8","אוה\"ת בראשית (ח\"ו ע' 2082 – בשם ארז\"ל). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381323\" data-slug=\"likkutei-torah\" data-id=\"4001381323\">לקו\"ת שה\"ש (מח, ד</a>). יל\"ר בראשית. זח\"א כז, א. תקו\"ז תכ\"א (סב, א). שם תנ\"ה (פח, ב)."],["2277","9","המשך תרס\"ו שם (ע' ד). ע' תקט. ד\"ה יו\"ט של ר\"ה תש\"י שם. ועוד."],["2278","10","המשך תרס\"ו ע' שלז ואילך. ס\"ע שנד ואילך. ועוד."],["2279","11","להעיר גם מהמשך הנ\"ל ס\"ע שמ ואילך."],["2280","12","קה\"ר פ\"ג, יא."],["2281","13","המשך וככה תרל\"ז פס\"ח. ד\"ה אם רוח המושל תרצ\"ה פ\"ו. ובכ\"מ."],["2282","14","ראה אוה\"ת שבהערה 3. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300101003\" data-slug=\"likkutei-sichot\" data-id=\"1300101003\">לקו\"ש ח\"י ע' 3</a>, 5."],["2283","15","לשון הכתוב – דה\"א כט, יד."],["2284","16","ראה אוה\"ת שבהערה 3."],["2285","17","ואתחנן ד, כט. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380845\" data-slug=\"likkutei-torah\" data-id=\"4001380845\">לקו\"ת ראה לב, ג</a>."],["2286","18","ומכיון שמצד ההעלמות וההסתרים, הבירור הוא \"בבחי' התחדשות גמורה כחידוש יש מאין\", לכן, עי\"ז דוקא הוא עיקר המשכת האור חדש (המשך תרס\"ו ע' שנד-ה)."],["2287","19","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381052\" data-slug=\"likkutei-torah\" data-id=\"4001381052\">לקו\"ת סוכות פב, א</a>. שער האמונה בהקדמה. המשך תרס\"ו ע' רמח ואילך (ולהעיר גם מהמשל המובא שם ס\"ע שפ ואילך)."],["2288","20","ואתחנן שם."],["2289","21","צפני' ג, ט."],["2290","22","עובדי' א, כא."],["2291","23","כמבואר בהשיחה (סעיף ד' – נדפסה ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201282\" data-slug=\"likkutei-sichot\" data-id=\"1300201282\">לקו\"ש ח\"כ ע' 269</a>)."],["2292","24","כ\"ה בלקו\"ת שבהערה 26. ולהעיר, שבכ\"מ בדא\"ח מבוארים גם (נוסחאות ו)מנהגים <i>שאין</i> נוהגים בחב\"ד."],["2293","25","לשון הכתוב – ישעי' מד, ב. ירמי' ל, יו\"ד. ועוד."],["2294","26","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו\"ת בלק עב, ב</a>."],["2295","27","בלק כג, כא. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380937\" data-slug=\"likkutei-torah\" data-id=\"4001380937\">לקו\"ת שם (עא, סע\"ד</a>), שענין זה (דהוי' אלקיו עמו) \"הוא העזר מלמעלה\" לבחי' <i>יעקב</i>. – ושייך לתרועת מלך בו – עבודה דר\"ה (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380607\" data-slug=\"likkutei-torah\" data-id=\"4001380607\">לקו\"ת ר\"ה נד, ג</a>. וראה גם לקו\"ת בלק עב, סע\"ב)."],["2296","28","שבת קיט, רע\"ב. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061022\" data-slug=\"likkutei-sichot\" data-id=\"1300061022\">לקו\"ש ח\"ו ע' 22</a> הע' 73."],["2297","29","ישעי' סו, כב. ובסה\"מ תרע\"ח ע' רפד: והוא ההמשכה מבחי' עצמות א\"ס שלמעלה מגילוי הקו ולמעלה מהאור שהי' ממלא מקום החלל."]]],[1500360034,"<h3>בס\"ד. ש\"פ בראשית (התוועדות ב'), ה'תנש\"א<sup data-n=\"2298\">*</sup></h3>\n<b>אלה</b> תולדות נח נח גו'<sup data-n=\"2299\">1</sup>, ומבאר הצמח צדק במאמרו ד\"ה זה<sup data-n=\"2300\">2</sup>, דמ\"ש נח נח שתי פעמים הוא, כי נח הוא בחינת שבת (כדלקמן), ובשבת יש שתי בחינות, כמאמר רז\"ל<sup data-n=\"2301\">3</sup> אלמלי משמרין ישראל שתי שבתות כהלכתן מיד נגאלים, וידוע<sup data-n=\"2302\">4</sup>, דפירוש שתי שבתות הוא<sup data-n=\"2303\">5</sup> שתי השבתות שישנם בכל שבת<sup data-n=\"2304\">6</sup>, מעלי דשבתא ויומא דשבתא. ולכן נאמר נח נח ב' פעמים, כנגד<sup data-n=\"2305\">7</sup> שתי השבתות שבכל שבת, מעלי דשבתא ויומא דשבתא. ומוסיף בהמאמר<sup data-n=\"2300\">2</sup>, דפירוש זה שנח הוא שבת הוא ע\"פ דאיתא במדרש<sup data-n=\"2306\">8</sup> דנח נח שתי פעמים הוא נייחא לו ונייחא לעולם, נייחא לאבות ונייחא לבנים, נייחא לעליונים ונייחא לתחתונים, נייחא בעוה\"ז ונייחא לעוה\"ב. ומאמר זה (דהמדרש) שנח הוא לשון נייחא כולל גם הפירוש שנח הוא בחינת שבת, כי בשבת כתיב<sup data-n=\"2307\">9</sup> וינח ביום השביעי. ונח נח שתי פעמים הם שבת תתאה ושבת עילאה, שהם<sup data-n=\"2304\">6</sup> מעלי דשבתא ויומא דשבתא. ויש לומר, דמהטעמים על זה שמבאר עוד פעם (לאחרי שמביא ראי' מהמדרש שנח הוא בחינת שבת) שנח נח הם מעלי דשבתא ויומא דשבתא, הוא, בכדי לרמז, שהשייכות דהפירוש שבהמאמר עם הפירוש שבמדרש הוא בנוגע ל<i>נח</i> [דמזה שנח הוא לשון נייחא מוכח שנח הוא בחינת שבת] ובנוגע לנח נח <i>שתי פעמים</i>. דהפירוש (שבהמאמר) שנח נח הם שבת תתאה [מעלי דשבתא] ושבת עילאה [יומא דשבתא] הוא ע\"ד פירוש המדרש שנח נח הם נייחא לעליונים ונייחא לתחתונים<sup data-n=\"2308\">10</sup>. והענין הוא, שמעלי דשבתא (עלית המלכות) בעבודת האדם הוא בירור והעלאת הגוף ונה\"ב<sup data-n=\"2309\">11</sup>, תחתון שבאדם<sup data-n=\"2310\">12</sup>, ויומא דשבתא (המשכת ז\"א) הוא המשכת הגילוי דנפשהאלקית&lt;11&gt;, עליון שבאדם&lt;12&gt;. ועל ידי שישראל שומרים שתי השבתות, שעי\"ז נעשה המנוחה (מהענינים המבלבלים מעבודת ה') הן בהתחתון שבאדם והן בהעליון שבאדם, עי\"ז נמשך גילוי המנוחה מלמעלה בכל העולמות, בעליונים ובתחתונים, נייחא לעליונים ונייחא לתחתונים<sup data-n=\"2311\">13</sup>.\nב) <b>וביאור</b> הענין בפרטיות יותר, יובן בהקדים המבואר בכ\"מ<sup data-n=\"2312\">14</sup> [וגם במאמר הנ\"ל דהצ\"צ<sup data-n=\"2313\">15</sup>] דשתי השבתות שישנם בכל שבת שייך לזה שכל עיסקא דשבתא כפול<sup data-n=\"2314\">16</sup>. וזהו אלמלי משמרין ישראל שתי שבתות כהלכתן מיד נגאלים, כי כפל שייך לגאולה<sup data-n=\"2315\">17</sup>. ויש לומר, דבדרז\"ל <i>כל</i> עיסקא דשבתא כפול נכלל גם שכל אחד משתי השבתות הוא כפול, היינו שכל אחד מהם כלול משניהם. והענין הוא, דאהבה ויראה הם (בכללות) העבודה שמצד הנשמה (יומא דשבתא) וקיום מצוות מעשיות היא העבודה שמצד הגוף (מעלי דשבתא). וענין עיסקא דשבתא כפול הוא, שאהבת ה' שמצד הנשמה (עליון שבאדם) תומשך בנפש הבהמית ובהגוף (תחתון שבאדם), וכמ\"ש<sup data-n=\"2316\">18</sup> ואהבת את הוי' אלקיך בכל לבבך (בשני ביתי\"ן), שהאהבה תהי' בחלל הימני מקום משכן נפש האלקית ובחלל השמאלי מקום משכן נפש הבהמית, כמארז\"ל<sup data-n=\"2317\">19</sup> בכל לבבך בשני יצריך<sup data-n=\"2318\">20</sup>. ויתירה מזו – בכל נפשך, שהאהבה מתפשטת בכל הכחות והאברים (וי\"ל שהוא כמו הרץ<sup data-n=\"2319\">21</sup> לדבר מצוה)<sup data-n=\"2320\">22</sup>, ויתירה מזו – בכל מאדך, שאהבתו את הוי' נמשכת וניכרת גם בחלקו בעולם (בכל מאדך בכל ממונך<sup data-n=\"2321\">23</sup>), וסיום הפרשה הוא<sup data-n=\"2322\">24</sup> וכתבתם על מזוזות ביתך ובשעריך, שע\"י המזוזה שקובע בפתח ביתו ניכר<sup data-n=\"2323\">25</sup> שה' אחד הוא המושל והוא השומר את הבית ואת כל אשר בתוכו<sup data-n=\"2324\">26</sup>,ושומר את האדם גם בצאתו מביתו, ה' ישמר צאתך ובואך מעתה ועד עולם<sup data-n=\"2325\">27</sup>. ועד\"ז הוא לאידך, שקיום המצוות מעשיות (עבודה שמצד הגוף) צ\"ל באהבה ויראה (עבודה שמצד הנשמה).\nג) <b>וממשיך</b> בהמאמר<sup data-n=\"2326\">28</sup>, דמנחת שבת וכן סעודה שלישית דשבת, היא למעלה משתי השבתות (מעלי דשבתא ויומא דשבתא), ועד שלגבי בחינה זו, שתי השבתות הם בשוה. וזהו זכור ושמור בדיבור אחד נאמרו<sup data-n=\"2327\">29</sup>, דזכור ושמור הם יומא דשבתא ומעלי דשבתא [זכור לדכורא<sup data-n=\"2328\">30</sup> (משפיע) הוא יומא דשבתא, המשכה מלמעלה למטה, ושמור לנוקבא<sup data-n=\"2328\">30</sup> (מקבל) הוא מעלי דשבתא, העלאה מלמטה למעלה<sup data-n=\"2329\">31</sup>], ולגבי גילוי הבחינה דמנחת שבת, המשפיע והמקבל הם בשוה, זכור ושמור בדיבור אחד. ויש לקשר זה עם מה שאומרים במנחת שבת כי מאתך היא מנוחתם, שהמנוחה דשבת (שמתגלית במנחת שבת, רעוא דרעוין<sup data-n=\"2330\">32</sup>) היא מאתך, מאתך ממש<sup data-n=\"2331\">33</sup>. ומנוחה זו היא כוללת גם המנוחה דיומא דשבתא ודמעלי שבתא, זכור ושמור.\n<b>ויש</b> לומר, דענין זכור ושמור בדיבור אחד בעבודת האדם הוא, שקיום המצוות שלו הוא [לא מפני שהורגל כן והרגל נעשה טבע<sup data-n=\"2332\">34</sup>, טבע הגוף ונפש הטבעית, תחתון שבאדם, וגם לא מפני שאוהב את הוי' וחפץ לדבקה בו ואי אפשר לדבקה בו באמת כי אם בקיום רמ\"ח פיקודין שהם<sup data-n=\"2333\">35</sup> רמ\"ח אברין דמלכא<sup data-n=\"2334\">36</sup>, דקיום המצוות באופן זה הוא מצד הנשמה (נפש האלקית), עליון שבאדם, אלא שקיום המצוות שלו הוא] מצד המצוה עצמה, מצוה מלשון צוותא וחיבור<sup data-n=\"2335\">37</sup>, שהוא מתאחד ומתחבר עם אוא\"ס מצַוה המצוות שלמעלה מהגדר דעליון ותחתון (נשמה וגוף) וכולל שניהם. וזהו\"ע זכור ושמור בדיבור אחד, דכוונת המצוה השייכת לנשמה (זכור) ומעשה המצוה השייכת להגוף (שמור), הם כולא חד.\n<b>ויש</b> לומר, שהמעלה דמנחת שבת על הכפילות (וההתכללות) דשתי השבתות שכל אחת מהם כלולה משתיהן (כנ\"ל סעיף ב), היא, דבענין ההתכללות (דלעיל שם), כל אחד מהם הוא ענין לעצמו, אלא שכלול גם מענין השני. דואהבת את ה'אלקיך הוא מצד הנשמה, אלא שהאהבה דהנשמה נמשכת גם בחלל השמאלי<sup data-n=\"2336\">38</sup>, ועד שמתפשטת גם בכל הכחות והאברים וניכרת גם בחלקו בעולם. והענין דמעשה המצוות שייך בעיקר לגוף האדם, אלא שבכדי שקיום המצוה תהי' לשמה הוא ע\"י האהבה ויראה<sup data-n=\"2337\">39</sup>. וענין זכור ושמור בדיבור אחד שבמנחת שבת הוא שכוונת המצוה (דהנשמה) ומעשה המצוה (דהגוף) הם כולא חד.\nד) <b>וע\"פ</b> הידוע<sup data-n=\"2338\">40</sup> בפירוש כי מאתך היא מנוחתם (שאומרים במנחת שבת), שמנוחתם הבאה מאתך, מאתך ממש, היא המנוחה (דשבת) שבעשי' בפועל (שביתה ממלאכה בגשמיות), שבה כל ישראל שוים, יש לומר, שעד\"ז הוא בהענין דקיום המצוה מצד המצוה עצמה, צוותא וחיבור עם אוא\"ס מצַוה המצוה, דענין זה מתגלה בעיקר בקיום המצוות בעשי' בפועל, שכל ישראל שוים בזה. והענין הוא, דהטעם האמיתי לזה שישראל מקיים מצוה (גם כשאין לו חיות בזה) הוא, מפני שכל אחד מישראל בעצם מהותו הוא רוצה לעשות כל מה שהוא רצון ה'<sup data-n=\"2339\">41</sup>. דרצון זה שמצד עצם הנשמה הוא הסיבה האמיתית לזה שרוצה בגילוי לעשות את המצוה [אלא שברצון הגלוי שלו אינו נרגש שסיבתו הוא הרצון שמצד עצם הנשמה, ולכן נדמה לו שקיום המצוה שלו הוא מפני ההרגל, או בשביל איזו פני']. ויתירה מזו יש לומר, דגם כשעושה שלא במתכוין (נפלה סלע מידו ומצאה עני<sup data-n=\"2340\">42</sup>), הסיבה האמיתית לזה הוא הרצון דעצם הנשמה לעשות את רצון ה'<sup data-n=\"2341\">43</sup>. כי עצם הנשמה היא למעלה מידיעה, ולכן פעולת הרצון דעצם הנשמה על כח המעשה הוא גם כשאינו יודע מזה. וזהו שהענין דקיום המצוה באופן דצוותא וחיבור עם עצמות אוא\"ס מצַוה המצוה מתגלה בעיקר במעשה המצוה, כי הסיבה האמיתית לזה שעושה את המצוה הוא לפי שנתגלה בו הרצון שמצד עצם הנשמה שקשורה עם עצמות אוא\"ס.\n<b>ויש</b> להוסיף, שגם בקיום המצוות באופן זה ישנו הענין דזכור ושמור בדיבור אחד. דכיון שהסיבה האמיתית לזה שעושה את המצוה הוא לפי שמתגלה בו הרצון דעצם הנשמה, הרי המצוה שנעשית היא מצוה בשלימות, שיש בה גוף (מעשה המצוה<sup data-n=\"2342\">44</sup>) ונשמה (כוונת המצוה<sup data-n=\"2342\">44</sup>, שמצד הרצון דעצם הנשמה). [אלא שהגוף דהמצוה הוא בגילוי והנשמה דהמצוה היא בהעלם]. וכיון ששני הענינים [הכוונה והמעשה] הם מצד עצם הנשמה שלמעלה מהתחלקות, לכן הם כולא חד, זכור ושמור בדיבור אחד.ה) <b>וזהו</b> אלה תולדות נח נח, דהטעם לזה שאומר נח נח שתי פעמים גבי תולדות נח, הוא, כי אמיתית הענין דנח נח שתי פעמים הוא, ששני הענינים דנייחא לעליונים ונייחא לתחתונים הם נקודה אחת שכוללת שניהם<sup data-n=\"2343\">45</sup>, וגילוי ענין זה הוא בעיקר בתולדות נח, דתולדותיהם של צדיקים הם מעשים טובים<sup data-n=\"2344\">46</sup>, כנ\"ל (סעיף ד) שאמיתית הענין דזכור ושמור בדיבור אחד הוא <i>במעשה</i> המצוות.\n<b>ויש</b> לומר, דהטעם שענין זה נאמר גבי נח, הוא, כי נח שייך לתשובה [דעבודתו של נח גרמה לאמירת ה' לא אוסיף גו' לא ישבותו<sup data-n=\"2345\">47</sup>], דע\"י התשובה הוא גילוי עצם הנשמה<sup data-n=\"2346\">48</sup>. ולכן נאמר בו נח נח שתי פעמים, ענין אחד שכולל שני הענינים דנייחא לעליונים ונייחא לתחתונים. ויש לקשר זה עם פירוש הידוע<sup data-n=\"2347\">49</sup> בלשון רז\"ל<sup data-n=\"2348\">50</sup> תשובה ומעשים טובים, שע\"י התשובה נעשים המעשים (מעשה המצוות) מעשים טובים ומאירים<sup data-n=\"2349\">51</sup>, דמעשים הוא גוף המצוה וטובים הוא האור והחיות דהמצוה (כוונת המצוות), וע\"י התשובה, שעל ידה הוא גילוי עצם הנשמה, המעשים (דהמצוות) עצמם הם טובים ומאירים, שמאיר בהם בגילוי הכוונה שמצד עצם הנשמה.\nו) <b>ויהי</b> רצון, דכיון שנמצאים כעת בסעודה שלישית דשבת ששייכת למנחת שבת, ובפרט שהקריאה בתורה דמנחת שבת זה היא אלה תולדות נח נח, תהי' מנוחה מכל הענינים המבלבלים לעבודת ה', הן בנוגע לעניני הגוף והן בנוגע לעניני הנשמה, וכנ\"ל (סעיף ג) שהמנוחה דמנחת שבת כוללת שני הענינים. וכיון שאת העולם נתן בלבו של האדם<sup data-n=\"2350\">52</sup>, עי\"ז תומשך המנוחה גם בכל העולמות, נייחא לעליונים ונייחא לתחתונים (כנ\"ל סעיף א). ויתירה מזו, דכמו שנח ראה עולם חדש<sup data-n=\"2351\">53</sup> (דנוסף לזה שהי' נייחא בכל העולמות, נעשה גם חידוש בעולם), כן נזכה בקרוב ממש לעולם חדש, השמים החדשים והארץ החדשה<sup data-n=\"2352\">54</sup>, ובפרט לאחרי הקריאה בתורה (בשחרית) בראשית ברא אלקים את השמים ואת הארץ<sup data-n=\"2353\">55</sup>, שעי\"ז פועלים שהקב\"ה בורא מחדש אתהשמים ואת הארץ וכל צבאיהם. ובקרוב ממש יהי' בנין בית המקדש השלישי שכנגד יעקב<sup data-n=\"2354\">56</sup>, שבו נכללים גם ביהמ\"ק הראשון והשני<sup data-n=\"2355\">57</sup> שכנגד אברהם ויצחק<sup data-n=\"2354\">56</sup> – בדוגמת מנחת שבת וסעודה השלישית דשבת, נחלת יעקב<sup data-n=\"2356\">58</sup>, הכוללת גם שתי השבתות דמעלי שבתא ודיומא דשבתא. ועוד ועיקר, שכל זה יהי' בקרוב ממש, ממש.\n**********",[["2298","*","יצא לאור בשעתו, \"לקראת ש\"ק פ' נח . . <i>עש\"ק ור\"ח מ\"ח</i>,<i> שנת ה'תנש\"א</i>\"."],["2299","1","ריש פרשתנו (נח)."],["2300","2","אוה\"ת פרשתנו נז, א. ביאוה\"ז להצ\"צ ע' יג."],["2301","3","שבת קיח, ב."],["2302","4","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380048\" data-slug=\"likkutei-torah\" data-id=\"4001380048\">לקו\"ת ר\"פ בשלח (ב, ג</a>). <i>ובכ\"מ</i>."],["2303","5","וזהו שבירושלמי (תענית פ\"א סוף ה\"א) אמרו אילו היו ישראל משמרין שבת אחת כתיקונה מיד הי' בן דוד בא, שאינו סותר להמאמר אלמלי משמרין ישראל שתי שבתות, כי פירוש שתי שבתות הוא שתי שבתות שבכל שבת (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>)."],["2304","6","זהר ח\"א (בהקדמה) ה, ב. ח\"ב קלח, א."],["2305","7","וכ\"ה בתו\"א ריש פרשתנו (ח, ג)."],["2306","8","ב\"ר ריש פרשתנו (פ\"ל, ה). וראה גם זח\"א נח, ב."],["2307","9","יתרו כ, יא."],["2308","10","ועפ\"ז יומתק שבתחלת הענין אומר בהמאמר ששתי השבתות הם שבת דמעלי שבתא ודיום השבת, ולאחרי שמביא המדרש, אומר דב\"פ נח הם \"שבת תתאה ושבת עילאה\" (ומפרש \"והוא שבת דמעלי שבתא ושבתא דיומא\") – כי הלשון \"שבת תתאה ושבת עילאה\" הוא ע\"ד לשון המדרש \"נייחא לעליונים ונייחא לתחתונים\"."],["2309","11","כן משמע באוה\"ת לתהלים (יהל אור) במילואים ס\"ע תרכח."],["2310","12","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370013\" data-slug=\"torah-or\" data-id=\"3901370013\">ראה ב</a>\"ר פ\"ח, יא. פי\"ב, ח. וראה תו\"א בראשית ג, ד ואילך. קונטרס ומעין מאמר טו. המשך תרס\"ו ע' תצה. ובכ\"מ."],["2311","13","ויש לומר, דבהמאמר מדבר בעבודת האדם (<i>משמרין ישראל</i> שתי שבתות), דעבודת האדם היא (בכלל) בסדר דמלמטה למעלה – ולכן אומר שבת תתאה ושבת עילאה; ובמדרש מדבר בההמשכה מלמעלה (שע\"י עבודת האדם), שהיא בסדר דמלמעלה למטה, ולכן אומר \"נייחא לעליונים ונייחא לתחתונים\"."],["2312","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380048\" data-slug=\"likkutei-torah\" data-id=\"4001380048\">לקו\"ת בשלח ב, ג</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830038\" data-slug=\"or-hatorah-hb\" data-id=\"8158830038\">אוה\"ת</a> לתהלים שם ריש ע' תרכט. שם בהשמטות ע' תשכד ואילך. ד\"ה לך לך תרכ\"ז (סה\"מ תרכ\"ז ע' טו) ותר\"ל (סה\"מ תר\"ל ע' ט). <i>ובכ\"מ</i>."],["2313","15","אוה\"ת שם נח, ב."],["2314","16","מדרש תהלים עה\"פ (תהלים צב, א) מזמור שיר ליום השבת. יל\"ש עה\"פ (בשלח טז, כט) ראו כי ה' נתן לכם השבת (רמז רסא)."],["2315","17","יל\"ש ר\"פ לך ובכ\"מ בענין אותיות כפולות (מנצפ\"ך). ובסה\"מ תרכ\"ז ותר\"ל שבהערה 14 מקשר זה עם מרז\"ל אלמלי משמרין ישראל שתי שבתות כו' נגאלים."],["2316","18","ואתחנן ו, ה."],["2317","19","ברכות נד, א (במשנה). ספרי (הובא בפרש\"י) עה\"פ."],["2318","20","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370137\" data-slug=\"torah-or\" data-id=\"3901370137\">תו\"א וישב כט, ג</a>. שערי אורה שער החנוכה י, ב. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158670134\" data-slug=\"or-hatorah-hb\" data-id=\"8158670134\">אוה\"ת חנוכה רפה, ב</a> ואילך. וראה גם תניא פ\"ט."],["2319","21","ראה אבות פ\"ד מ\"ב. ברכות ו, ב. שו\"ע (ואדה\"ז) או\"ח ס\"צ סי\"ב (סי\"ג)."],["2320","22","המשך תרס\"ו ע' תצז. סה\"מ תרפ\"ט ע' 263. סה\"מ קונטרסים ח\"ב שנא, א."],["2321","23","ברכות ופרש\"י שבהערה 19."],["2322","24","ואתחנן שם, ט."],["2323","25","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">תו\"א מקץ מב, ג</a> \"וקובעין (המזוזה) בפתח הבית להעלות הבית וכל אשר בו כו' להיות בטלים לאהבת ה' בכל מאדך בכל ממונך\", ושם מג, ד \"ובכל מאדך היא המזוזה שהיא בסוף ביתו עם כל הרכוש שבתוכו\"."],["2324","26","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300191121\" data-slug=\"likkutei-sichot\" data-id=\"1300191121\">ע\"ז</a> יא, א. מנחות לג, ריש ע\"ב. וראה ירושלמי פאה פ\"א ה\"א. זהר ח\"ב לו, רע\"א (וראה לקו\"ש חי\"ט ע' 121 בשוה\"ג). ח\"ג רסו, א."],["2325","27","תהלים קכא, ח. זח\"ג רסג, ב."],["2326","28","אוה\"ת פרשתנו סא, א."],["2327","29","ר\"ה כז, א. מכילתא (הובא בפרש\"י) עה\"פ יתרו כ, ח."],["2328","30","זהר ח\"א מח, ב. שם (בהשמטות) רסה, א. ח\"ב צב, א (ברע\"מ). שם קלח, א. ח\"ג צב, סע\"ב (בהקדמת הרע\"מ). שם רכד, סע\"א. וראה ג\"כ שם פא, סע\"ב."],["2329","31","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370324\" data-slug=\"torah-or\" data-id=\"3901370324\">תו\"א יתרו עג, סע\"א</a> ואילך. ובכ\"מ."],["2330","32","זח\"ב פח, סע\"ב. וראה המשך תרס\"ו ע' תקמב ואילך."],["2331","33","ראה ד\"ה אתה אחד לאדמו\"ר האמצעי (מאמרי אדמו\"ר האמצעי קונטרסים ע' יו\"ד)."],["2332","34","<a class=\"ft-cite\" href=\"#/read/tanya/3401310049\" data-slug=\"tanya\" data-id=\"3401310049\">תניא פמ\"ד (סג, ב</a>). וראה גם שם ספי\"ד. פט\"ו (כא, א). שבילי אמונה (לר' מאיר אלדבי) נתיב ד שער ב. שו\"ת הרמ\"ע מפאנו סל\"ו."],["2333","35","ראה תקו\"ז ת\"ל (עד, סע\"א). הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310028\" data-slug=\"tanya\" data-id=\"3401310028\">תניא רפכ\"ג</a>. ועוד."],["2334","36","<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>."],["2335","37","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380272\" data-slug=\"likkutei-torah\" data-id=\"4001380272\">לקו\"ת בחוקותי מה, ג</a>. ובכ\"מ – נסמנו לקמן ח\"ג ע' נט הערה 55."],["2336","38","להעיר מ<a class=\"ft-cite\" href=\"#/read/tanya/3401310014\" data-slug=\"tanya\" data-id=\"3401310014\">תניא פ\"ט</a> \"שתתפשט גם בחלל השמאלי\", היינו שהאהבה <i>שבחלל הימני</i> מתפשטת גם בחלל השמאלי, ובהמשך הענין שם \"בכל לבבך בשני יצריך\"."],["2337","39","<a class=\"ft-cite\" href=\"#/read/tanya/3401310044\" data-slug=\"tanya\" data-id=\"3401310044\">תניא פל\"ט (נג, ב</a>)."],["2338","40","ד\"ה אתה אחד דלעיל הערה 33. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151239\" data-slug=\"likkutei-sichot\" data-id=\"1300151239\">לקו\"ש חט\"ו ע' 227</a> ואילך. לקמן ח\"ב ע' נד. ובכ\"מ."],["2339","41","וכפס\"ד הרמב\"ם הידוע בהל' גירושין ספ\"ב."],["2340","42","ראה ספרי הובא בפרש\"י עה\"פ תצא כד, יט. תו\"כ הובא בפרש\"י עה\"פ ויקרא ה, יז."],["2341","43","ועפ\"ז מובן, שגם כשנתינת הצדקה היא בלי ידיעתו, מתברך עלי' (ספרי ותו\"כ שם)."],["2342","44","דמצוה בלא כוונה היא \"כגוף בלא נשמה\" – ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח (נ, א</a>). <a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">של\"ה רמט, סע\"ב</a>. וראה בהנסמן במפתח פסוקים ומחז\"ל ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא</a> (קה\"ת תשמ\"ה) ע' צ הערה 11."],["2343","45","וכמו שהוא בפשטות, שהוא <i>איש אחד</i> שנכפל שמו."],["2344","46","פרש\"י ריש פרשתנו.\nולפירוש הראשון שבפירוש רש\"י שתולדות נח הם כפשוטם – יש לומר, דג' בני נח הם ג' הקוין חג\"ת (אוה\"ת פרשתנו סג, א. תו\"א ר\"פ וישב), שהם תורה עבודה וגמ\"ח. וכאשר קיום המצוות הוא באופן דצוותא וחיבור עם אוא\"ס מצַוה המצוות (הענין דנח נח שתי פעמים) – ג' הענינים דתורה עבודה וגמ\"ח הם כולא חד."],["2345","47","פרשתנו ח, כא-כב. ולהעיר, שע\"י הקרבנות שהקריב נח נעשה קיום העולם עוד יותר מכמו שהי' בתחילה (קיום באופן ד\"לא ישבותו\"), ע\"ד המעלה דבע\"ת לגבי צדיקים."],["2346","48","ולהעיר מהמשך תער\"ב ח\"א פר\"א (ע' תח) דענין \"וגם את נח באהבה זכרת\" הוא \"מפני האהבה עצמית\", \"מצד עצם מעלת נש\"י\"."],["2347","49","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת</a> דרושים לשמע\"צ פה, א. שה\"ש יז, ג. וראה לקו\"ש ח\"ד ע' 1053 ואילך."],["2348","50","אבות פ\"ד מי\"ז."],["2349","51","דפירוש טובים הוא מאירים כמ\"ש (בראשית א, ד) את האור כי טוב (לקו\"ת שה\"ש שם)."],["2350","52","ע\"פ ל' הכתוב – קהלת ג, יא. וראה לקו\"ת במדבר ה, ריש ע\"ב."],["2351","53","ב\"ר פרשתנו פ\"ל, ח."],["2352","54","ישעי' סו, כב. וראה ד\"ה כי כאשר השמים החדשים ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370004\" data-slug=\"torah-or\" data-id=\"3901370004\">תו\"א בראשית (א, סע\"ג</a> ואילך) וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381322\" data-slug=\"likkutei-torah\" data-id=\"4001381322\">לקו\"ת שה\"ש (מח, ג</a> ואילך)."],["2353","55","בראשית א, א."],["2354","56","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380656\" data-slug=\"likkutei-torah\" data-id=\"4001380656\">פסחים פח, א</a>. וראה לקו\"ת מטות פג, ג-ד."],["2355","57","זח\"ג רכא, א."],["2356","58","ישעי' נח, יד. שבת קיח, סע\"א ואילך. זח\"ב פח, ב. וראה אוה\"ת פרשתנו סב, סע\"ב ואילך."]]],[1500360035,"<h3>בס\"ד. מוצאי ש\"פ נח – בחדרו – ה'תשל\"ח<sup data-n=\"2357\">*</sup></h3>\n<b>מים</b> רבים לא יוכלו לכבות את האהבה ונהרות לא ישטפוה גו'<sup data-n=\"2358\">1</sup>, ואיתא בדרושי רבותינו נשיאינו<sup data-n=\"2359\">2</sup>, שמים רבים הם כל טרדות הפרנסה והמחשבות שבעניני עולם הזה, ועכ\"ז לא יוכלו לכבות את האהבה המסותרת שיש בכל נפש מישראל, ונהרות לא ישטפוה, שגם כאשר מחשבות הנ\"ל הם מטרידות ביותר, עד שהן משוטטות במרוצה בתמידות בלי הפסק כלל, כמו הנהרות<sup data-n=\"2360\">3</sup> שנובעים תמיד בלי הפסק וניידי ואזלי בשטף גדול<sup data-n=\"2361\">4</sup>, מ\"מ לא ישטפוה להאהבה (ולא יוכלו לכבותה<sup data-n=\"2362\">5</sup>).\nב) <b>וביאור</b> דיוק הלשון \"טרדות הפרנסה\", הנה כתיב<sup data-n=\"2363\">6</sup> יגיע כפיך כי תאכל גו', וידוע הדיוק בזה<sup data-n=\"2364\">7</sup>, יגיע כפיך דוקא אבל לא יגיעת המוח והלב. והיינו דהגם אשר (מצד זה שהשפע בעוה\"ז נמשכת דרך לבוש הטבע<sup data-n=\"2365\">8</sup>) צריך להיות עשי' שבזה תתלבש השפע שלמעלה, וכמ\"ש<sup data-n=\"2366\">9</sup> וברכך הוי' אלקיך בכל אשר תעשה (דוקא), ועד שלפעמים (מצד גודל ההעלם וההסתר<sup data-n=\"2367\">10</sup>) צריכים גם ליגיעה, מ\"מ אין צריך להעסיק בעשי' זו כ\"א רק את כחות החיצונים שלו, יגיע כפיך [כפים ושארי אברים החיצונים<sup data-n=\"2368\">11</sup>], אבל לא את כחות הפנימיים והנעלים (שבמוח ולב), כי כחות אלו צריכים להיות מוקדשים לשמש את קונו, שזהו תכלית בריאתו<sup data-n=\"2369\">12</sup>. והגם שמכיון שהשפע מתעלם ומסתתר בלבושי הטבע צריך להשתמש גם בשכלו לצורך העסק, הוא רק מה שמוכרח להעשי', אבל לא באופן דיגיעה בהתחכמות ותחבולות. ובפרט שברכת הוי' היא תעשיר<sup data-n=\"2370\">13</sup>, והעסק אינו אלא <i>לבוש</i> לברכת הוי' (ולא שהעסק הוא מקור פרנסתו ח\"ו), הרי מובן<sup data-n=\"2371\">14</sup>, שבדוגמת הלבושים בפשטות \"המרבה בלבושיםלא העדיף מאומה, ואדרבה<sup data-n=\"2372\">15</sup> מקלקל יותר\"<sup data-n=\"2373\">16</sup>. וזהו דיוק הלשון \"טרדות הפרנסה\", דהגם שהוא במצב נמוך שיש לו <i>טרדות</i> הפרנסה [שזה מראה אשר אינו מתבונן כדבעי אליבי' דנפשי' שברכת הוי' היא תעשיר<sup data-n=\"2374\">17</sup>], מ\"מ, הנה גם הטרדות לא יוכלו לכבות ח\"ו את האהבה המסותרת שבכ\"א מישראל.\nג) <b>והנה</b> החידוש בזה שמים רבים לא יוכלו לכבות את האהבה, דידוע דשרש המים רבים [שהוא טרדות הפרנסה] הוא בבחי' התהו שקדם לתיקון<sup data-n=\"2375\">18</sup>. דזהו שנקראים מים רבים להיותם \"רבים\" (גם) מצד שרשם ומקורם<sup data-n=\"2376\">19</sup>. וזהו הרבותא<sup data-n=\"2377\">20</sup> בזה שמים רבים לא יוכלו לכבות את האהבה ונהרות לא ישטפוה, דהגם ששרש המים רבים והנהרות<sup data-n=\"2378\">21</sup> הוא בבחי' התהו שקדם לתיקון (שרש נפש האלקית), מ\"מ לא יוכלו לכבות ח\"ו את האהבה שבנפש האלקית<sup data-n=\"2379\">22</sup>. והטעם לזה הוא (כמ\"ש לפנ\"ז<sup data-n=\"2380\">23</sup>) רשפי' רשפי אש שלהבת י-ה<sup data-n=\"2381\">24</sup>, ששרש הנשמה והאהבה מסותרת שבה הוא בעצמות אוא\"ס שלמעלה גם מבחי' תהו. ששרש האהבה שבנפש האלקית הוא בבחי' שלהבת י-ה כמו שהיא קשורה וגנוזה בגחלת (רשפי אש<sup data-n=\"2382\">25</sup>), ולמעלה יותר<sup data-n=\"2383\">26</sup> – כמו שהוא בבחי' צור<sup data-n=\"2384\">27</sup> (שלמעלה מהוי'<sup data-n=\"2385\">28</sup>), ששם הוא שרש הנשמה, כמבואר בלקו\"ת<sup data-n=\"2386\">29</sup> בפירוש הכתוב<sup data-n=\"2387\">30</sup> והרוח תשוב אל האלקים אשר נתנה, שבחי' האלקים (אשר נתנה) הוא בחי' צור הנ\"ל.\nד) <b>והנה</b> לא זו בלבד שאין ביכולת המים רבים הנ\"ל לכבות ח\"ו את האהבה של הנשמה, אלא יתירה מזו, שעל ידם נעשה יתרון בהאהבה. והוא שע\"י ירידת הנשמה למטה בעוה\"ז והתלבשותה במים רבים הנ\"ל היא מגיעה למדריגה נעלית יותר ממדריגתה קודם ירידתה למטה<sup data-n=\"2388\">31</sup>. [וזהו תכלית הכוונה שלמים רבים הנ\"ל. ולכן סו\"ס אין ביכולתם לכבות את האהבה, לפי<sup data-n=\"2389\">32</sup> שתכלית עומק כוונתם של המים רבים גופא הוא אדרבא בכדי לפעול יתרון בהאהבה<sup data-n=\"2390\">33</sup>]. ובעבודה העילוי שנעשה בהנשמה ע\"י ירידתה למטה והתלבשותה במים רבים הנ\"ל הוא שבאה לענין התשובה<sup data-n=\"2391\">34</sup>. וכידוע<sup data-n=\"2392\">35</sup>, שהנשמות קודם ירידתן לגוף הם בבחי' צדיקים גמורים, והיתרון שנעשה בהם ע\"י ירידתן בגוף הוא שנעשים בבחי' בעלי תשובה, אשר במקום שבעלי תשובה עומדין צדיקים גמורים אינם עומדין<sup data-n=\"2393\">36</sup>, ויתירה מזו, שאין <i>יכולין</i> לעמוד בו<sup data-n=\"2394\">37</sup>, שאין זה (אפילו) ביכולת<sup data-n=\"2395\">38</sup> שלהם. וזהו הטעם שירדה הנשמה למטה, כי ענין התשובה [הגם שאינה על עבירות דוקא, כ\"א השבת הנפש למקורה ושרשה<sup data-n=\"2396\">39</sup>] שייך דוקא כאשר אינו נמצא במקומו האמיתי (מקורו ושרשו), שאז שייך שישוב לשרשו ומקורו, בחי' והרוח תשוב אל האלקים אשר נתנה<sup data-n=\"2397\">40</sup>. ומכיון שמעלת הבע\"ת היא נעלית יותר ממעלת הצדיקים [ועד שהחילוק שביניהם הוא שלא בערך, שלכן מקום שבעלי תשובה עומדין אין צדיקים גמורים <i>יכולין</i> לעמוד בו, כנ\"ל], לכן, ע\"י ענין התשובה שמתחדש בהנשמה בירידתה למטה ה\"ה מתעלית יותר גם מכפי שהיתה בשרשה, בבחי' האלקים אשר נתנה<sup data-n=\"2398\">41</sup>.\nה) <b>והגם</b> ששרש הנשמות הוא בעצמותו ית' שלמעלה מכל הגילויים, וכדמוכח (גם) ממה שארז\"ל<sup data-n=\"2399\">42</sup> במי נמלך בנשמותיהן של צדיקים, שענין ההמלכה הוא גם על גילויים הכי נעלים (מכיון שהם ברצון ולא בהכרח ח\"ו), הרי מובן שהנשמות שבהן נמלך הן למעלה מכל הגילויים<sup data-n=\"2400\">43</sup>, מ\"מ שייך לומר שע\"י התשובה (בירידתן למטה) נעשית בהן עלי' גם לגבי הדרגא שהי' בשרשן. ויובן זה ע\"פ מ\"ש הרב המגיד<sup data-n=\"2401\">44</sup> בפירוש מרז\"ל<sup data-n=\"2402\">45</sup> ישראל עלו במחשבה, שהוא כמשל אדם שיש לו בן, דגם כשהבן עבר מכנגד פניו והלך מאתו, עכ\"ז נחקקה הצורה של הבן במחשבה של האב. אלא שבבני אדם שייך זה דוקא במי שיש לו בן כו'. אבל אצל השי\"ת שייך זה לומר אף קודם שנבראו ישראל הי' נחקק צורתם במחשבה,כמ\"ש רז\"ל&lt;45&gt; ישראל עלו במחשבה, כי אצלו ית' העבר והעתיד אחד. ומובן מזה, דזה מה שהנשמות מושרשות בעצמותו ית' ובהם נמלך כו' – הו\"ע הנשמות כמו שהן בבחי' נברא (וכמו שהן יורדות למטה), ורק ש(גם) צורה זו היא חקוקה במחשבתו ית', לפי שאצלו ית' העבר והעתיד אחד. וכידוע<sup data-n=\"2403\">46</sup> בפירוש במי נמלך כו', שזהו מה שעלה לפניו ית' התענוג שיתענג כבי' בעבודת הנשמות <i>למטה</i>. ועפ\"ז יובן ענין העלי' שנעשה בהנשמות ע\"י ירידתן למטה, הגם שגם לפני ירידתן הן מושרשות בעצמותו ית', כי זה מה שהן מושרשות בעצמותו ית' (ובהם נמלך כו') הוא מצד ידיעתו ית' שתהי' אח\"כ ירידתן למטה כו' וישלימו הכוונה<sup data-n=\"2404\">47</sup>. והגם שגם בתחלה יודעים בודאות גמורה שישלימו הכוונה, הרי זהו בכח, ותכלית העילוי (והכוונה) הוא<sup data-n=\"2405\">48</sup> הפועל. [וזהו גם דיוק הלשון במי נמלך בנשמותיהן של צדיקים, שבהיותן בבחינת ההמלכה [שאז העילוי שלהן הוא בכח, שיודעים שישלימו הכוונה] הן בבחינת צדיקים, ולאחרי ירידתן למטה [שאז הם משלימים את הכוונה בפועל] נעשים בבחי' בעלי תשובה].\nו) <b>ויש</b> לקשר זה עם ענין ד\"ויעקב הלך לדרכו\" (שבמוצאי שבת פרשת נח<sup data-n=\"2406\">49</sup>), דהגם שלאחרי חודש תשרי הוא הולך לדרכו (גם) בעניני הרשות ובעובדין דחול, ועד לבחינת מים רבים הנ\"ל, מ\"מ עי\"ז גופא הוא מתעלה יותר, שנעשה בבחינת מהלך<sup data-n=\"2407\">50</sup>, וכלשון הכתוב<sup data-n=\"2408\">51</sup> ויעקב <i>הלך</i> לדרכו. וידיעה זו [שהירידה (לדרכו בעניני הרשות וכו') היא צורך עלי'] פועלת שההליכה תהי' בשמחה ובטוב לבב [וע\"ד מ\"ש<sup data-n=\"2409\">52</sup> גבי יעקב וישא יעקב רגליו גו' משנתבשר בשורה טובה כו']. וזה פועל שעבודתו תהי' בתכלית השלימות ולמעלה ממדידה והגבלה (בחי' בכל מאדך<sup data-n=\"2410\">53</sup>), כי שמחה פורץ<sup data-n=\"2411\">54</sup> כל הגדרים. וע\"י שעובד עבודתו [בכל הג' קוין (ג' בני נח<sup data-n=\"2412\">55</sup>) דתורה עבודה וגמ\"ח] בתכלית השלימות ובשמחה ובטוב לבב, נמשך לו גם ברכת הוי' בכל המצטרך לו [בג' הענינים דבני חיי ומזוני<sup data-n=\"2413\">56</sup>] בתכלית השלימות ובשמחה ובטוב לבב, הן ברוחניות והן בגשמיות, וברוחניות ובגשמיות גם יחד.\n**********",[["2357","*","יצא לאור ב<b>קונטרס מוצאי ש\"פ נח – ה'תשל\"ח</b>, \"<i>ז' מ\"ח ה'תשל\"ח</i>\"."],["2358","1","שה\"ש ח, ז."],["2359","2","תו\"א ר\"פ נח. תו\"ח נח נח, ד ואילך. מים רבים תרל\"ו (בתחלתו. פע\"ה)."],["2360","3","משא\"כ \"מים\", מי הים \"הם מכונסים ועומדים\" (תו\"א ותו\"ח שבהערה הבאה)."],["2361","4","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670249\" data-slug=\"torat-chaim\" data-id=\"2300670249\">תו\"ח שם סב, ב</a>. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370038\" data-slug=\"torah-or\" data-id=\"3901370038\">תו\"א ט, ב</a> (ד\"ה אם יתן). יו\"ד, א (ד\"ה וזהו הפי')."],["2362","5","כ\"ה בתו\"א שם, ש\"לא יוכלו לכבות גו'\" קאי גם על \"נהרות\"."],["2363","6","תהלים קכח, ב."],["2364","7","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380483\" data-slug=\"likkutei-torah\" data-id=\"4001380483\">לקו\"ת שלח מב, ד</a>. חוקת סו, ג. ובכ\"מ."],["2365","8","דרמ\"צ קז, א (וראה גם שם ח, א). קונטרס ומעין מכ\"ה פ\"א."],["2366","9","ראה טו, יח. ובספרי שם: יכול יהא יושב ובטל* ת\"ל בכל אשר תעשה."],["2367","10","להעיר, <i>ש</i>\"<i>בזעת</i> אפיך תאכל לחם\" (בראשית ג, יט) נתחדש לאחרי חטא עה\"ד."],["2368","11","לקו\"ת שלח שם."],["2369","12","קדושין בסופה."],["2370","13","משלי י, כב."],["2371","14","ראה בכ\"ז דרמ\"צ קז, ב. קונטרס ומעין שם פ\"ב.\n*) <i>כן הובא בקונטרס ומעין שם ובכ\"מ</i>.<i> ובספרי שלפנינו</i>:<i> יכול בטל</i>.<i> וביל\"ש (עה\"פ)</i>:<i> יכול כשעומד ובטל כו'</i>."],["2372","15","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380051\" data-slug=\"likkutei-torah\" data-id=\"4001380051\">לקו\"ת</a> חוקת שם: ואדרבה מחשבה מועלת. וראה גם דרך חיים בהקדמה (ג, ב)."],["2373","16","דרמ\"צ שם."],["2374","17","דרמ\"צ שם (קז, א ואילך). קונטרס ומעין שם פ\"ג. ד\"ה וידעת תרנ\"ז."],["2375","18","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370093\" data-slug=\"torah-or\" data-id=\"3901370093\">תו\"א יו\"ד, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670173\" data-slug=\"torat-chaim\" data-id=\"2300670173\">תו\"ח שם סא, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560286\" data-slug=\"or-hatorah-hb\" data-id=\"8316560286\">אוה\"ת נח (כרך ג') תרט, ב</a>."],["2376","19","להעיר, שבתהו היו אורות <i>מרובים</i>. וראה אוה\"ת שם, שענין מים רבים הוא דוגמת ענין רשות הרבים שהוא בחי' עולם הנקודים."],["2377","20","ועד \"שזהו רבותא <i>גדולה</i>\" (תו\"ח שם)."],["2378","21","בתו\"א שם, ש\"מים רבים\" ו\"נהרות\" הם ב' בחי' בתהו."],["2379","22","תו\"ח שם."],["2380","23","שה\"ש ח, ו."],["2381","24","ראה גם שהש\"ר עה\"פ (בסופו): שלהבת י-ה . . כאש של מעלה . . ולא המים מכבין לאש. וראה בפירוש מהרז\"ו שם."],["2382","25","ראה פירוש הראב\"ע לשה\"ש שם (וראה גם מצודת שם): רשפי' – גחלי'. ובתיב\"ע שם: גומרין דאשא (אוה\"ת והמשך מים רבים שבהערה 27)."],["2383","26","ראה ד\"ה ואברהם זקן תרס\"ו. ובכ\"מ."],["2384","27","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560310\" data-slug=\"or-hatorah-hb\" data-id=\"8316560310\">אוה\"ת נח תרכא, ב</a>. מים רבים תרל\"ו פע\"ג. וראה גם אוה\"ת שה\"ש עה\"פ (ע' תשמו)."],["2385","28","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380190\" data-slug=\"likkutei-torah\" data-id=\"4001380190\">לקו\"ת אחרי כו, ג</a>."],["2386","29","ר\"פ האזינו (עב, א). שמע\"צ פה, רע\"ב."],["2387","30","קהלת יב, ז."],["2388","31","תו\"א ותו\"ח שבהערה 2. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560311\" data-slug=\"or-hatorah-hb\" data-id=\"8316560311\">אוה\"ת נח תרכב, א</a>. מים רבים הנ\"ל פע\"ה ואילך."],["2389","32","והיינו, דזה שאין ביכולתם לכבות את האהבה הוא לא רק מצד שרש האהבה (כנ\"ל ס\"ג), אלא גם מצד \"תכלית עומק כוונתם\" של המים רבים גופא."],["2390","33","ראה המשך מים רבים שם."],["2391","34","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א שם ט, א</a>. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670093\" data-slug=\"torat-chaim\" data-id=\"2300670093\">תו\"ח שם נט, סע\"ד</a>."],["2392","35","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380610\" data-slug=\"likkutei-torah\" data-id=\"4001380610\">לקו\"ת בלק עג, סע\"א</a>. ובכ\"מ. ובלקו\"ת שם, שזהו \"התירוץ האמיתי\" למה ירדה הנשמה לעוה\"ז."],["2393","36","ברכות לד, ב."],["2394","37","רמב\"ם הל' תשובה פ\"ז ה\"ד (וגם בלקו\"ת שם מובא הגירסא אינם יכולים)."],["2395","38","שלמעלה מבחי' כח (המשך ר\"ה תש\"ג פי\"ג. ועוד)."],["2396","39","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380815\" data-slug=\"likkutei-torah\" data-id=\"4001380815\">לקו\"ת ראה כד, ד</a>. ש\"ש סו, ג. ובכ\"מ."],["2397","40","לקו\"ת ר\"פ האזינו."],["2398","41","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381011\" data-slug=\"likkutei-torah\" data-id=\"4001381011\">לקו\"ת שם עב, רע\"א</a>: והתשובה היא להיות . . כמו קודם ירידתה <i>ויתר על כן</i>. ומ\"ש והרוח תשוב אל <i>האלקים אשר נתנה</i> – ראה לקמן הערה 47."],["2399","42","רות רבה רפי\"ב."],["2400","43","ד\"ה העושה סוכתו תרצ\"ט פ\"ב. וראה גם המשך תער\"ב (ח\"ב) ע' תתק."],["2401","44","או\"ת (ב, ג) עה\"פ נעשה אדם – הובא גם בהמשך הנ\"ל ס\"ע תתקב [ומהמשך הענין שם (ראה שם ריש ע' תתקג) משמע שזה שייך גם לענין במי נמלך כו']."],["2402","45","ב\"ר פ\"א, ד."],["2403","46","המשך ר\"ה תש\"ג פ\"ג. ובכ\"מ."],["2404","47","ועפ\"ז יובן מ\"ש \"והרוח תשוב אל <i>האלקים אשר נתנה</i>\" – אף שע\"י התשובה נעשית בעילוי יותר – כי גם העילוי דנשמה שע\"י התשובה הוא בבחינת \"האלקים אשר נתנה\" (שרש הנשמות בעצמותו ית'). אלא שבתחלה הוא רק בכח, כבפנים. ועצ\"ע."],["2405","48","ראה בארוכה בהשיחה סעיף ד' ואילך (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201296\" data-slug=\"likkutei-sichot\" data-id=\"1300201296\">לקו\"ש ח\"כ ע' 283</a> ואילך)."],["2406","49","ראה בארוכה בהשיחה (שם ע' 281 ואילך) סעיף ב' ואילך. ושם (ס\"ג ואילך), שהחידוש שבמוצאי ש\"פ נח על מוצאי שבת בראשית הוא – שאז ישנו כבר הענין ד\"ויעקב הלך לדרכו\" בפועל."],["2407","50","וע\"ד הידוע (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370139\" data-slug=\"torah-or\" data-id=\"3901370139\">תו\"א ל, סע\"א</a> ואילך. ובכ\"מ) בענין העלי' שע\"י (כללות) ירידת הנשמה למטה, שהעלי' היא מה שנעשית בבחי' מהלך."],["2408","51","ויצא לב, ב. וראה שיחת מוצאי שבת בראשית ס\"ו (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201001\" data-slug=\"likkutei-sichot\" data-id=\"1300201001\">לקו\"ש שם ע' 1-270</a>)."],["2409","52","ויצא כט, א. פירש\"י שם. וראה שיחה הנ\"ל ס\"י (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201003\" data-slug=\"likkutei-sichot\" data-id=\"1300201003\">לקו\"ש שם ע' 3-272</a>)."],["2410","53","להעיר, שזהו (בחי' בכל מאדך) גם העילוי שנעשה ע\"י ה\"מים רבים\" (<a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א ט, א</a>. ובכ\"מ)."],["2411","54","ד\"ה שמח תשמח תרנ\"ז ע' 49 ואילך."],["2412","55","ג' בני נח הם בחי' חג\"ת (תו\"א ר\"פ וישב ואוה\"ת נח סג, א), ענין הג' קוין דתורה עבודה וגמ\"ח."],["2413","56","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490173\" data-slug=\"or-hatorah-hb\" data-id=\"8316490173\">אוה\"ת וירא תשנו, סע\"א</a> ואילך."]]],[1500360036,"<h3>בס\"ד. מוצאי ש\"פ לך לך – בחדרו – ה'תשל\"ח<sup data-n=\"2414\">*</sup></h3>\n<b>ויאמר</b> ה' אל אברם לך לך מארצך וממולדתך ומבית אביך אל הארץ אשר אראך, וידוע<sup data-n=\"2415\">1</sup> שיש בזה ב' פירושים. פירוש הא' שההליכה (דלך לך) היא מלמעלמ\"ט. וכמבואר בתו\"א<sup data-n=\"2416\">2</sup> שאברם הוא אב רם, שכל הנעלם מכל רעיון [שהוא למעלה גם מבחי' חכמה. כי חכמה (עם היותה <i>ראשית</i> כל הכחות פנימיים) היא בחי' גילוי. משא\"כ אב רם הוא שכל <i>הנעלם</i> מכל רעיון. וכמבואר בהגהות וביאורי הצ\"צ לתו\"א שם<sup data-n=\"2417\">3</sup> פרטי הדרגות שבזה]. ואמר ה' אל אברם לך לך מארצך גו' שיצא אורו הנעלם לגילוי ויומשך מלמעלה למטה עד אל הארץ, בחי' מלכות. ומוסיף \"אשר אראך\", ובזה ב' פירושים. א' (כפשוטו) שאראך קאי על הארץ, בחי' מלכות, שהמלכות היא בחי' עלמא דאתגליא לכן אומר עלי' אשר אראך<sup data-n=\"2418\">4</sup>. ופירוש ב' שאראך קאי על אברם (בחי' שכל הנעלם מכל רעיון) – \"אראה ואגלה אותך בעצמך\"<sup data-n=\"2419\">5</sup> (\"במהותך ועצמותך\"<sup data-n=\"2420\">6</sup>). והיינו, דהגם שספירת המלכות עלמא דאתגליא (ובפרט כמו שנמשכת בבי\"ע<sup data-n=\"2421\">7</sup>) היא קצה הכי תחתון, ושכל הנעלם מכל רעיון (שהוא נעלם גם מרעיון העליון) הוא קצה הכי עליון, אעפ\"כ, ע\"י הירידה וההמשכה (דאברם, שכל הנעלם מכל רעיון) אל הארץ אשר אראך (כפירוש הא'), לבחי' מלכות עלמא דאתגליא (קצה התחתון), עי\"ז יתראה ויתגלה אמיתית ענינו (מהותו ועצמותו) של אברם (כפירוש הב'), שנעשה עילוי (גם) בבחי' שכל הנעלם מכל רעיון (קצה הכי עליון), כמובן מהמבואר בתו\"א שם<sup data-n=\"2422\">8</sup>.\nב) <b>ועד\"ז</b> הוא גם בענין ירידת הנשמה בגוף<sup data-n=\"2423\">9</sup>, שהעלי' הנעשית בהנשמה ע\"י ירידתה למטה [שנעשית בבחינת מהלך<sup data-n=\"2424\">10</sup>, ענין \"<i>לך</i> לך\"<sup data-n=\"2425\">11</sup>], היא גם בהדרגות הכי נעלות שבה, ואפילו בבחינת יחידה. דהגם דזה שנקראת יחידה הואלהיותה \"מקבלת מיחיד\"<sup data-n=\"2426\">12</sup> [שלכן<sup data-n=\"2427\">13</sup> אין שייך שתהי' כנגדה בלעו\"ז, בבואה דבבואה לית להו<sup data-n=\"2428\">14</sup>], מ\"מ, ע\"י שהנשמה יורדת למטה, מאיגרא רמה לבירא עמיקתא<sup data-n=\"2429\">15</sup>, נעשה עלי' גם בבחינת יחידה שבה. כמבואר בכמה דרושים<sup data-n=\"2430\">16</sup> שע\"י עבודת הנשמה בירידתה למטה דוקא נעשה עלי' (ועלי' שלא בערך) גם בשרש ועצם הנשמה שלמעלה. וכמובן גם מהמבואר בכמה שיחות<sup data-n=\"2431\">17</sup> (בענין עלי' לתורה), שהעלי' היא בכל חמש הבחינות שבנשמה נפש רוח נשמה חי' יחידה, שהם ג' הבחינות תחתיים שניים ושלישיים<sup data-n=\"2432\">18</sup> דתיבת נח. וע\"פ משנת\"ל<sup data-n=\"2433\">19</sup> (ע\"פ תורת הבעש\"ט<sup data-n=\"2434\">20</sup> עה\"פ<sup data-n=\"2435\">21</sup> בא גו' אל התיבה) שענין תיבת נח הוא \"הוראה בסדר עבודה\"<sup data-n=\"2436\">22</sup> לכאו\"א מישראל [ובפרט לאחרי חודש תשרי שאז מתחיל סדר העבודה ד\"ויעקב הלך לדרכו\"<sup data-n=\"2437\">23</sup>. שהגם שהוא הולך לדרכו (גם) בעניני הרשות ובעובדין דחול, ועד לבחי' מים רבים שהם כל טרדות הפרנסה כו'<sup data-n=\"2438\">24</sup>, מ\"מ ע\"י שמכניס את עצמו בהתיבות דתפלה ותורה הנה לא זו בלבד שהוא \"ניצל מהשטף דמבול\"<sup data-n=\"2436\">22</sup> אלא יתירה מזו שע\"י המים נעשה ותרם התיבה<sup data-n=\"2439\">25</sup> ועד שנעשה ותנח התיבה<sup data-n=\"2440\">26</sup>], מובן מזה, שעליית הנשמה שנעשה ע\"י ירידתה למטה והתלבשותה במים רבים הוא בכל ג' הבחינות (דתיבת נח) תחתיים שניים ושלישיים, שענינם בנפש האדם הוא נר\"נ חי' יחידה<sup data-n=\"2441\">27</sup>. בדוגמת המבואר לעיל (סעיף א') שע\"י הליכת וירידת אברם אל הארץ בחי' מלכות, שהתכלית (דירידה זו) הוא להיות גילוי בבי\"ע<sup data-n=\"2442\">28</sup> [וכידוע<sup data-n=\"2443\">29</sup>, שהליכת אברם אל הארץ הי' בכדי להמשיך בבי\"ע עד בעוה\"ז הגשמי, שעי\"ז עשה הכנה לההמשכהשע\"י מעשה המצוות בגשמיות לאחרי מתן תורה] נעשה עילוי גם בבחי' שכל הנעלם מכל רעיון.\nג) <b>ופירוש</b> הב' בלך לך גו' אל הארץ הוא (כפשטות הכתוב<sup data-n=\"2444\">30</sup>) שהליכה זו היא מלמטה למעלה, ההליכה מארצך וממולדתך ומבית אביך שהוא (כפשטות הכתוב) ארצו וגו' של תרח [היפך ענין הטהרה<sup data-n=\"2445\">31</sup>], דרגא הכי תחתונה, ומשם ילך ויעלה מלמטלמ\"ע עד אל הארץ אשר אראך שקאי (כנ\"ל ס\"א) על בחי' המלכות, ועד לבחי' ויבן שם מזבח להוי' הנראה אליו<sup data-n=\"2446\">32</sup> (שהוא למעלה מבחי' מלכות), ועד אשר ויבן שם מזבח להוי' סתם<sup data-n=\"2447\">33</sup>, בחי' הוי' דלעילא, הוי' הנעלם, שלמעלה מהוי' (דלתתא) הנראה<sup data-n=\"2448\">34</sup>. ועד\"ז הוא גם בהעבודה ד\"ויעקב הלך לדרכו\" שבכאו\"א שלאחרי חודש תשרי, שהליכה זו היא (לא רק באופן דמלמעלה למטה, שהולך לדרכו מהמועדים דחודש תשרי לדרכו בעניני הרשות ועובדין דחול במשך כל השנה, אלא) גם באופן דמלמטלמ\"ע, מתחיל מכח המעשה שלו, ובכח המעשה גופא כמו שהוא בהעקב שבו, דרגא היותר תחתונה שבגוף האדם [ועד שהוא ענין דהיפך החיים<sup data-n=\"2449\">35</sup>, בדוגמת המובא לעיל בנוגע לתרח שהוא היפך הטהרה], ומשם מתחיל הליכתו מלמטלמ\"ע, שפועל גם בהעקב שלו ער זאָל דערהערן אלקות [וכמ\"ש באברהם עקב אשר שמע אברהם בקולי<sup data-n=\"2450\">36</sup> שגם העקב שלו האָט דערהערט<sup data-n=\"2451\">37</sup>. וע\"י שהי' זה אצל אברהם אבינו, ניתן הכח על זה לכאו\"א מישראל (בדוגמת האהבה מסותרת שבכאו\"א מישראל שהיא בירושה לנו מאבותינו<sup data-n=\"2452\">38</sup>, ובפרט מאברהם אבינו<sup data-n=\"2453\">39</sup>)], ומזה נמשך (באופן דהילוך מלמטלמ\"ע) השמיעה (דער דערהער) באלקות בכל הכחות, עד לכח השכל שבראש, שתהי' בהם השמיעה למעלה ממדידה והגבלה דשכל.\n<b>וגם</b> ענין זה ד\"ויעקב הלך לדרכו\" (הליכה מלמטלמ\"ע) מתחיל לאחרי חודש תשרי. דהנה העבודה דשמע\"צ ושמח\"ת (סיום המועדים דחודש תשרי) היא ב(שמחה ו)ריקודים, שענין הריקודים הוא (בעיקר ומתחיל) בהרגלים, ובהם גופא בהעקב שבהם. וע\"י שהעקבים מתנשאים (הויבן זיך) ומרקדים, הם מנשאים גם את הראש (וכח השכל שבו)<sup data-n=\"2454\">40</sup>, שגם הוא מרקד בשמחה גדולה למעלה ממדידה והגבלה. ומזה נמשך כח על העבודה דויעקב הלך לדרכו (הליכה מלמטלמ\"ע)במשך כל השנה, מתחיל מכח המעשה כמו שהוא בהעקב [כולל הענינים שאדם דש בעקביו<sup data-n=\"2455\">41</sup>, היינו ענינים אשר (מצד איזה סיבה שתהי') אין לו חיות בהם (בדוגמת העקב כפשוטו שהו\"ע דהיפך החיים)], ומזה ממשיך (באופן דהילוך מלמטלמ\"ע) גם לכח השכל שבראש, כנ\"ל.\nד) <b>ושני</b> פירושים הנ\"ל בלך לך מארצך גו' הם בהתאם לשני הפירושים ב\"בעבר הנהר ישבו אבותיכם\"<sup data-n=\"2456\">42</sup>. הפירוש [שבפנימיות התורה<sup data-n=\"2457\">43</sup>] שעבר הנהר הוא הבחי' שלמעלה (גם) מבחי' ונהר יוצא מעדן<sup data-n=\"2458\">44</sup> (בינה דאצילות) ופירוש בעבר הנהר ישבו אבותיכם גו' הוא ששרש האבות הוא מעבר הנהר שלמעלה מאצילות ומשם נמשכו למטה (בעבר השני של הנהר, היינו) בז\"א דאצילות, ועד ש\"ואולך אותו בכל ארץ כנען\"<sup data-n=\"2459\">45</sup> הירידה וההמשכה בבחינת המלכות (כנ\"ל סעיף א' שארץ ישראל קאי על מלכות) – ההליכה מארצך גו', שקאי על עבר הנהר, אל הארץ אשר אראך, הוא הליכה מלמעלה למטה<sup data-n=\"2460\">46</sup>. והפירוש (כמו שהוא בפשטות) שעבר הנהר הוא מקומו של תרח, ומ\"ש בעבר הנהר ישבו אבותיכם גו' הוא לגריעותא [כדמוכח ממרז\"ל<sup data-n=\"2461\">47</sup> מתחיל בגנות כו' מתחילה עובדי ע\"ז היו אבותינו כו' שנאמר בעבר הנהר ישבו אבותיכם גו'] – ההליכה מארצך גו' (עבר הנהר) אל הארץ אשר אראך, הילוך ועלי' מלמטלמ\"ע<sup data-n=\"2462\">48</sup> (כנ\"ל סעיף ג').\nה) <b>והנה</b> הגם שב' פירושים הנ\"ל ב\"לך לך\" הם שני פירושים שונים והפכיים, מ\"מ, מכיון שב' הפירושים הם באותה התיבה (תיבת לך), מוכח מזה<sup data-n=\"2463\">49</sup>, שענין \"לך לך\" [וההוראה לכאו\"א מישראל שבפרשה זו] כולל ב' האופנים יחד, הילוך מלמעלה למטה והילוך מלמטה למעלה. ובדוגמת \"והתהלכתי בתוככם\"<sup data-n=\"2464\">50</sup> ש\"והתהלכתי\" (לשון רבים) כולל<sup data-n=\"2465\">51</sup> ב' בחינות הילוך הנ\"ל<sup data-n=\"2466\">52</sup>. וכ\"ה גם בענין ואולך אתכם קוממיות<sup data-n=\"2467\">53</sup>, ש\"קוממיות\" (לשון רבים<sup data-n=\"2468\">54</sup>) מורה על ב' קומות<sup data-n=\"2469\">55</sup> [קומה דאורישר וקומה דאור חוזר, שהם דוגמת ב' בחינות הילוך הנ\"ל<sup data-n=\"2470\">56</sup>], הכוונה בזה היא ש\"קוממיות\" כולל ב' הקומות יחד.\n<b>ויש</b> לקשר זה עם שנה זו (ביחוד), שהיא שנת העיבור, ויתירה מזו שהיא שנת העיבור דסיום מחזור קטן, שבה נעשה ההתאמה דשנת החמה עם שנת הלבנה (בתכלית השלימות)<sup data-n=\"2471\">57</sup>. דהנה שמש הוא בחי' משפיע – דוגמת ענין ההילוך מלמעלמ\"ט, ולבנה (דלית לה מגרמה כלום<sup data-n=\"2472\">58</sup>) הוא בחי' מקבל – דוגמת ענין ההילוך מלמטלמ\"ע. וענין שנת העיבור (ובפרט שנת העיבור דסיום מחזור קטן) הוא צירוף וחיבור ב' העבודות [העבודה דשמש (בחי' משפיע, הילוך מלמעלמ\"ט, שבכללות הוא<sup data-n=\"2473\">59</sup> עבודת הצדיקים), והעבודה דלבנה (בחי' מקבל, הילוך מלמטה למעלה, שבכללות הוא<sup data-n=\"2473\">59</sup> עבודת הבעלי תשובה)], שייעשו ענין אחד (שנה תמימה), כמשנ\"ת לעיל<sup data-n=\"2474\">60</sup> בארוכה. וכמ\"ש<sup data-n=\"2475\">61</sup> ועינינו מאירות כשמש וכירח, שהכוונה בזה היא [לא רק שיהיו ב' המעלות, המעלה דשמש והמעלה דירח אלא גם] שב' הענינים (והמעלות) יהיו כאחד.\n<b>וענין</b> זה [צירוף ואיחוד ב' ענינים הנ\"ל] הוא הכנה וכלי [ובאופן דאבר, שהוא לא רק מקבל אלא גם ממשיך<sup data-n=\"2476\">62</sup>] להמשכת אוא\"ס שלמעלה מגדר \"מעלה ומטה\". [וע\"ד הידוע<sup data-n=\"2477\">63</sup> שלאחרי השלימות דאתערותא דלתתא (בחי' לבנה) וגילוי אתערותא דלעילא (בחי' שמש) (הנמשכת ע\"י אתערותא דלתתא) נמשך אח\"כ בחי' אתערותא דלעילא ממקום שאין אתערותא דלתתא מגעת שם כלל]. ששלימות העבודה [בצירוף ב' ענינים הנ\"ל, שנה <i>תמימה</i>] הוא האתר שלים, שהוא כלי להשראת אוא\"ס, דקוב\"ה שריא באתר שלים<sup data-n=\"2478\">64</sup>. ועד שעי\"ז נעשה המשכת העצמות שהוא אמיתית ותכלית השלימות. ונעשים ישראל וקוב\"ה (ע\"י אורייתא) כולא חד<sup data-n=\"2479\">65</sup>, ובאופן שאין שייך לחלק ביניהם, מכיון שתורת אמת מעידה שהם חד.\n**********",[["2414","*","יצא לאור ב<b>קונטרס מוצאי ש\"פ לך לך – ה'תשל\"ח</b>, \"<i>עש\"ק וירא ה'תשל\"ח</i>\"."],["2415","1","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670485\" data-slug=\"torat-chaim\" data-id=\"2300670485\">תו\"ח לך לך פט, א</a>. אוה\"ת שם (כרך ו') תתרעט, ב."],["2416","2","ר\"פ לך לך. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670031\" data-slug=\"torat-chaim\" data-id=\"2300670031\">תו\"ח שם (פ, א</a>). אוה\"ת שם תתרעב, א ואילך."],["2417","3","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490031\" data-slug=\"or-hatorah-hb\" data-id=\"8316490031\">אוה\"ת לך לך (כרך ד') תרפה, א</a>. וראה גם תו\"ח שם."],["2418","4","כ\"מ ב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670095\" data-slug=\"torat-chaim\" data-id=\"2300670095\">תו\"ח שם</a> (תחילת סעיף ב'). ושם פא, רע\"א – באו\"א קצת."],["2419","5","תו\"א יא, ב. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670095\" data-slug=\"torat-chaim\" data-id=\"2300670095\">תו\"ח שם פא, רע\"א</a>. אוה\"ת שם (כרך ו') תתרעג, א."],["2420","6","תו\"ח שם. ובאוה\"ת שם: בעצמך ומהותך."],["2421","7","ראה לקמן סוס\"ב."],["2422","8","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370049\" data-slug=\"torah-or\" data-id=\"3901370049\">תו\"א שם יא, ב</a> ואילך (וב<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670095\" data-slug=\"torat-chaim\" data-id=\"2300670095\">תו\"ח שם פא, סע\"א</a> ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490035\" data-slug=\"or-hatorah-hb\" data-id=\"8316490035\">אוה\"ת שם תתרעג, ב</a>), שהירידה דבחי' אברם למטה היא ע\"י (גילוי) בחינה שלמעלה מבחי' אברם. ובאוה\"ת שם (כרך ד') תרפז, א בשוה\"ג, שהיא ירידה צורך עלי'."],["2423","9","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490037\" data-slug=\"or-hatorah-hb\" data-id=\"8316490037\">אוה\"ת שם תרפח, סע\"א</a>, שענין לך לך \"קאי על ירידת הנשמה בגוף\"."],["2424","10","ראה בהמצויין לעיל ע' רמט הערה 50. ובכ\"מ."],["2425","11","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490019\" data-slug=\"or-hatorah-hb\" data-id=\"8316490019\">אוה\"ת שם</a> תרעט, א: \"לך לך, שיהי' בבחי' מהלך ולא בבחי' עומד\". ושם ע\"ב: שזהו \"<i>עיקר</i> פי' לך לך\"."],["2426","12","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380816\" data-slug=\"likkutei-torah\" data-id=\"4001380816\">לקו\"ת ראה כה, א</a>."],["2427","13","ראה ד\"ה צהר תעשה תש\"ז פ\"ל (ע' 187). וראה גם ד\"ה ועשית ציץ עת\"ר (ע' קס)."],["2428","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380867\" data-slug=\"likkutei-torah\" data-id=\"4001380867\">גיטין סו, א</a>. לקו\"ת תצא לז, ג. ד\"ה ועשית ציץ שם. צהר תעשה שם."],["2429","15","לשון הגמרא – חגיגה ה, ב."],["2430","16","ד\"ה זה היום תש\"ט ספ\"ב ואילך. וראה הביאור בזה לקו\"ש ח\"ג ע' 846."],["2431","17","לקו\"ד כה, ב ואילך. סה\"ש תש\"ב ע' 75."],["2432","18","נח ו, טז. וראה לקמן הערה 27."],["2433","19","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201007\" data-slug=\"likkutei-sichot\" data-id=\"1300201007\">לקו\"ש ח\"כ ע' 7-286</a>."],["2434","20","הובאה בד\"ה צהר תעשה תרצ\"ה בתחלתו ובכ\"מ (ראה הוספות לכתר שם טוב (הוצאת קה\"ת, תשנ\"ט) סי' יא)."],["2435","21","נח ז, א."],["2436","22","לשון כ\"ק מו\"ח אדמו\"ר בד\"ה צהר תעשה שם."],["2437","23","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201282\" data-slug=\"likkutei-sichot\" data-id=\"1300201282\">לקו\"ש שם ע' 269</a>, וע' 282."],["2438","24","ראה ד\"ה מים רבים סעיף ו' (לעיל ע' רמט)."],["2439","25","(נח ז, יז) <a class=\"ft-cite\" href=\"#/read/torah-or/3901370037\" data-slug=\"torah-or\" data-id=\"3901370037\">תו\"א ט, סע\"א</a>."],["2440","26","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560354\" data-slug=\"or-hatorah-hb\" data-id=\"8316560354\">נח ח, ד</a>. וראה אוה\"ת נח ע, א. (כרך ג') תרמג, ב ואילך."],["2441","27","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316550008\" data-slug=\"or-hatorah-hb\" data-id=\"8316550008\">אוה\"ת</a> שם תרכז, א (מרמ\"ז), שג' הבחינות תחתיים שניים ושלישיים הם בי\"ע אצילות וא\"ק. וידוע (שע\"ק להרח\"ו ח\"ג פ\"ב. ע\"ח שער דרושי אבי\"ע פ\"ג – הובא בהמשך תרס\"ו ע' רל. ד\"ה ויהי אומן עטר\"ת פ\"א. ובכ\"מ) שנר\"ן הם מבי\"ע, חי' מאצי', ויחידה מא\"ק.\nוזהו גם הכוונה במ\"ש בלקו\"ד שם, שחמשה השמות נרנח\"י הם תחתיים שניים שלישיים רביעיים וחמישיים שהם ד' עולמות אבי\"ע ועולמות א\"ס שלמעלה מאצילות, שמונה העולמות בי\"ע <i>לג'</i> בחינות – כהפי' (אוה\"ת שם, משל\"ה), שתחתיים שניים ושלישיים הם בי\"ע (ועפ\"ז יש \"רביעיים וחמישיים\" – ובדוגמת ה' שמות דנשמה)."],["2442","28","תו\"א ריש פרשתנו (וראה הגהות הצ\"צ לשם <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490032\" data-slug=\"or-hatorah-hb\" data-id=\"8316490032\">אוה\"ת לך תרפה, ב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316490040\" data-slug=\"or-hatorah-hb\" data-id=\"8316490040\">תרפט, ב</a>)."],["2443","29","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670266\" data-slug=\"torat-chaim\" data-id=\"2300670266\">תו\"ח שם פג, ד</a> ואילך. אוה\"ת שם (כרך ו') תתרעה, סע\"א ואילך. וראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370050\" data-slug=\"torah-or\" data-id=\"3901370050\">תו\"א יא, סע\"ג</a>."],["2444","30","וכ\"ה בל\"ת להאריז\"ל – מובא במקומות שבהערה 1."],["2445","31","ראה במדב\"ר רפי\"ט: מי יתן טהור מטמא . . כגון אברהם מתרח."],["2446","32","פרשתנו יב, ז."],["2447","33","שם, ח."],["2448","34","אוה\"ת פרשתנו (כרך ד') תרפד, ב. תרפז, ב. תרפט, סע\"א. ד\"ה בחודש השלישי תש\"ב."],["2449","35","אדר\"נ ספל\"א."],["2450","36","תולדות כו, ה."],["2451","37","סה\"מ תש\"ח ס\"ע 253. התמים ח\"ו ע' נב."],["2452","38","<a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>."],["2453","39","<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300550062\" data-slug=\"torat-chaim\" data-id=\"2300550062\">תו\"ח שמות תקלז, סע\"ב</a> [בהוצאה החדשה – תצוה ח\"ב שסג, סע\"ב]. וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381039\" data-slug=\"likkutei-torah\" data-id=\"4001381039\">לקו\"ת סוכות עח, ד</a>. שמע\"צ פט, ב."],["2454","40","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201280\" data-slug=\"likkutei-sichot\" data-id=\"1300201280\">לקו\"ש שם ע' 267</a> ואילך."],["2455","41","רש\"י ר\"פ עקב."],["2456","42","יהושע כד, ב. ובאוה\"ת פרשתנו תרפב, ב הובאו ב' הפירושים דלקמן."],["2457","43","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370117\" data-slug=\"torah-or\" data-id=\"3901370117\">תו\"א כה, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370337\" data-slug=\"torah-or\" data-id=\"3901370337\">עה, ד</a>. דרמ\"צ פב, ב. ובכ\"מ."],["2458","44","בראשית ב, יו\"ד."],["2459","45","יהושע שם, ג."],["2460","46","ראה גם אוה\"ת שם תרצ, ב."],["2461","47","פסחים קטז, א."],["2462","48","ראה גם אוה\"ת שם תרצא, ב."],["2463","49","ראה לקו\"ש ח\"ג ע' 782 (הראי' לזה מ\"שעטנז\")."],["2464","50","בחוקותי כו, יב."],["2465","51","ובנוגע ל\"והתהלכתי\" – פשוט שכולל ב' הבחינות, מכיון (שאין זה שני פירושים כ\"א) שפירוש \"והתהלכתי\" הוא <i>ב'</i> אופני הילוך. ועד\"ז הוא גם בנוגע ל\"קוממיות\" (דלקמן בפנים)."],["2466","52","דרושי ד\"ה והתהלכתי – <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159940234\" data-slug=\"or-hatorah-hb\" data-id=\"8159940234\">אוה\"ת ויקרא (כרך ב') ע' תרמ</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380820\" data-slug=\"likkutei-torah\" data-id=\"4001380820\">לקו\"ת ראה כו, א</a>. אמ\"ב שער הק\"ש פפ\"ז. ספפ\"ח ואילך."],["2467","53","בחוקותי כו, יג."],["2468","54","ראה חדא\"ג מהרש\"א לב\"ב שבהערה הבאה."],["2469","55","ב\"ב עה, א. סנהדרין ק, א."],["2470","56","אמ\"ב שם פפ\"ט. אוה\"ת שם ע' תרנג. תערב-ג."],["2471","57","ראה בארוכה במכתב דוא\"ו תשרי תשל\"ח (לקו\"ש חי\"ד ע' 477 ואילך). <i>וש\"נ</i>."],["2472","58","זח\"ב קמה, ב. ועוד."],["2473","59","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201301\" data-slug=\"likkutei-sichot\" data-id=\"1300201301\">לקו\"ש ח\"כ ע' 288</a> הערה *&lt;65&gt;."],["2474","60","<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201008\" data-slug=\"likkutei-sichot\" data-id=\"1300201008\">לקו\"ש שם ע' 8-287</a>."],["2475","61","נוסח התפלה דשבת (נשמת). וראה בהמצויין ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201303\" data-slug=\"likkutei-sichot\" data-id=\"1300201303\">לקו\"ש שם ע' 290</a> הערה 83."],["2476","62","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370510\" data-slug=\"torah-or\" data-id=\"3901370510\">תו\"א קיד, ב</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380807\" data-slug=\"likkutei-torah\" data-id=\"4001380807\">לקו\"ת ראה כב, סע\"ד</a>. ד\"ה אדון עולם תש\"ג פ\"ה. ובכ\"מ."],["2477","63","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">לקו\"ת שה\"ש כד, סע\"א</a> ואילך."],["2478","64","זח\"ג צ, ב."],["2479","65","ראה זהר שם עג, א."]]],[1500360037,"<h3>בס\"ד. ש\"פ וירא, כ\"ף מרחשון ה'תשל\"ז<sup data-n=\"2480\">*</sup></h3>\n<b>וה'</b> אמר המכסה אני מאברהם גו' ואברהם היו יהי' לגוי גדול גו' כי ידעתיו למען אשר יצוה גו' ושמרו דרך ה' לעשות צדקה ומשפט גו'<sup data-n=\"2481\">1</sup>. ומדייק בזה בעל יום ההולדת במאמרו ד\"ה זה דשנת תרס\"ז (בהמשך תרס\"ו<sup data-n=\"2482\">2</sup>), הרי דרך הוי' זהו תומ\"צ<sup data-n=\"2483\">3</sup>, וא\"כ מה מוסיף הכתוב בלעשות צדקה גו' (ענין המצוות<sup data-n=\"2484\">4</sup>) על ושמרו דרך הוי'. ומבאר שם<sup data-n=\"2485\">5</sup>, דדרך הוי' היא המשכה מלמעלה למטה, וצדקה ומשפט היא העבודה בבחי' מלמטה למעלה, העבודה דאור חוזר. [ועפ\"ז מבואר שם<sup data-n=\"2486\">6</sup> גם השייכות דושמרו דרך הוי' לעשות צדקה ומשפט למ\"ש לפנ\"ז והוי' אמר המכסה אני מאברהם גו'].\n<b>והנה</b> הפסוק כי ידעתיו גו' ושמרו דרך הוי' לעשות צדקה ומשפט נתבאר בהמשך הנ\"ל בד\"ה כי ידעתיו דשנת תרס\"ו<sup data-n=\"2487\">7</sup> (מאמר דש\"פ וירא הראשון שבההמשך), ובמאמר זה (מאמר דש\"פ וירא השני שבההמשך) מבאר הפסוק באופן אחר, נוסף על זה שמאמר הראשון מתחיל בפסוק כי ידעתיו ומאמר השני מתחיל בפסוק והוי' אמר המכסה אני גו', הנה גם בפסוק כי ידעתיו גופא, במאמר השני מפרש באופן אחר, דבמאמר הראשון מביא שני פירושים בכי ידעתיו, פירוש התרגום<sup data-n=\"2488\">8</sup> שידעתיו הוא לשון ידיעה, ארי גלי קדמי, ופירוש רש\"י שידעתיו הוא לשון חיבה. ומבאר שם<sup data-n=\"2489\">9</sup>דידעתיו לשון ידיעה הו\"ע רצון העצמי (דזהו ארי גלי קדמי, כי הרצון הוא בהתגלות), וידעתיו לשון חיבה הו\"ע תענוג העצמי, משא\"כ במאמר השני&lt;5&gt; מפרש<sup data-n=\"2490\">10</sup> ידעתיו לשון חיבה, שחיבב אותו בבחי' תענוג העצמי. ועוד חילוק בין שני המאמרים בהפירוש דושמרו דרך הוי' לעשות צדקה ומשפט. דבמאמר הראשון משמע (כפשטות לשון הכתוב, וכמבואר גם בכמה דרושים) דלעשות צדקה ומשפט הוא הפירוש דושמרו דרך הוי'<sup data-n=\"2491\">11</sup>, או שצדקה ומשפט הוא פרט בדרך הוי'. ויש לומר שדרך הוי' (לשון יחיד) היא התורה (בחינת כלל שלמעלה מהתחלקות), ומזה נמשך לעשות צדקה<sup data-n=\"2492\">12</sup>, עשיית המצוות (רמ\"ח אברין דמלכא<sup data-n=\"2493\">13</sup>, אברים פרטים)<sup data-n=\"2494\">14</sup>. ובמאמר זה (מאמר דש\"פ וירא השני שבההמשך) מבאר דלעשות צדקה גו' (עם היות שבא בהמשך לושמרו דרך הוי') הוא לא פירוש או פרט בדרך הוי' אלא שהוא ענין נוסף. דלאחרי ושמרו דרך הוי', המשכה מלמעלה למטה, באים אח\"כ<sup data-n=\"2495\">15</sup> לעבודה נעלית יותר, לעשות צדקה, עבודה מלמטה למעלה.\nב) <b>ויובן</b> כ\"ז ע\"פ המבואר בד\"ה זכור תרע\"ח<sup data-n=\"2496\">16</sup> לבעל יום ההולדת (עה\"פ ושמרו דרך הוי'), ובארוכה בביאורי הזהר לאדמו\"ר האמצעי<sup data-n=\"2497\">17</sup> (עה\"פ<sup data-n=\"2498\">18</sup> כי ישרים דרכי הוי') ובכ\"מ<sup data-n=\"2499\">19</sup>, דענין דרך למעלה הוא בדוגמת דרך כפשוטו (בגשמיות), שהוא ממוצע שמחבר שני מקומות שמצד עצמם הם רחוקים זמ\"ז בתכלית. וכמו דרך המלך הנמשך והולך מעיר המלוכה מקום מושב המלך לכל מרחבי המדינה (שעל ידו מגיעים לכל העיירות הגדולות), וממנו מסתעפים עוד דרכים ונתיבות שעל ידם יכולים להגיע לעיירות הקטנות וכו' עד לפינה הכי נדחת, דהריחוק שבין עיירות הקטנות ומכש\"כ פינה הנדחת לעיר הבירה מקום מושב המלך הוא נוסף על הריחוק במקום גם ריחוק במעלה, ועד לריחוק שבאין ערוך, וע\"י אמצעות הדרך נעשה קישור וחיבור דפינה הנדחת עם מקום מושב המלך. וזהו מה שהקו הנמשך מאוא\"ס נקרא בשם דרך, כי הקו הוא הממוצע שעל ידו נמשך מאוא\"ס לעולמות, דנוסף על זה שהתהוות העולמות(המשכת אוא\"ס להוות את העולמות) הוא ע\"י אמצעות הקו [דענין זה הוא ע\"י חיצוניות הקו, דשרשו הוא ממל' דא\"ס], הרי ע\"י הקו נעשה גם המשכת הגילויים דאוא\"ס בעולמות [דענין זה הוא ע\"י פנימיות הקו, דשרשו הוא מת\"ת הנעלם].\nג) <b>ועפ\"ז</b> מבאר בעל יום ההולדת בד\"ה זכור הנ\"ל<sup data-n=\"2500\">20</sup> זה שהתומ\"צ נק' דרך הוי', כי ענין תומ\"צ הוא לאתקנא רזא דשמי'<sup data-n=\"2501\">21</sup>, המשכת בחי' שמו הגדול (שם הוי'), שהוא הגילוי דעצמות אוא\"ס (בחי' ת\"ת הנעלם שלמעלה מבחי' מל' דא\"ס). ולכן נק' דרך הוי', הדרכים שעל ידם נמשך בעולם הגילוי דשם הוי', שמו הגדול. ועי\"ז נשלמה הכוונה דדירה בתחתונים<sup data-n=\"2502\">22</sup>, הגילוי דעצמות אוא\"ס (שלמעלה מבחי' סובב וממלא) למטה בתחתונים, בתחתון שאין<sup data-n=\"2503\">23</sup> תחתון למטה ממנו. ומבאר שם<sup data-n=\"2504\">24</sup>, דענין דירה בתחתונים הוא כמשל אדם הדר בבית חבירו, שכל עצמותו כמו שהוא דר בביתו הוא דר בבית חבירו. ויש לומר, שהכוונה בהמשל דאדם הדר בבית חבירו, הוא לבאר, דענין דירה בתחתונים הוא לא באופן שמצד הגילוי דאוא\"ס בהתחתון נעשה בו זיכוך ועלי' (באופן שמתבטל ה\"תחתון\" שבו), כי אם, שגם לאחרי הגילוי הוא נשאר תחתון<sup data-n=\"2505\">25</sup>, ואעפ\"כ נמשך בו הגילוי דעצמות אוא\"ס. דזהו תוכן המשל דאדם הדר בבית חבירו, שגם לאחרי שהוא דר שם הבית הוא בית חבירו, ואעפ\"כ הוא דר שם בכל עצמותו כמו שהוא דר בביתו.\nד) <b>והנה</b> לאחרי זה ממשיך בהמאמר (ד\"ה זכור הנ\"ל<sup data-n=\"2506\">26</sup>), דכמו שדרך כפשוטו משמש לא רק להליכה אלא גם לחזרה<sup data-n=\"2507\">27</sup>, עד\"ז הוא גם בדרך הוי', דאמיתית ענינו הוא שהוא באופן כזה שעל ידו נעשה לא רק ההמשכה מלמעלה למטה (ענין הליכה), אלא גם העלאת התחתון, שיהי' כלי לההמשכה<sup data-n=\"2508\">28</sup>. ושני ענינים אלו (ההמשכה מלמעלה והעלאת המטה) נעשים על ידי לימוד התורה וקיוםהמצוות<sup data-n=\"2509\">29</sup>. ע\"י לימוד התורה נעשה ההמשכה דעצמות אוא\"ס (דהחכמה דתורה היא מבחי' החכמה דעצמות א\"ס) בשכל האדם (שכל אנושי שמלובש במוח גשמי), ובפרט כשלומד היטב בעיון שכלו שאז היא מתאחדת עמו ביחוד נפלא שאין יחוד כמוהו<sup data-n=\"2510\">30</sup>, ועד שנקראת על שמו<sup data-n=\"2511\">31</sup>. ובירור והעלאת התחתון נעשה ע\"י מעשה המצוות, ובפרט כשמעשה המצוות הוא באופן דאתכפיא, מעשה מלשון כפי'<sup data-n=\"2512\">32</sup>. וזהו ושמרו דרך הוי' לעשות צדקה גו', דאמיתית ענין הדרך שמשמש לא רק להליכה (המשכה מלמעלה) אלא גם לחזרה (בירור והעלאת התחתון) הוא שנוסף ללימוד התורה יש גם עשיית צדקה, דכל המצוות נק' בשם צדקה<sup data-n=\"2513\">33</sup>. ומוסיף צדקה ומשפט<sup data-n=\"2514\">34</sup>, דעשיית הצדקה (צדקה כפשוטה) צ\"ל במשפט, שישפוט את עצמו מהמותרות ויחשוב היטב מה שהוא מוכרח לנפשו וכל השאר יתן לצדקה. ועד\"ז הוא בכל המצוות (שנק' בשם צדקה, כנ\"ל) שקיומם צ\"ל באופן דמשפט. ומוסיף לעשות (צדקה ומשפט), שגם זה (שהצדקה היא באופן דמשפט) אינו מספיק עדיין, וצריך להיות באופן דאתכפיא, מעשה מלשון כפי'. ועי\"ז נעשה בירור והעלאת התחתון, שנעשה כלי להגילוי שלמעלה.\nה) <b>והנה</b> העילוי שבבירור והעלאת התחתון, מובן מהמאמר (ד\"ה זכור הנ\"ל) שיש בזה ב' ענינים. א' שזה נוגע לההמשכה שלמעלה. וכמ\"ש במאמר הנ\"ל&lt;26&gt; דכמו שבדרך כפשוטו באם א\"א לילך בו בחזרה אזי אינו נקרא דרך (לא רק לגבי המקום שבא לשם, אלא) גם לגבי המקום שהלך משם, דכשלא ישנה העלי' (שהתחתון אינו כלי לההמשכה), אין ההמשכה אמיתית. ויש לומר הביאור בזה, דאמיתית ענין ושלימות ההמשכה (שאין בה הגבלה) היא, דלא רק שהיא נמשכת בכל מקום גם במקום הכי תחתון, אלא שהיא נמשכת וחודרת בכל חלקי המקום עד שמתעצמת עמו. שזה (ההתעצמות) הוא דוקא כשהתחתון הוא כלי להגילוי. דהגם שמצד למעלה אפשר להיות ההמשכה גם בתחתון שאינו כלי, דמי<sup data-n=\"2515\">35</sup> יאמר לו מה תעשה<sup data-n=\"2516\">36</sup>, הרי בנוגע להתחתון, מכיון שמצדו אינו כלי ראוי לההמשכה, אינו מתעצם עם האור<sup data-n=\"2517\">37</sup>, ובמילא חסר גם בההמשכה כנ\"ל. ועוד ענין בבירור והעלאת התחתון<sup data-n=\"2518\">38</sup>, ובפרט כשהבירורהוא באופן דאתכפיא, שזה דוקא מגיע בהעצמות. וזהו\"ע מעשה גדול<sup data-n=\"2519\">39</sup>, כי מעשה מלשון כפי' (בירור התחתון) מגיע בהעלם העצמי<sup data-n=\"2520\">40</sup> שלמעלה מכל ההמשכות והגילויים<sup data-n=\"2521\">41</sup>.\nו) <b>ועפ\"ז</b> יש לבאר תוכן הפנימי של החילוקים דהמאמרים דש\"פ וירא בהמשך תרס\"ו. דבמאמר הראשון מבאר ענין המצוות, זה שע\"י קיום המצוות נמשכים ענינים הכי נעלים, רצון עצמי ותענוג עצמי. היינו שהעילוי דעבודת המטה הוא שעי\"ז נעשה ההמשכה מלמעלה וגם ענין בירור התחתון הוא שעי\"ז היא השלימות דההמשכה. ולכן מפרש (כפשטות לשון הכתוב) דלעשות צדקה ומשפט הוא פירוש ופרט בדרך הוי', ההמשכה מלמעלה. ולשנה הבאה במאמר השני מבאר העילוי דמעשה המצוות (עבודת המטה) כמו שהוא מצד עצמו<sup data-n=\"2522\">42</sup>, בדוגמת הגילוי דלעתיד שאז תתגלה מעלת המעשה, מעשה גדול, לא רק זה שהמעשה מעורר וממשיך את אור הבל\"ג כמו שהוא למעלה מהתלבשות בחכמה (תלמוד), אלא גם העילוי דהמעשה גופא, שהוא מגיע בהעלם העצמי<sup data-n=\"2520\">40</sup> (שלמעלה גם מאור הבל\"ג שנמשך על ידו)<sup data-n=\"2521\">41</sup>. ולכן מפרש דלעשות צדקה ומשפט הוא (לא פרט וביאור בדרך הוי', כ\"א) ענין נוסף (שבא לאחרי וע\"י ושמרו דרך הוי')<sup data-n=\"2523\">43</sup>. וזהו מה שמאמר זה מתחיל בפסוק והוי' אמר המכסה אני, ומבאר דהמכסה אני הוא בחי' העלם העצמי דא\"ס, ופירוש המכסה אני מאברהם הוא שלאברהם נתגלה בחי' זו, דע\"י עבודתו בבחי' אור חוזר מלמטה למעלה, וגם יצוה את בניו ואת ביתו אחריו גו' לעשות צדקה ומשפט, לכן נתגלה לו בחי' העלם העצמי. [ואומר על זה המכסה בתמי'<sup data-n=\"2524\">44</sup>, כי מצד העבודה שלו (בבחינת אור חוזר) אין שייך שלא יתגלה לו בחינה זו]. ומכיון שבמאמר זה מדובר בענין הגילוי דהעלם העצמי (המכסה אני), לכן, גם בפסוק כי ידעתיו גו' מפרששידעתיו הוא לשון חיבה שחיבב אותו בבחי' תענוג העצמי [דגילוי תענוג העצמי הוא נעלה יותר מגילוי הרצון, שלכן גילוי הרצון יש גם עכשיו משא\"כ גילוי התענוג יהי' רק לעתיד<sup data-n=\"2525\">45</sup>], כי ע\"י המשכת וגילוי העלם העצמי, גם הגילויים הם באופן נעלה יותר<sup data-n=\"2526\">46</sup>.\n<b>והנה</b> שני ענינים אלו דושמרו דרך הוי' (המשכה מלמעלה למטה) לעשות צדקה ומשפט (עבודה מלמטה למעלה) ישנם בכאו\"א מישראל, במשך כל הדורות. דנוסף על זה שכל עניני התורה הם נצחיים<sup data-n=\"2527\">47</sup>, ובפרט הענינים דמעשה אבות סימן ונתינת כח לבנים<sup data-n=\"2528\">48</sup>, הרי בנוגע לענין זה אומר בפירוש אשר יצוה את בניו ואת ביתו אחריו, עד סוף כל הדורות. וציווי זה (שאברהם מצוה את בניו גו') הוא נתינת כח מיוחד (נוסף על הנתינת כח שמצד מעשה אבות) לכל אחד מישראל על שתי עבודות הנ\"ל.\nז) <b>ויש</b> לקשר זה עם הפסוק (בתהלים קאַפּיטל<sup data-n=\"2529\">49</sup> קטז, הקאַפּיטל דבעל יום ההולדת<sup data-n=\"2530\">50</sup> דשנה שעברה<sup data-n=\"2531\">51</sup>) אתהלך לפני הוי' בארצות החיים<sup data-n=\"2532\">52</sup>, ארצות לשון רבים, ומבואר בתו\"א<sup data-n=\"2533\">53</sup> שהם (בכלל) ב' ארצות, עלמא דאתכסיא ועלמא דאתגליא, דב' ארצות אלו הם המשכה מלמעלה למטה והעלאה מלמטה למעלה. ויש לבאר זה בב' אופנים. א' שעלמא דאתכסיא הו\"ע העלאה מלמטה למעלה (דעלי' למעלה הו\"ע של התעלמות) ועלמא דאתגליא (ענין הגילוי וירידה) הו\"ע המשכה מלמעלה למטה. וע\"פ המבואר בתו\"א שם שעלמא דאתכסיא הוא בחי' לאה (מחשבה) ועלמא דאתגליא הוא בחי' רחל (דיבור), יש לומר, שעלמא דאתכסיא בעבודת האדם הוא לימוד התורה, שעיקר ענינה הוא הבנה והשגה (מחשבה)<sup data-n=\"2534\">54</sup>, ועלמא דאתגליא הוא קיום המצוות בדיבור ומעשה. ועפ\"ז, עלמא דאתכסיא הוא המשכה מלמעלה למטה ועלמא דאתגליאהוא העלאה מלמטה למעלה, כנ\"ל בארוכה שתורה היא המשכה מלמעלה למטה ומצוות הם העלאה מלמטה למעלה.\nח) <b>וע\"י</b> העבודה דאתהלך לפני הוי' בארצות החיים, באים לתוכן הקאַפּיטל דבעל יום ההולדת&lt;50&gt; דשנה זו<sup data-n=\"2535\">55</sup>, הללו את הוי' כל גוים גו' כי גבר עלינו חסדו גו', שגם שני ענינים אלו הו\"ע העלאה והמשכה. הללו גו' כל גוים גו' הו\"ע בירור זיכוך והעלאת העולם<sup data-n=\"2536\">56</sup>, עד שגם הגוים והאומים מהללים ומשבחים את הוי'. וגבר עלינו חסדו גו' הו\"ע המשכה מלמעלה למטה, דנוסף על זה שחסד (בכלל) הוא המשכה מלמעלה למטה, הנה החסד (ההמשכה) הוא בתוקף ובהתגברות, גבר גו' חסדו. והוא, שההמשכה היא מלמעלה מעלה ביותר, קצה הכי עליון, וביחד עם זה באה ההמשכה למטה מטה, עד לתחתון שאין תחתון למטה ממנו, וזהו מה שממשיך בכתוב ואמת הוי' לעולם, דאמת הוי' היא בחינה נעלית ביותר [וי\"ל שזהו\"ע מ\"ש הרמב\"ם<sup data-n=\"2537\">57</sup> שכל הנמצאים לא נמצאו אלא מאמיתת המצאו, דאמיתת המצאו שייך לשם הוי', שלכן מביא ברמב\"ם (בהמשך הענין שם)<sup data-n=\"2538\">58</sup> הפסוק<sup data-n=\"2539\">59</sup> והוי' אלקים אמת], ואעפ\"כ הוא נמשך לעולם, לעולם הזה הגשמי, ובזה גופא גם לגוים ואומים. אמנם לאחרי כל העילוי דהמשכה זו, נאמר זה בכתוב (לא בתור ענין בפ\"ע, אלא) בתור טעם (כי) על הללו גו' כל גוים. דתכלית הכוונה של ההמשכה היא שעי\"ז יהי' אח\"כ בירור ועליית המטה, שגם הגוים גופא יהללו את הוי'. וע\"ד העילוי דלעשות צדקה ומשפט שבא ע\"י קדימת דרך הוי'<sup data-n=\"2540\">60</sup>. וסיום וחותם המזמור הוא הללוי', דאמיתית ההילול יהי' בשירה העשירית<sup data-n=\"2541\">61</sup> לע\"ל, שאז יתגלה העילוי דהעלאת התחתון, מעשה גדול, בביאת משיח צדקנו במהרה בימינו ממש.\n**********",[["2480","*","יצא לאור ב<b>קונטרס כ\"ף מרחשון – תשמ\"ז</b>, \"לקראת ש\"ק פ' וירא, כ\"ף מרחשון הבעל\"ט, יום הולדת כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע . . <i>ערש\"ק וירא כ\"ף מ\"ח ה' </i><b>ת</b><i>הא </i><b>ז</b><i>ו </i><b>ש</b><i>נת </i><b>מ</b><i>שיח</i>\"."],["2481","1","פרשתנו יח, יז-יט."],["2482","2","הוצאת קה\"ת – ע' שצח."],["2483","3","כמובן בפשטות (שלכן לא הוצרך רש\"י לפרש הפירוש ד\"ללכת בכל דרכיו\" (עקב י, יב) – כי זה מובן מעצמו*). וכדמוכח גם ממ\"ש (הושע בסופו) כי ישרים דרכי הוי', שקאי על דברי תורה (ב\"ב פט, א וברשב\"ם שם. שהש\"ר פ\"א, ב עה\"פ ישקני מנשיקות פיהו בסופו), או על מצוות (נזיר כג, א. הוריות י, ב). וראה זהר ח\"א וישלח (קעה, ב) \"ואינון ארחין ושבילין דאורייתא\". ביאוה\"ז לאדהאמ\"צ שם (יט, ב ואילך) ולהצ\"צ (כרך ב ע' תשד ואילך). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600451\" data-slug=\"or-hatorah-hb\" data-id=\"8316600451\">אוה\"ת נ\"ך</a> עה\"פ הושע שם (ע' תנא ואילך)."],["2484","4","דצדקה נק' בשם מצוה (סתם) – <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז (מח, ב</a>). וכן כל המצוות נקראות בשם צדקה, כדלקמן סעיף ד."],["2485","5","בסיומו – ע' תח."],["2486","6","נעתק לקמן סעיף ו."],["2487","7","ע' סח."],["2488","8","אונקלוס עה\"פ. וגם בתיב\"ע עה\"פ: ארום גלי קדמי."],["2489","9","בסיומו – ע' עז.\n*) <i>ומה שפירש רש\"י בס\"פ עקב (יא</i>,<i> כב) </i>\"<i>ללכת בכל דרכיו – הוא רחום ואתה תהא רחום כו'</i>\"<i> – יש לומר</i>,<i> כי לפני </i>\"<i>ללכת בכל דרכיו</i>\"<i> דס\"פ עקב כתיב </i>\"<i>שמור תשמרון את כל המצוה הזאת גו'</i>\",<i> דמזה מוכח</i>,<i> שב</i>\"<i>ללכת בכל דרכיו</i>\"<i> מוסיף עוד ענין</i>.\n<i>ועד\"ז י\"ל במ\"ש הרמב\"ם (הל' דיעות פ\"א ה\"ה) </i>\"<i>ומצווין אנו ללכת בדרכים האלו הבינונים </i>. .<i> שנאמר (תבוא כח</i>,<i> ט) והלכת בדרכיו</i>\"<i> – כי לפני </i>\"<i>והלכת בדרכיו</i>\"<i> כתיב </i>\"<i>כי תשמור את מצוות ה' אלקיך</i>\".<i> והא שלא פירש רש\"י בפ' תבוא – יש לומר שסומך על מה שפירש כבר לפנ\"ז בס\"פ עקב</i>."],["2490","10","אף שאין זה פירוש הפשוט דתיבת \"ידעתיו\", אלא שרש\"י מוכרח לפרש כן כי \"אם תפרשהו כתרגומו יודע אני . . אין למען נופל על הלשון\"."],["2491","11","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370283\" data-slug=\"torah-or\" data-id=\"3901370283\">וכמבואר בכ\"מ, ד</a>\"לעשות צדקה\" הוא הדרך ומבוא שיהי' גילוי שם הוי' (תו\"א בשלח סג, ב. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381306\" data-slug=\"likkutei-torah\" data-id=\"4001381306\">לקו\"ת שה\"ש מד, ג</a>. ד\"ה זכור תרע\"ח ס\"ע קצ. ד\"ה כי ידעתיו תרפ\"ו ס\"ע קיא. ועוד)."],["2492","12","להעיר מסה\"מ תרע\"ח ע' סג, ש\"דרך הוי'\" הוא כוונת המצוות ו\"לעשות צדקה גו'\" הוא מעשה המצוות. ובהמשך הענין שם \"כמו שהוא במעשה המצוות לגבי כוונת המצוות כן הוא במצוות לגבי תורה\"."],["2493","13","ראה תקו\"ז תיקון ל' (עד, סע\"א). הובא ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. רפכ\"ג. ועוד."],["2494","14","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380803\" data-slug=\"likkutei-torah\" data-id=\"4001380803\">ראה זח\"ג קכט, א</a> (באד\"ר) \"חד ארחא כו' דנהיר לתרי\"ג ארחין\". וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380360\" data-slug=\"likkutei-torah\" data-id=\"4001380360\">לקו\"ת ראה כא, ד</a> [ועד\"ז בד\"ה כי ידעתיו תרכ\"ז (ע' כו), פר\"ת (ע' קלט)] שתורה היא \"חד ארחא\" [\"אור אחד . . למעלה מבחי' התחלקות\"], והמצוות (אורות המתחלקים בכלים, שלכל כלי אור בפ\"ע) מתחלקים לתרי\"ג (תרי\"ג ארחין). ולהעיר גם מלקו\"ת במדבר יג, א-ב. <i>ובפשטות</i>: התורה – אחת המצוות – תרי\"ג."],["2495","15","ועפ\"ז מובן ההמשך ד\"לעשות צדקה גו'\" ל\"ושמרו דרך הוי'\". וראה לקמן הערה 43."],["2496","16","סה\"מ תרע\"ח ע' קצג."],["2497","17","ר\"פ וישלח (יט, ב ואילך)."],["2498","18","הושע בסופו."],["2499","19","ביאוה\"ז להצ\"צ וישלח (כרך ב) ע' תשד ואילך. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600453\" data-slug=\"or-hatorah-hb\" data-id=\"8316600453\">אוה\"ת נ\"ך ס\"ע תנג</a> ואילך. שה\"ש כרך ב ע' תרפ ואילך. המשך ר\"ה תש\"ו פ\"ח ואילך. ועוד."],["2500","20","ע' קצ."],["2501","21","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370224\" data-slug=\"torah-or\" data-id=\"3901370224\">תו\"א שמות מט, ד</a> ואילך. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370303\" data-slug=\"torah-or\" data-id=\"3901370303\">יתרו סז, ד</a> ואילך. אוה\"ת שמות ע' רט ואילך. שם כרך ז ע' ב'תפה. כרך ח ס\"ע ב'תתכד ואילך. יתרו ע' תתלג ואילך. שם ע' תתמד ואילך. ועוד."],["2502","22","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["2503","23","לשון אדה\"ז בתניא שם."],["2504","24","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770312\" data-slug=\"or-hatorah-hb\" data-id=\"8316770312\">ע' קצג</a>. וראה גם אוה\"ת שה\"ש שם ע' תרפ. סה\"מ תרס\"ב ע' שלה."],["2505","25","וי\"ל השייכות דענין זה לדרך הוי', כי הדרך מקשר גם פינה הנדחת, כנ\"ל בפנים.\nולהעיר גם מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381306\" data-slug=\"likkutei-torah\" data-id=\"4001381306\">לקו\"ת שה\"ש מד, ג</a> דענין דרך הוי' הוא \"להיות הולך ומתגלה גם למטה בעולם העשי' עולם החושך\", די\"ל הפירוש שגם אח\"כ נשאר \"עולם החושך\"*, ואעפ\"כ נמשך בו הגילוי דהוי'."],["2506","26","ע' קצג ואילך."],["2507","27","ראה גם ביאוה\"ז לאדהאמ\"צ שם יט, ג. להצ\"צ שם ע' תשז. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316600456\" data-slug=\"or-hatorah-hb\" data-id=\"8316600456\">אוה\"ת נ\"ך ע' תנו</a>. ועוד."],["2508","28","ומה שנק' \"בית חבירו\" ו\"עולם החושך\" (ראה לעיל הערה 25) – יש לומר (וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151089\" data-slug=\"likkutei-sichot\" data-id=\"1300151089\">לקו\"ש חט\"ו ע' 89</a> בהערות), כי גם ענין עליית התחתון מלמטלמ\"ע, כולל גם העלי' שתהי' לע\"ל (שאז תהי' בתכלית השלימות), הוא (לא שאז יתבטל הצמצום, כי אם) שחושך הצמצום גופא יהפך לאור (המשך תער\"ב ח\"ב ע' תתקל. שם ע' תתקלב). ומכיון שענין זה (הפיכת החושך לאור) א\"א להיות מצד הגדרים ד\"אור\" ו\"חושך\" ורק בכח העצמות – נמצא, שמצד הגדרים ד\"עולם\", יהי' גם אז \"תחתון\" – \"בית חבירו\", \"עולם החושך\". ועצ\"ע.\n*) <i>ראה לקמן הערה 28</i>."],["2509","29","ראה לקו\"ת שמע\"צ פד, ב. אוה\"ת ואתחנן ד\"ה ושננתם. ד\"ה ויגש תרע\"ח (הובא גם בד\"ה זכור הנ\"ל). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300091065\" data-slug=\"likkutei-sichot\" data-id=\"1300091065\">לקו\"ש ח\"ט ע' 65</a>. ועוד."],["2510","30","<a class=\"ft-cite\" href=\"#/read/tanya/3401310010\" data-slug=\"tanya\" data-id=\"3401310010\">תניא פ\"ה</a>."],["2511","31","ע\"ז יט, א. וראה קידושין לב, סע\"א ואילך."],["2512","32","ד\"ה ויגש הנ\"ל ע' קכא. שם ע' קכד ואילך. ד\"ה זכור הנ\"ל ע' קצב. מאמרי אדהאמ\"צ ויקרא ח\"ב ע' תשסא ואילך. סה\"מ תרל\"ו ח\"ב ע' רפט. תרצ\"ט ע' 191. ועוד."],["2513","33","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו\"א מקץ לח, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370191\" data-slug=\"torah-or\" data-id=\"3901370191\">מב, ג</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381306\" data-slug=\"likkutei-torah\" data-id=\"4001381306\">לקו\"ת שה\"ש מד, ג</a>. מאמרי אדהאמ\"צ ויקרא ח\"ב ס\"ע עדרת. וש\"נ. ס' המאמרים: תרע\"ח ד\"ה ויגש (ע' קכא), ד\"ה זכור (ע' קצ). וראה גם ד\"ה כי ידעתיו תרכ\"ז (ע' כב. שם ע' כד ואילך), פר\"ת (ע' קלג. שם ע' קלז ואילך), תרפ\"ו (ע' קג. שם ע' קיא. קיג). ובכ\"מ."],["2514","34","ראה גם <a class=\"ft-cite\" href=\"#/read/torah-or/3901370283\" data-slug=\"torah-or\" data-id=\"3901370283\">תו\"א בשלח סג, סע\"ב</a>. ד\"ה נ\"ח תרמ\"ג ס\"ג (ע' מו-מז). ד\"ה אשר ברא תרפ\"ט ס\"ד (סה\"מ קונטרסים ח\"א כג, ב. סה\"מ תרפ\"ט ע' 90). ד\"ה ויאמר גו' לך תש\"ב ס\"ד (ע' 53). ובכ\"מ."],["2515","35","קהלת ח, ד."],["2516","36","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380829\" data-slug=\"likkutei-torah\" data-id=\"4001380829\">לקו\"ת פ' ראה כח, ב</a> \"שעכ\"ז נמשך בו (אף שלא נזדכך) גילוי אור עליון ממש, כי הוא ית' כל יכול\"."],["2517","37","וכמ\"ש בלקו\"ת שם, ש\"מ\"מ אין הגילוי אור מתייחד כ\"כ עם הכלי\"."],["2518","38","כ\"מ בד\"ה זכור תרע\"ח (ע' קצד). ובפרט מזה שמציין שם לד\"ה ויגש תרע\"ח – עיי\"ש ע' קכד."],["2519","39","קידושין מ, ב."],["2520","40","כ\"ה הלשון (העלם העצמי) בד\"ה ויגש הנ\"ל ע' קכה."],["2521","41","ד\"ה ויגש הנ\"ל ע' קכד."],["2522","42","להעיר שהקביעות דיום ההולדת (כ' מרחשון) בשנת תרס\"ו היתה בש\"ק פ' וירא אליו הוי' – גילוי מלמעלה*, והקביעות דיום ההולדת בשנת תרס\"ז היתה ביום ה' פ' חיי שרה** – כמה ימים דעבודה כמו שהיא לאחרי הגילוי מלמעלה (ראה הערה הבאה) ד\"וירא אליו הוי'\".\nולהעיר גם מזה שבכל השנים (משנת תרנ\"ד עד שנת תרע\"ו) הי' אדמו\"ר נ\"ע בעל יום ההולדת בליובאַוויטש, מלבד בשנת תרס\"ז שהי' אז בחו\"ל, בוירצבורג (\"התמים\" חוברת ג ע' לא-לב). ואולי יש לומר, שגם ענין זה (שהי' אז בחוץ מליובאַוויטש) שייך לעבודת הבירורים, בירור והעלאת התחתון."],["2523","43","כי בכדי שיהי' בירור והעלאת התחתון (בשלימות) צ\"ל תחילה ההמשכה והגילוי מלמעלה (וע\"ד תלמוד שמביא לידי מעשה – ראה ד\"ה ויגש שם ע' קכד). ועפ\"ז תובן השייכות ד\"לעשות צדקה גו'\" ל\"ושמרו דרך הוי'\" גם להפירוש שבהמאמר דשנת תרס\"ז."],["2524","44","פרש\"י עה\"פ.\n*) <i>ולהעיר מהשייכות המיוחדת דבעל יום ההולדת ל</i>\"<i>וירא</i>\",<i> שעוד בהיותו ילד השתוקק לזה ועד לבכי' (</i>\"<i>היום יום</i>\"<i> ט' חשון</i>.<i> וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151129\" data-slug=\"likkutei-sichot\" data-id=\"1300151129\">לקו\"ש חט\"ו ע' 129</a> ואילך</i>.<i> וש\"נ)</i>.\n**) <i>להעיר שקביעות דכ' מרחשון (שהוא כמו הקביעות דיום א' דראש השנה) יכול להיות בד' ימים</i>;<i> ביום הש\"ק פ' וירא</i>,<i> ביום ב'</i>,<i> ביום ג' או ביום ה' (דפ' חיי שרה)</i>,<i> וכשהקביעות דכ' מ\"ח הוא ביום ה' – הוא ריבוי הכי גדול בימי העבודה שלאחרי הגילוי ד</i>\"<i>וירא</i>\"."],["2525","45","ד\"ה כי ידעתיו תרס\"ו ס\"ע עו."],["2526","46","וכמבואר שם (ד\"ה וה' אמר תרס\"ז בסופו) בענין ואברהם היו יהי' לגוי גדול ועצום גו'."],["2527","47","וראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310022\" data-slug=\"tanya\" data-id=\"3401310022\">תניא רפי\"ז</a>."],["2528","48","ראה תנחומא לך לך ט. ב\"ר פ\"מ, ו. רמב\"ן עה\"פ לך לך יב, ו. וראה שם יב, יו\"ד. תולדות כו, א. וישלח לב, ד."],["2529","49","כן הוא לשון הצ\"צ בכ\"מ (ולדוגמא: אוה\"ת נ\"ך כרך ב' ס\"ע א'יא)."],["2530","50","כידוע המנהג לומר הקאַפּיטל תהלים המתאים למספר שנותיו – מכתב כ\"ק מו\"ח אדמו\"ר, נדפס בקובץ מכתבים ע\"ד אמירת תהלים. אגרות-קודש כ\"ק אדמו\"ר מוהריי\"צ ח\"י ס\"ע נג. וענין זה שייך גם לאחר ההסתלקות – כמפורש ברשימה שבהערה הבאה. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051115\" data-slug=\"likkutei-sichot\" data-id=\"1300051115\">לקו\"ש ח\"ה ע' 103</a> ואילך. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201413\" data-slug=\"likkutei-sichot\" data-id=\"1300201413\">ח\"כ ע' 400</a> ואילך. סה\"מ י\"א ניסן ע' 1 ואילך. ועוד."],["2531","51","להעיר מרשימת כ\"ק מו\"ח אדמו\"ר מכ' מ\"ח תש\"ה (נדפסה בהוספות לסה\"מ פר\"ת ע' שנז), ש\"כל אחד מכ\"ק רבותינו . . יאמר דרוש ע\"פ דקאַפּיטל פ\"ד\" – דמזה מוכח, שגם הקאַפּיטל דשנה העברה שייך ליום ההולדת."],["2532","52","פסוק ט."],["2533","53","ויצא כב, ד. וראה גם אוה\"ת שם רטז, סע\"ב ואילך."],["2534","54","ד\"אם אינו מבין הפירוש, אינו נחשב לימוד <i>כלל</i>\" (הל' ת\"ת לאדה\"ז פ\"ב הי\"ג. שו\"ע אדה\"ז או\"ח ס\"נ ס\"ב).\nבהל' ת\"ת שם הי\"ב \"וכל מה שלומד בהרהור לבד ואפשר לו להוציא בשפתיו ואינו מוציא אינו יוצא בלימוד זה י\"ח מצות ולמדתם אותם וכמ\"ש לא ימוש ספר התורה הזה מפיך והגית בו וגו'\". אבל: (א) זהו בנוגע <i>מצות</i> ת\"ת, ש\"אינו יוצא בלימוד זה י\"ח <i>מצות</i> ולמדתם אותם\" (ולא לעצם הענין דלימוד התורה (וכמו שמדגיש בהלכה זו עצמה ש\"אינו <i>יוצא בלימוד</i> זה\"). משא\"כ כשאינו מבין \"אינו נחשב <i>לימוד כלל</i>\"). (ב) גםבנוגע למצות ת\"ת – מדייק אדה\"ז ש\"אינו יוצא י\"ח מצות <i>ולמדתם אותם</i>\", שהיא \"כמ\"ש לא ימוש גו' מפיך\", משא\"כ מצות \"והגית\" <i>שלאח\"ז</i> י\"ל שיוצא גם בלימוד זה – ראה בארוכה ליקוט פירושים וכו' לאגה\"ת פ\"א ע' סה הערה 83."],["2535","55","– תשל\"ז: תהלים קיז (א-ב) – כל הקאַפּיטל."],["2536","56","ובפרט לפמ\"ש ברשימות הצ\"צ לתהלים שם (יהל אור ע' תמז) שפסוק זה נאמר על \"אז אהפוך אל עמים שפה ברורה\" שיהי' לע\"ל (צפני' ג, ט), שאז יהי' שלימות הבירור – <i>אהפוך</i> אל עמים, אתהפכא."],["2537","57","הל' יסוה\"ת פ\"א ה\"א."],["2538","58","שם ה\"ד. וראה ד\"ה הללו את הוי' תשל\"א (לעיל ע' קפז), דכוונת הרמב\"ם במ\"ש \"הוא <i>שהנביא</i> אומר\" י\"ל שהיא להדגיש שזהו אמת נעלה כזה שא\"א לידע כלל בשכל רק \"<i>שהנביא</i> אומר\".\nויש לומר, דזהו גם מה שהרמב\"ם ממשיך \"והוא שהתורה אומרת כו'\", דיש דרגא באמת נעלית יותר שאינה מתגלית גם בנבואה, אלא \"<i>שהתורה</i> אומרת\"."],["2539","59","ירמי' י, י."],["2540","60","ראה לעיל סעיף ו ובהערה 43."],["2541","61","מכילתא עה\"פ בשלח טו, א. תנחומא בשלח יו\"ד. תרגום שה\"ש בתחלתו. וראה אוה\"ת שה\"ש בתחלתו."]]],[1500360038,"<h3>בס\"ד. אור ליום ב' פ' חיי שרה, כ\"ף מרחשון ה'תשמ\"ו<sup data-n=\"2542\">*</sup></h3>\n<b>ואשה</b> אחת מנשי בני הנביאים צעקה אל אלישע גו'<sup data-n=\"2543\">1</sup>, וידוע מאמר אדמו\"ר הזקן עה\"פ<sup data-n=\"2544\">2</sup> דאשה היא הנשמה, ונק' אשה אחת כי היא אחת עם הוי', מנשי בני הנביאים, כי נביאים מלשון ניב שפתיים<sup data-n=\"2545\">3</sup> הוא שמקבלים מבחי' דבר הוי' והנשמה היא כלי קיבול לקבל השגות וגילוי אלקות. ואלישע אותיות אלי שע הוא הקב\"ה. וזהו ואשה אחת גו' צעקה אל אלישע, שהנשמה צועקת להקב\"ה, עבדך אישי מת, אישי הוא אש יו\"ד, דהאהבה כרשפי אש שהי' אצלי להכלל ולהבטל בבחי' יו\"ד חכמה עילאה – מת, שעכשיו אין לי אהבה זו. והנושה בא לקחת את שני ילדי לו לעבדים, והנושה מלשון כי נשני אלקים<sup data-n=\"2546\">4</sup> קאי על נפש הבהמית שמשכחת אותי מאלקות, ושני ילדי הם האהבה והיראה [וכמבואר בתניא<sup data-n=\"2547\">5</sup> שהמדות נקראים בשם תולדות, ועיקרי המדות הם אהבה ויראה<sup data-n=\"2548\">6</sup>], וזהו והנושה בא לקחת את שני ילדי לו לעבדים, לאהבות זרות וליראות זרות. [דנוסף לזה שנה\"ב משכחת אותי מאלקות ורוצה <i>לבטל</i> ח\"ו את האהוי\"ר באלקות, היא רוצה לקחת את האהוי\"ר דנפש האלקית שיהיו עבדים לנה\"ב]. ויאמר אלי' אלישע גו' מה יש לך בבית, איזה כחות נשארו לך שאין לנה\"ב שליטה עליהם<sup data-n=\"2549\">7</sup>, ותאמר אין לשפחתך גו' כי אם אסוך שמן, שלא נשאר אצלה שום דבר מלבד עצם נקודת הנשמה. [ויש לומר<sup data-n=\"2550\">8</sup>, דשמן הוא חכמה<sup data-n=\"2551\">9</sup>, ואסוך שמן הוא בחינת החכמה שבנפש, שאין לנה\"ב שליטה עלי'<sup data-n=\"2552\">10</sup>]. ויאמר לכי שאלי לך כלים מן החוץ גו' כלים ריקים אל תמעיטי, שתעסוק בתורה ובמצוות<sup data-n=\"2553\">11</sup> שהם כלים לאור הוי'<sup data-n=\"2554\">12</sup>, ואף שהתומ\"צ שעוסקת בהם עכשיו הם כלים ריקים (בלי אהבה ויראה<sup data-n=\"2555\">13</sup>) מ\"מ אל תמעיטי בהם, ויצקת על כל הכלים האלה, להמשיך בהםהגילוי דעצם הנשמה [וע\"ד המבואר בתניא<sup data-n=\"2556\">14</sup> שקיום התורה ומצוותי' תלוי בזה שיזכור תמיד ענין מסירת נפשו לה', דמס\"נ הוא מצד עצם הנשמה<sup data-n=\"2557\">15</sup>]. וכשתעשה כן אזי את ובנייך תחיי בנותר, כיתרון האור הבא מן החושך<sup data-n=\"2558\">16</sup>. ועוד פירוש בכלים ריקים אל תמעיטי, שיתבונן הרבה<sup data-n=\"2559\">17</sup> איך שהוא כלי ריקן בלי דעת במוח ובלי דחילו ורחימו, ויתמרמר מאד על ריחוקו, ועי\"ז יאיר בו אור הנשמה. וכמאמר רב מתיבתא בג\"ע<sup data-n=\"2560\">18</sup> אעא דלא סליק בי' נהורא מבטשין לי' כו' גופא דלא סליק בי' נהורא דנשמתא מבטשין לי' וסליק בי' נהורא. ויתירה מזה שאור זה (שמאיר ע\"י המרירות מזה שהוא כלי ריקן) יש לו יתרון על האור כמו שהוא מצד עצמו, כיתרון האור הבא מן החושך דוקא. וזהו ואת ובנייך תחיי בנותר, את הוא עצם הנשמה ובנייך הם דחילו ורחימו שבכל נשמה – תחיי בנותר, כיתרון האור הבא מן החושך.\nב) <b>ויש</b> לומר, דיתרון האור הבא מן החושך (ואת ובנייך תחיי בנותר) להפירוש בכלים ריקים אל תמעיטי שיתבונן הרבה איך שהוא כלי ריקן, הוא נעלה יותר מיתרון האור (נותר) להפירוש בכלים ריקים אל תמעיטי שיעסוק בתורה ומצוות אף שהם בלי אהוי\"ר. דהנה ביתרון האור מן החושך, שני ענינים. יתרון האור בכדי <i>להאיר</i> את החושך. שבכדי להאיר במקום רחוק וחשוך ביותר, צריך לאור גדול ביותר<sup data-n=\"2561\">19</sup>. דכמו\"כ הוא גם בנוגע להיתרון (תחיי בנותר) שע\"י עסק התומ\"צ בלי אהוי\"ר, דזה שהוא עוסק בתומ\"צ הגם שאין לו אהוי\"ר, הוא מפני תוקף ההתקשרות שלו באלקות שמצד עצם הנשמה, שלמעלה מכחות הגלויים. ועוד ענין ביתרון האור מן החושך, שע\"י המרירות מהחושך המסתיר אורו ית', נמשך מבחינת ישת חושך סתרו<sup data-n=\"2562\">20</sup>, חושך שלמעלה מאור<sup data-n=\"2563\">21</sup> (למעלה גם מאור גדול שמאיר גם במקום חשוך ביותר). וזהו היתרון (תחיי בנותר) שע\"י ההתבוננות איך שהוא כלי ריקן, דע\"י המרירות מזה שהוא כלי ריקן (חושך), הוא מגיע לבחינת חושך שלמעלה מאור.\nג) <b>וביאור</b> הענין בפרטיות יותר, יובן ע\"פ מ\"ש בלקו\"ת<sup data-n=\"2564\">22</sup> דענין את ובנייך תחיי בנותר הוא ע\"ד מה שארז\"ל<sup data-n=\"2565\">23</sup> עה\"פ<sup data-n=\"2566\">24</sup> לשארית נחלתו, למי שמשים עצמו כשיריים. ומבאר שם<sup data-n=\"2567\">25</sup>, דשיריים הם המקיפים שלמעלה מהשתלשלות. דהאור שנמשך בעולמות (בפנימיות) הוא הארה בלבד, ועיקר האור (המקיפים) נשארלמעלה, שיריים. ובכדי להמשיך המקיפים, הוא ע\"י הביטול. וזהו למי שמשים עצמו כשיריים, דע\"י שמשים עצמו כשיריים כפשוטו, ביטול, עי\"ז דוקא הוא ממשיך המקיפים, שיריים. דכאשר עבודתו היא בבחינת מציאות, גם כשהעבודה היא בתכלית העילוי, ההמשכה שעל ידה היא אור השייך להשתלשלות (מציאות), ובכדי להמשיך השיריים דלמעלה (שלמעלה מבחינת מציאות) הוא דוקא ע\"י הביטול. [וכמבואר גם בתו\"א<sup data-n=\"2568\">26</sup> עה\"פ<sup data-n=\"2569\">27</sup> השמים כסאי והארץ הדום רגלי אי זה בית גו' ואל זה אביט אל עני ונכה רוח, דההמשכה שע\"י שמים וארץ שהם תורה (שמים) ומצוות (ארץ) הוא אור פנימי, ובכדי להמשיך המקיפים, אי זה בית גו', דבית הוא מקיף (ובמקיפים עצמם מקיף הרחוק), הוא ע\"י הביטול, עני ונכה רוח]. ומבאר בלקו\"ת שם, דזהו מה שארז\"ל<sup data-n=\"2570\">28</sup> עה\"פ ואת ובנייך תחיי בנותר עד שיחיו המתים, דנותר הוא מה שנשאר למעלה בבחינת מקיף, ובמקיפים עצמם הוא מקיף הרחוק, עתיק (דאריך הוא מקיף הקרוב ועתיק הוא מקיף הרחוק<sup data-n=\"2571\">29</sup>), וזהו תחיי בנותר עד שיחיו המתים, דתחיית המתים הוא ע\"י טלא דנטיף מעתיקא<sup data-n=\"2572\">30</sup>.\n<b>וזוהי</b> המעלה דענין תחיי בנותר שבא על ידי המרירות מזה שהוא כלי ריקן (פירוש השני בכלים ריקים אל תמעיטי) על הענין דתחיי בנותר שבא על ידי שעוסק בתורה ומצוות הגם שאין לו אהוי\"ר (פירוש הראשון בכלים ריקים אל תמעיטי), כי היתרון (נותר) בזה שעוסק בתומ\"צ גם כשאין לו אהבה ויראה הוא זה שאז קיום התומ\"צ שלו קשור עם כח המסירת נפש, דענין המסירת נפש הוא מצד עצם הנשמה שלמעלה מכחות הגלויים (אהוי\"ר). אבל מ\"מ, כיון שע\"י עסק התומ\"צ (גם כשקיום התומ\"צ הוא ע\"י שזוכר ענין מסירת נפשו לה') אינו מתבטל ממציאותו [שהרי זה שהוא מקיים תומ\"צ תלוי ברצונו, רצון (מציאות) האדם<sup data-n=\"2573\">31</sup>], הגילוי דעצם הנשמה שבזה הוא רק כמו ששייכת לכחות הגלויים [דע\"י שזוכר ענין מסירת נפשו לה' שמצד עצם הנשמה, הרצון שלו בתומ\"צ הוא בתוקף גדול]. ולכן, גם ההמשכה שנמשכת מלמעלה עי\"ז, הוא האור שלמעלה מהשתלשלות כמו שהוא שייך להשתלשלות, דבכללות הוא מקיף הקרוב, אריך. והיתרון שנעשה על ידי ההרגש והמרירות מזה שהוא כלי ריקן, מכיון שעי\"ז הוא מתבטל ממציאותו, נמשך עי\"ז הגילוי דעצם הנשמה כמו שהיא למעלה משייכות לכחות הגלויים. ועד\"ז הוא בההמשכה שנמשכת עי\"ז מלמעלה, דע\"י שמרגיש בעצמו שהוא כלי ריקן שאין בושום מעלה והוא כמו שיריים בעיניו (דבר המיותר, נותר), הענין דתחיי בנותר שעי\"ז הוא המשכת מקיף הרחוק, עתיק<sup data-n=\"2574\">32</sup>.\nד) <b>וצריך</b> להבין מ\"ש את ובנייך תחיי בנותר, שגם האהבה והיראה דהנשמה (בנייך) יחיו בנותר, דלכאורה, מכיון שנותר הוא מקיף, ובפרט להפירוש שנותר הוא מקיף הרחוק, איך שייך שיומשך ממנו חיות לכחות הפנימיים (אהבה ויראה). ויש לבאר זה ע\"פ מ\"ש אדמו\"ר (מהורש\"ב) נ\"ע בעל יום ההולדת במאמרו ד\"ה כי<sup data-n=\"2575\">33</sup> המצוה הזאת אשר אנכי מצוך היום לא נפלאת היא ממך ולא רחוקה היא<sup data-n=\"2576\">34</sup> (בספר המאמרים שלו שמכינים עתה לדפוס<sup data-n=\"2577\">35</sup>), דשני הלשונות נפלאת ורחוקה הם בעתיק ואריך. דפלא [שהוא לשון הפרשה והבדלה] הוא בעתיק, שנעתק ונבדל מהשתלשלות, וריחוק הוא באריך, דלשון ריחוק מורה שיש לו שייכות להדבר שהוא רחוק ממנו, וכמו אמרתי אחכמה והיא רחוקה ממני<sup data-n=\"2578\">36</sup>, דזה שאמרתי אחכמה הוא לפי שהחכמה שייכת אליו, ורק שהיא רחוקה ממנו<sup data-n=\"2579\">37</sup>. ומבאר שם, דמ\"ש כי המצוה הזאת גו' לא נפלאת היא ממך גו', ממך דוקא, הוא, כי כיון שהמצוות הם רצון העליון, רצון שלמעלה מטעם, הם בבחינת פלא וריחוק<sup data-n=\"2580\">38</sup>. ומכ\"ש מצות התשובה (דהמצוה הזאת קאי על מצות התשובה, כמ\"ש הרמב\"ן וכמה מפרשים<sup data-n=\"2581\">39</sup>) שהיא למעלה מהרצון דמצוות [וכמבואר בכ\"מ<sup data-n=\"2582\">40</sup>, דזה שע\"י התשובה מתמלאים כל הפגמים הוא לפי שתשובה מגעת באוא\"ס בעל הרצון (שלמעלה מהרצון דמצוות), ועד שהיא מגעת בהעצמות<sup data-n=\"2583\">41</sup>, דזהו מ\"ש כי המצוה הזאת אשר אנכי מצוך, אנכי מי שאנכי<sup data-n=\"2584\">42</sup>] שהיא בודאי בבחינת פלא וריחוק. דתשובה תתאה היא בבחינת ריחוק ותשובה עילאה היא בבחינת פלא. כי תשובה תתאה היא במקיף דחי', מקיף הקרוב. וגם ההמשכה מלמעלה הנמשכת ע\"י תשובה תתאה היא המקיף דאור ישר שיש לו שייכות להפנימי, דבכללות הוא אריך. ותשובה עילאה היא במקיף דיחידה, מקיף הרחוק. וגם ההמשכה מלמעלה שנמשכת עי\"ז היא המקיף דאור חוזר שלמעלה משייכותלפנימיות, דבכללות הוא עתיק. ומ\"ש לא נפלאת היא ממך ולא רחוקה היא, הוא ממך דוקא, מנשמות ישראל. דנש\"י יש בהם הכל, וגם מלמעלה נותנים להם הכל, ולכן אין זה נפלא ורחוק מהם.\nה) <b>וצריך</b> להבין, מה מחדש הכתוב בזה שהמצוה הזאת (תשובה) לא נפלאת היא ממך ולא רחוקה היא, דלכאורה, מכיון שגם באדם, עבודת התשובה היא בהמקיפים חי' יחידה, שהם בדוגמת המקיפים שלמעלה (אריך ועתיק), מהו החידוש (כ\"כ) בזה שע\"י העבודה בהמקיפים דהנשמה נמשכים המקיפים דלמעלה. ויש לומר, דממך קאי על נר\"נ שהם עיקר האדם<sup data-n=\"2585\">43</sup>. דהגם שתשובה היא בהמקיפים דנשמה, מ\"מ, בכדי לעורר המקיפים צריכה להיות התבוננות, וההתבוננות (שבנר\"נ) צריכה להיות באופן שעי\"ז יתעוררו המקיפים שלמעלה מהשכל. וזהו החידוש בלא נפלאת היא ממך גו' שממך קאי על נר\"נ (כנ\"ל), דהגם שהמקיפים חי' יחידה הם נפלאים ורחוקים מנר\"נ, מ\"מ, בכח הנר\"נ לעורר (ע\"י התבוננות המתאימה) את המקיפים חי' יחידה<sup data-n=\"2586\">44</sup>, ועל ידם גם המקיפים שלמעלה, אריך ועתיק. והטעם על זה הוא (כמובא לעיל (סוף סעיף ד) מהמאמר) כי נש\"י (היינו גם הנר\"נ) יש להם הכל, וגם מלמעלה נותנים להם הכל.\nו) <b>ויובן</b> זה בהקדים שהביאור בדיוק לשון הכתוב לא נפלאת היא ממך (ממך דוקא), הוא גם להפירוש<sup data-n=\"2587\">45</sup> שהמצוה הזאת קאי על כללות המצוות. דגם לפירוש זה, המצוה הזאת היא בבחינת פלא, וכמובא לעיל (סעיף ד) מהמאמר, שגם כל המצוות, להיותם רצון העליון שלמעלה מהטעם, הם בבחינת פלא וריחוק (אלא שאעפ\"כ לא נפלאת היא ממך, מישראל). ויש לומר, דזה שאומר ב' לשונות, נפלאת ורחוקה, הוא, כי במצוות יש שני ענינים. זה שהמצוות הם רצונו ית', רצון שלמעלה מטעם. וזה שלאחרי שהרצון נתלבש בחכמה (דתורה), ניתוסף גם טעם לכל מצוה<sup data-n=\"2588\">46</sup>. וזהו שני הלשונות דפלא וריחוק, דהרצון שבמצוות, להיותו למעלה מטעם, הוא פלא. וטעמי המצוות כמו שהם מצד החכמה דתורה כמו שהיא למעלה, הם בבחינת ריחוק. דהגם שגם טעמי המצוות (כמו שהם בחכמתו ית') הם למעלה מההבנה דשכל אנושי<sup data-n=\"2589\">47</sup>, מ\"מ, החכמה דלמעלה היא מקור לחכמת ושכל הנבראים<sup data-n=\"2590\">48</sup>, ולכן היא לא נפלאת משכל הנבראים ורק רחוקה מהם<sup data-n=\"2591\">49</sup>.ז) <b>ויש</b> להוסיף, דהמצוות והתורה (טעמי המצוות) כמו שהם מצד עצמם, אין שייך לומר עליהם גם התואר דפלא וריחוק. כי לשון פלא (ומכ\"ש לשון ריחוק) מורה שהדבר המופלא יש לו איזו שייכות להדבר שמופלא ממנו. משא\"כ בשני ענינים שאין שום שייכות ביניהם, אין נופל הלשון פלא. וכמו שאין שייך לומר על סברא שכלית שהיא נפלאת מחוש המישוש<sup data-n=\"2592\">50</sup>. וזה שהתומ\"צ הם ריחוק ופלא הוא לאחרי שירדו להיות להם איזו שייכות לעולם. דהתחלת הירידה היא זה שהתורה קדמה לעולם. דהתורה כמו שהיא מצד עצמה, אינה בגדר עלמין כלל ואין שייך לומר עלי' שקדמה לעולם. וזה שארז\"ל<sup data-n=\"2593\">51</sup> אלפיים שנה קדמה תורה לעולם, הוא בהדרגא דתורה כמו שירדה<sup data-n=\"2594\">52</sup> להיות בגדר עלמין. דבדרגא זו שייך לומר שקדמה לעולם, ויתירה מזו, שיש שיעור בהקדימה, אלפיים שנה. ולאחרי זה ירדה עוד כו\"כ ירידות<sup data-n=\"2595\">53</sup>, עד שנמשכה למטה. ובדרגא זו דתורה, כמו שהיא לאחרי ירידתה [שהיא דרגא כללית, הכוללת כו\"כ דרגות פרטיות, מהדרגא דתורה שקדמה לעולם ועד להדרגא דתורה שנמשכה למטה] שייך לומר שהיא בבחינת פלא וריחוק.\n<b>ויש</b> לומר, דזה שאומר לא נפלאת היא ממך ולא רחוקה היא, הכוונה בזה היא להתומ\"צ כמו שהם בבחינת פלא וריחוק, וגם להתומ\"צ כמו שהם מצד עצמם (קודם ירידתם, שאז אין שייך לומר עליהם גם התואר דפלא וריחוק), שגם דרגא זו דתומ\"צ לא נפלאת היא ממך ולא רחוקה היא. כי במתן תורה ניתנו לישראל כל הדרגות דתורה, גם הדרגא דתורה כמו שהיא מצד עצמה (לפני ירידתה להיות שייכת לעולמות), ועד לאורייתא וקוב\"ה כולא חד<sup data-n=\"2596\">54</sup>.\nח) <b>והנה</b> עד\"ז הוא להפירוש דהמצוה הזאת קאי על מצות התשובה, דזה שתשובה היא בבחינת פלא וריחוק, הוא כמו שירדה להיות נמשכת למטה, אבל כמו שהיא מצד עצמה, אין שייך בה גם התוארים פלא וריחוק. והגם שהפלא והריחוק דתשובה הם באופן נעלה יותר מהפלא והריחוק שבכל המצוות [דהפלא והריחוק שבכל המצוות הו\"ע הרצון והחכמה (כנ\"ל סעיף ו), וכיון שתשובה היא בבעל הרצון (כנ\"ל סעיף ד), מובן, שהפלא והריחוק דתשובה הם באופן נעלה יותר], מ\"מ, מכיון שהתואר פלא (ומכ\"ש התואר דריחוק), גם כמו שהוא בתכלית העילוי, מורה שהדבר המופלא יש לו איזו שייכות להדבר שמופלא ממנו, לכן, בהדרגא דתשובה כמו שהיא מצד עצמה (בעל הרצון), אין שייך לומר לשון פלא וריחוק. ומ\"ש שהמצוה הזאת (תשובה) היא נפלאת ורחוקה, הוא, לאחרי ירידתה להיות נמשכת למטה.<b>ויש</b> לומר, דמ\"ש לא נפלאת היא ממך ולא רחוקה היא, הכוונה בזה היא להתשובה כמו שהיא בבחינת פלא וריחוק וגם להתשובה כמו שהיא מצד שרשה בבעל הרצון (שלמעלה מהתואר דפלא וריחוק), שגם דרגא זו דתשובה לא נפלאת היא ממך ולא רחוקה היא. וזהו מ\"ש כי המצוה הזאת אשר <i>אנכי</i> מצוך גו', שגם התשובה כמו שהיא מצד אנכי, אנכי מי שאנכי, לא נפלאת היא ממך ולא רחוקה היא.\nט) <b>והטעם</b> על זה, כי במתן תורה, על ידי הדיבור<sup data-n=\"2597\">55</sup> אנכי הוי' אלקיך, נעשה כן בכאו\"א מישראל, שאנכי (על ידי שנמשך בהוי') הוא אלקיך, כחך וחיותך<sup data-n=\"2598\">56</sup>. והגם דזה שאנכי נעשה אלקיך הוא כמו שנמשך בהוי', וכמבואר בהמאמר<sup data-n=\"2599\">57</sup> החילוק בין מצות התשובה לכל המצוות, דבתשובה כתיב אשר אנכי מצוך, אנכי סתם, ובכל המצוות כתיב אנכי הוי', אנכי כמו שנמשך בהוי', מ\"מ, ע\"פ הידוע<sup data-n=\"2600\">58</sup> שבהדיבור אנכי כלולים כל המצוות, גם מצות התשובה, יש לומר, שבאנכי הוי' (שבמתן תורה) נכלל גם בחינת אנכי כמו שהוא בעצמותו, למעלה מהמשכה בהוי', אלא שהגילוי דבחינה זו הוא במצות התשובה. ומזה מובן, דזה שבמתן תורה נעשה בכאו\"א מישראל שאנכי הוא אלקיך, כחך וחיותך, הוא גם בחינת אנכי שלמעלה מהמשכה בהוי'. וכאשר האדם רוצה להתעורר בתשובה (עוד לפני שעושה תשובה), עי\"ז מתגלה אצלו שאנכי (גם אנכי שלמעלה מהמשכה בהוי') הוא כחך וחיותך, היינו שזה שייך גם להנר\"נ שלו, ועי\"ז, המצוה הזאת (תשובה) אשר אנכי מצוך, לא נפלאת היא ממך ולא רחוקה היא, ואדרבא, קרוב אליך הדבר מאד בפיך ובלבבך לעשותו, שקרוב מאד לכ\"א מישראל להגיע לתשובה, ולא רק לדרגת התשובה כמו שירדה להיות בבחינת פלא וריחוק אלא גם לדרגת התשובה אשר <i>אנכי</i> מצוך.\nיו\"ד) <b>וזהו</b> ואת ובנייך תחיי בנותר, שגם כחות הפנימיים דהנשמה יחיו בנותר, דהגם שנותר הוא מקיף, ויתירה מזו שהוא מקיף הרחוק, מ\"מ, נמשך ממנו חיות גם לכחות הפנימיים דהנשמה, כי ע\"י התשובה מתגלה שאנכי הוא אלקיך כחך וחיותך. וע\"ד שנת\"ל (סעיף ט) בענין לא נפלאת היא ממך. אלא שענין לא נפלאת היא ממך הוא שכחות הפנימיים דהנשמה (ע\"י הרצון לעשות תשובה) הם באופן שעל ידם אפשר להגיע להמקיפים, וענין ואת ובנייך תחיי בנותר הוא שכחות הפנימיים חיים (בחיות פנימי) בהנותר שנמשך ע\"י התשובה, בנותר דמקיף הקרוב וגם בנותר דמקיף הרחוק [ויש לומר, שבנותר נכלל גם העצם שלמעלה מהגדר דמקיף ופנימי].\n<b>ויש</b> לקשר זה גם עם פירוש רז\"ל עה\"פ ואת ובנייך תחיי בנותר, עד שיחיו המתים, כי בתחיית המתים יהי' חיות הגוף מהסובב<sup data-n=\"2601\">59</sup> (נותר). וע\"י ענין את ובנייך תחייבנותר, שהחיות דכחות הפנימיים (דהנשמה) הוא בנותר, יהי' לע\"ל גם חיות הגוף מהסובב. [ולא עוד אלא שהחיות דהגוף יהי' נעלה יותר, שלכן, הנשמה תהי' ניזונית מהגוף&lt;59&gt;]. ויש לומר, שזוהי גם השייכות דתשובה לגאולה העתידה, דאין ישראל נגאלין אלא בתשובה<sup data-n=\"2602\">60</sup> ומשיח אתא לאתבא צדיקייא בתיובתא<sup data-n=\"2603\">61</sup>, כי ההמשכה שע\"י התשובה היא באופן שממנה נמשך חיות גם לכחות הפנימיים, את ובנייך תחיי בנותר, והשלימות דגאולה העתידה היא בתחיית המתים, שחיות הגוף יהי' מהסובב. ולכן, ע\"י שישראל עושין תשובה מיד הן נגאלין<sup data-n=\"2602\">60</sup>, בגאולה האמיתית והשלימה ע\"י משיח צדקנו, יבוא ויגאלנו ויוליכנו קוממיות לארצנו, בעגלא דידן ממש.\n**********",[["2542","*","יצא לאור ב<b>קונטרס כ\"ף מרחשון – תש\"נ</b>, \"לקראת ש\"פ וירא, כ\"ף מרחשון הבעל\"ט, יום הולדת את כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע . . <i>ט\"ו מ\"ח שנת ה'תש\"נ</i>\"."],["2543","1","מלכים-ב ד, א ואילך. – התחלת ההפטרה דש\"פ וירא, שבשנה זו (תשמ\"ו) הוא השבת שלפני כ\"ף מר-חשון, יום ההולדת של כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע, שמיני' מתברכין כולהו יומין (זח\"ב סג, ב. פח, א)."],["2544","2","ד\"ה כשם שצועקים, נדפס במאמרי אדה\"ז – הקצרים ע' קלז. וראה גם ד\"ה ואשה אחת (נדפס שם ע' קלו)."],["2545","3","לשון הכתוב – ישעי' נז, יט."],["2546","4","מקץ מא, נא."],["2547","5","פ\"ג."],["2548","6","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310015\" data-slug=\"tanya\" data-id=\"3401310015\">תניא שם (ז, ב</a>): ושאר המדות הן ענפי היראה והאהבה ותולדותיהן."],["2549","7","כ\"ה בד\"ה ואשה אחת שם."],["2550","8","וכן משמע בד\"ה ואשה אחת הנ\"ל."],["2551","9","<a class=\"ft-cite\" href=\"#/read/tanya/3401310058\" data-slug=\"tanya\" data-id=\"3401310058\">תניא פנ\"ג (עה, רע\"א</a>), מזהר (ראה זח\"ג לד, א. שם לח, ב ובניצוצי אורות שם אות א)."],["2552","10","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310024\" data-slug=\"tanya\" data-id=\"3401310024\">תניא פי\"ט (כה, א</a>)."],["2553","11","כ\"ה בד\"ה ואשה אחת שם. ובד\"ה כשם שצועקים, דפירוש כלים רקים אל תמעיטי הוא שיתבונן איך שהוא כלי ריקן, כדלקמן בפנים."],["2554","12","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380846\" data-slug=\"likkutei-torah\" data-id=\"4001380846\">לקו\"ת ראה לב, ד</a>."],["2555","13","שאז הם כגוף בלי נשמה (<a class=\"ft-cite\" href=\"#/read/tanya/3401310043\" data-slug=\"tanya\" data-id=\"3401310043\">תניא פל\"ח</a> ואילך) ואפשר שלכן הם נק' כלים רקים."],["2556","14","ספכ\"ה."],["2557","15","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310023\" data-slug=\"tanya\" data-id=\"3401310023\">תניא פי\"ח</a>-יט."],["2558","16","ע\"פ לשון הכתוב – קהלת ב, יג. וראה ספר הערכים-חב\"ד ערך אור – ביחס לחושך ס\"ח. <i>וש\"נ</i>."],["2559","17","צע\"ק, דבפסוק נאמר \"אל תמעיטי\", ובהמאמר \"שיתבונן <i>הרבה</i>\"."],["2560","18","זח\"ג קסח, א. – בזהר שם הוא בשינוי לשון, אבל כ\"ה במאמר אדה\"ז שם. וכ\"ה גם ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310034\" data-slug=\"tanya\" data-id=\"3401310034\">תניא רפכ\"ט</a>. <i>ובכ\"מ</i>."],["2561","19","ראה ספר הערכים שם ע' תקפ (<i>וש\"נ</i>), שזהו אחד הפירושים ביתרון האור מן החושך."],["2562","20","תהלים יח, יב."],["2563","21","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381015\" data-slug=\"likkutei-torah\" data-id=\"4001381015\">לקו\"ת האזינו עג, סע\"א</a>."],["2564","22","ס\"פ מסעי ד\"ה ענין נחלת יעקב (צו, ב)."],["2565","23","ר\"ה יז, א."],["2566","24","מיכה ז, יח."],["2567","25","וראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380968\" data-slug=\"likkutei-torah\" data-id=\"4001380968\">לקו\"ת דרושי ר\"ה ד</a>\"ה להבין כו' מי א-ל כמוך (סב, ב)."],["2568","26","בתחילתו. ובאוה\"ת נצבים א'רפב ואילך הובא ענין זה שבתו\"א והענין דלמי שמשים עצמו כשיריים <i>בהמשך אחד</i>. עיי\"ש."],["2569","27","ישעי' סו, א-ב."],["2570","28","ב\"ר ספל\"ה. יל\"ש מלכים עה\"פ (רמז רכח)."],["2571","29","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381124\" data-slug=\"likkutei-torah\" data-id=\"4001381124\">לקו\"ת ברכה צט, ב</a>-ג (הובא בלקו\"ת מסעי שם). ובכ\"מ."],["2572","30","זח\"ב פג, א (הובא בלקו\"ת מסעי שם)."],["2573","31","והגם דטבע המס\"נ שבכאו\"א מישראל הוא לא מצד הרצון שלו אלא מפני שאינו יכול להפרד ח\"ו מאחדותו ית' (המשך תרס\"ו ע' רסז. ובכ\"מ) – הנה זהו כשבא למס\"נ בפועל, שאז מתגלית היחידה שבו. אבל כל זמן שלא בא לידי מס\"נ בפועל ורק <i>זוכר</i> ענין מסירת נפשו לה' שעי\"ז \"יוכל לעמוד נגד יצרו\" (תניא ספכ\"ה) – הנה זה שעומד נגד יצרו (ע\"י זכירת המס\"נ) הוא <i>שרוצה</i> לעמוד נגד יצרו."],["2574","32","להעיר שגם בתשובה (דוגמת) שני ענינים אלה. א) שהאהבה והצמאון להוי' דבעל תשובה הוא יותר מבצדיקים (<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז (יב, א</a>). ובכ\"מ). ב) שנעשה נבזה בעיניו נמאס כו' מואס בחייו, <i>ועי\"ז</i> נמשך לו חסד דעתיק (<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380965\" data-slug=\"likkutei-torah\" data-id=\"4001380965\">לקו\"ת</a> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380968\" data-slug=\"likkutei-torah\" data-id=\"4001380968\">דרושים לר\"ה סא, ג</a>). ובהמשך הענין שם (סב, ב) שזהו\"ע המשכת השיריים למי שמשים עצמו כשיריים."],["2575","33","לשון הכתוב – נצבים ל, יא."],["2576","34","דשנת תרע\"ג."],["2577","35","סה\"מ תער\"ב-תרע\"ו (נדפס שם ע' רפט ואילך)."],["2578","36","קהלת ז, כג."],["2579","37","כ\"ה בסה\"מ שם ע' רחצ. ועד\"ז הוא בד\"ה כי המצוה הזאת ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380900\" data-slug=\"likkutei-torah\" data-id=\"4001380900\">לקו\"ת נצבים מה, ב</a> ובסה\"מ תקס\"ה ס\"ע תתפא ואילך. ולהעיר דבסוף ד\"ה כי המצוה הזאת בהמשך תרס\"ו (ע' שמז) מבואר דריחוק הוא למעלה מפלא."],["2580","38","כ\"ה (שגם כל המצוות הם פלא וריחוק) להדיא בתחלת המאמר שם ע' רפט."],["2581","39","וכ\"ה בד\"ה כי המצוה שבלקו\"ת ובסה\"מ תקס\"ה שם."],["2582","40","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380901\" data-slug=\"likkutei-torah\" data-id=\"4001380901\">ראה ד</a>\"ה שובה ישראל דוא\"ו תשרי ה'תשל\"ז ס\"ה (לעיל ע' צג) ובהנסמן שם הערה 46. וראה גם לקו\"ת נצבים מה, ג-ד. סה\"מ תקס\"ה שם ע' תתעט ואילך."],["2583","41","שהוא למעלה גם מבעל הרצון – ראה ד\"ה שובה ישראל דש\"פ האזינו ה'תשל\"ז ס\"ד (לעיל ע' צט)."],["2584","42","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380902\" data-slug=\"likkutei-torah\" data-id=\"4001380902\">לקו\"ת שם מה, ד</a>. סה\"מ תקס\"ה ע' תתעט ואילך. ד\"ה הנ\"ל תרע\"ג ע' רצט. וראה לקמן ס\"ט."],["2585","43","להעיר מהמובא לעיל ס\"ג שהמקיפים נק' <i>שיריים</i>."],["2586","44","להעיר מ<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380906\" data-slug=\"likkutei-torah\" data-id=\"4001380906\">לקו\"ת נצבים מו סע\"ד</a> דבתשובה יש שתי מדריגות תשו\"ת ותשו\"ע \"וגם בחינה זו (תשו\"ע) הוא קרוב אליך\"."],["2587","45","ראה רש\"י עה\"פ לא בשמים גו' ועה\"פ כי קרוב גו' (שבהמשך לכי המצוה הזאת). תניא פי\"ז ובה\"שער\" דהתניא (בפי' הפסוק כי קרוב גו'). ובסד\"ה כי המצוה בהמשך תרס\"ו \"המצוה הזאת קאי על כל המצוות\"."],["2588","46","ראה בארוכה לקמן ח\"ב ס\"ע קסד ואילך. ח\"ד ס\"ע יד ואילך. <i>וש\"נ</i>. וראה שם ע' טו, שגם המצוות דחוקים יש להם טעם בחכמה שלמע'. ולהעיר מהא שאמר שלמה \"אמרתי אחכמה גו'\" בנוגע <i>לפרה אדומה</i> (במדב\"ר פי\"ט, ג)."],["2589","47","ראה אגה\"ק סי\"ט (קכח, א) שטעמי המצוות לא נתגלו, והטעמים המובנים לנו אינם תכלית הטעם. וראה בארוכה לקמן ח\"ב ס\"ע קסד ואילך."],["2590","48","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370063\" data-slug=\"torah-or\" data-id=\"3901370063\">תו\"א וירא יד, א</a>. ובכ\"מ."],["2591","49","עפ\"ז יומתק זה שאמר שלמה בנוגע ל<i>הטעם</i> דפרה אדומה \"והיא <i>רחוקה</i> ממני\"."],["2592","50","ראה שעהיוה\"א פ\"ט (פו, ב). וראה ד\"ה שובה ישראל דש\"פ האזינו הנ\"ל הערה 24 (לעיל ע' צט)."],["2593","51","ראה מדרש תהלים צ, ד. ב\"ר פ\"ח, ב. תנחומא וישב ד."],["2594","52","דזה שאלפיים שנה קדמה תורה לעולם למדין ממ\"ש (משלי ח, ל) ואהי' גו' יום יום (מקומות שבהערה הקודמת) – וענין זה שבתורה הוא למטה וירידה לגבי \"ואהי' אצלו אמון\" (התחלת הכתוב), ראה בארוכה סה\"מ תרס\"ה ע' עד. ובכ\"מ."],["2595","53","ראה סה\"מ תרס\"ה שם בענין ה' הדרגות דתורה שבמשלי שם."],["2596","54","ראה זח\"ג עג, א."],["2597","55","יתרו כ, ב."],["2598","56","ראה <i>עד\"ז</i> <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380375\" data-slug=\"likkutei-torah\" data-id=\"4001380375\">לקו\"ת במדבר טז, סע\"ד</a>."],["2599","57","ע' רצט. וראה גם סה\"מ תקס\"ה ע' תתעט."],["2600","58","ראה ד\"ה וידבר גו' אנכי ה'תשכ\"ח הערה 20 (לקמן ח\"ג ע' שכז)."],["2601","59","המשך וככה תרל\"ז פצ\"א. סה\"מ קונטרסים ח\"ב תיג, ב. ובכ\"מ."],["2602","60","רמב\"ם הל' תשובה פ\"ז ה\"ה."],["2603","61","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת שמע\"צ צב, ב</a>. שה\"ש נ, סע\"ב. ובכ\"מ. וראה זח\"ג קנג, ב."]]],[1500360039,"<h3>בס\"ד. ש\"פ חיי שרה, מבה\"ח כסלו ה'תש\"ל<sup data-n=\"2604\">*</sup></h3>\n<b>ויהיו</b> חיי שרה מאה שנה ועשרים שנה ושבע שנים שני חיי שרה<sup data-n=\"2605\">1</sup>, ומדייק אדמו\"ר (מהורש\"ב) נ\"ע בעל יום ההולדת דכ\"ף מרחשון במאמרו ד\"ה זה<sup data-n=\"2606\">2</sup>, הרי כבר נאמר ויהיו חיי שרה, ולמה נכפל עוד פעם שני חיי שרה. וממשיך בהמאמר, שבזהר<sup data-n=\"2607\">3</sup> עה\"פ ויהיו חיי שרה מבאר תחלה את הפסוק<sup data-n=\"2608\">4</sup> ויתרון ארץ בכל היא מלך לשדה נעבד, ולאח\"ז<sup data-n=\"2609\">5</sup> אומר דענין ויהיו חיי שרה הוא ששרה זכתה לחיין עילאין. ומבאר בהמאמר השייכות דויתרון ארץ בכל היא מלך לשדה נעבד לויהיו חיי שרה, דארץ ושדה הם בחינת מלכות, וענין יתרון ארץ בכל היא מלך לשדה נעבד הוא המשכת האורות שלמעלה ממלכות, בחינת כל ובחינת מלך, במלכות. וזוהי השייכות דויתרון ארץ בכל היא מלך לשדה נעבד לויהיו חיי שרה, כי שרה היא בחינת מלכות (דוגמת ארץ ושדה), וזה ששרה זכתה לחיין עילאין הוא שנמשכו בה האורות שלמעלה ממלכות. ומבאר בארוכה ד' הענינים שבפסוק ויתרון ארץ גו', שתי הבחינות שבמלכות, ארץ ושדה, ושתי הבחינות בהאורות שלמעלה מהמלכות הנמשכים במלכות, בחינת כל ובחינת מלך. ומבאר, דעשרים שנה ושבע שנים הוא ע\"ד בחינת כל, ומאה שנה הוא ע\"ד בחינת מלך<sup data-n=\"2610\">6</sup>. ולאחרי זה מבאר (בסיום המאמר), דויהיו חיי שרה הוא המשכת החיין עילאין (מאה שנה ועשרים שנה ושבע שנים) במלכות, ושני חיי שרה הוא, שהחיין עילאין נמשכו בבי\"ע. וצריך להבין, דבכדי לבאר ההוספה דשני חיי שרה על ויהיו חיי שרה נוגע לכאורה רק שויהיו חיי שרה הוא המשכת חיין עילאין במלכות, דעפ\"ז יש לבאר שההוספה דשני חיי שרה היא ההמשכה בבי\"ע, ומזה שביאור זה בא (בהמאמר) לאחרי ביאור הפסוק ויתרון ארץ גו' ושייכותו לויהיו חיי שרה, משמע, שעי\"ז מיתוסף ביאור בהענין דשני חיי שרה (ההמשכה בבי\"ע).\nב) <b>ויובן</b> זה ע\"פ המבואר בהמאמר<sup data-n=\"2611\">7</sup> החילוק בין ארץ ושדה, דארץ הוא כללות העולם, ושדה (המובחר שבארץ) הוא הגן עדן. וחילוק זה שבין כללות העולם לג\"ע (שכללות העולם נקרא ארץ וג\"ע שדה) הוא בשרשם. דהתהוות העולםהוא מבחינת חיצוניות המלכות שנק' ארץ, והג\"ע הוא מבחינת פנימיות המלכות שנק' שדה. וממשיך בהמאמר, דכמו שמעלת השדה כפשוטה היא שהוא מקום הראוי לזריעה, עד\"ז הוא בנוגע לג\"ע, שהוא מקום מוכשר להמשכת הגילוי דאוא\"ס (צמיחה) שע\"י זריעת המצוות. [וכמבואר במק\"א<sup data-n=\"2612\">8</sup> עה\"פ<sup data-n=\"2613\">9</sup> ויקח ה' אלקים את האדם ויניחהו בגן עדן לעבדה ולשמרה וארז\"ל<sup data-n=\"2614\">10</sup> לעבדה זה רמ\"ח מ\"ע ולשמרה זה שס\"ה מל\"ת, דהטעם על זה שהניחהו בג\"ע (דוקא) לעבדה ולשמרה, הוא, כי ג\"ע הוא מקום מוכשר להגילוי שנמשך ע\"י קיום המצוות. וזה שנמשך הגילוי ע\"י קיום המצוות בכללות העולם (לאחרי שגורש האדם מג\"ע) הוא כמ\"ש<sup data-n=\"2615\">11</sup> וישלחהו ה' אלקים מגן עדן לעבוד את האדמה גו', דענין לעבוד את האדמה הוא לעשות המקום דעולם שיהי' מוכשר להגילוי<sup data-n=\"2616\">12</sup>]. וזהו ויתרון ארץ בכל היא מלך לשדה נעבד, שהיתרון דארץ [כללות העולם, שהתהוותו היא מחיצוניות המלכות] היא בכל, שנמשך בה בחינת כל, היא ספירת היסוד שנקראת כל<sup data-n=\"2617\">13</sup>. ומלך לשדה נעבד הוא המשכת הגילוי דאוא\"ס (שלמעלה מבחינת כל) שע\"י קיום המצוות. כדאיתא בזהר שם, מאן מלך דא מלך עילאה דאתחבר לשדה כד איהו נעבד, שע\"י העבודה בג\"ע (שדה נעבד) שהיא העבודה דקיום המצוות (לעבדה רמ\"ח מ\"ע ולשמרה שס\"ה מל\"ת), נמשך גילוי אוא\"ס (מלך עילאה), שלמעלה מהגילוי דבחינת כל.\nג) <b>וביאור</b> ג' מדריגות הנ\"ל [המלכות כמו שהיא מצד עצמה, המשכת הגילוי דבחינת כל (יסוד), והמשכת הגילוי דבחינת מלך עילאה ע\"י קיום המצוות], הנה החילוק בין יסוד ומלכות הוא<sup data-n=\"2618\">14</sup>, שמלכות היא שרש הנבראים. שלכן נקראת המלכות בשם דיבור (מלכות פה<sup data-n=\"2619\">15</sup>), דכמו שהדיבור הוא בשביל הזולת. דנוסף לזה שהדיבור שמדבר בפועל הוא נשמע לזולתו (דזה שהוא נשמע לזולתו הוא ע\"י שיוצא לחוץ ונעשה נפרד מהאדם המדבר), הנה גם <i>כח</i> הדיבור שבהאדם עצמו, ענינו הוא זה שבכחו לדבר לזולתו. ועד\"ז הוא במלכות, שגם בהיותה באצילות (לפני שיורדת להחיות הנבראים) היא שורש ומקור הנבראים. ויסוד הוא סיום האצילות (סיומא דגופא<sup data-n=\"2619\">15</sup>), בדוגמת המדות שבאדם, דהגם שהם שייכים להזולת, הרי ענינם הוא<sup data-n=\"2620\">16</sup> <i>שהאדם</i> מתעורר ומתפעל. וזהו ויתרון ארץ בכל היא, שהיתרון דארץ (מלכות, שרש הנבראים) הוא שנמשך בה בחינת כל, יסוד (סיום האצילות).<b>ויש</b> לומר, דזה שהמשכה זו נקראת <i>יתרון</i> ארץ, הגם שהמלכות מקבלת תמיד מז\"א (מדות), הוא, כי ההמשכה מז\"א למלכות היא (בדרך כלל) באופן שע\"י שהמלכות מקבלת בתוכה את האורות דז\"א היא <i>משתנית</i><sup data-n=\"2621\">17</sup> [וע\"ד כשאדם מדבר דברי אהבה, דכיון דזה שהוא <i>מדבר</i> דברי אהבה הוא כדי לגלות האהבה לזולתו, הרי האהבה שנמשכת בהדיבור היא ירידה ושינוי לגבי האהבה עצמה], והיתרון דארץ (מלכות) הוא בכל (יסוד ז\"א), שהמלכות מקבלת בחינת היסוד (כמו שהוא בעצמותו<sup data-n=\"2622\">18</sup>) – סיום האצילות.\nד) <b>והנה</b> זה שהמשכת הגילוי דבחינת כל הוא יתרון בהמלכות, הוא דוקא בנוגע לחיצוניות המלכות, ארץ. דכיון שחיצוניות המלכות (הדיבור דמלכות) ענינה הוא שהיא שרש הנבראים, לכן, זה שנמשך בה הגילוי דבחינת כל, (סיום ה)אצילות שלמעלה משרש הנבראים, הוא יתרון (חידוש). אבל בנוגע לפנימיות המלכות, הרי אדרבה, ענינה של פנימיות המלכות (ג\"ר דמלכות) הוא שהיא מקבלת מהיסוד. וזהו שהג\"ע נקרא בשם כל [כמארז\"ל<sup data-n=\"2623\">19</sup> שלשה הטעימן הקב\"ה בעולם הזה מעין עולם הבא, אלו הן, אברהם יצחק ויעקב, אברהם דכתיב בי'<sup data-n=\"2624\">20</sup> בכל, יצחק דכתיב בי'<sup data-n=\"2625\">21</sup> מכל, יעקב דכתיב בי'<sup data-n=\"2626\">22</sup> כל], כי כל הוא ספירת היסוד (כנ\"ל), והג\"ע הוא מבחינת פנימיות המלכות שמקבלת מהיסוד.\nה) <b>ומבואר</b> בהמאמר, דזה שהיסוד נקרא בשם כל הוא על שם נו\"ן שערי בינה שנמשכים בו (כל בגימטריא נו\"ן<sup data-n=\"2627\">23</sup>). ומזה מובן, דהיתרון בארץ (מלכות) ע\"י בחינת כל הוא בשני ענינים. שנמשך בה היסוד, שהוא סיום המדות דאצילות, ויתירה מזו, שע\"י היסוד נמשכים בה נו\"ן שערי בינה, מוחין שלמעלה ממדות. ויש לומר, דשני ענינים אלה שייכים זה לזה. והענין הוא, דמדות הם שייכים להזולת. דהגם שהמדות הם ענין שנוגע להאדם עצמו (ולא כהדיבור שהוא גילוי להזולת), מ\"מ, הם בדרגת האדם כמו ששייך אל הזולת, והמוחין הם בדרגת האדם כמו שהוא לעצמו, מובדל מהזולת. ולכן, כשההמשכה היא רק מבחינת המדות דז\"א שהם שייכים לזולת, אזי, ע\"י שהמלכות מקבלת בתוכה את המדות דז\"א נעשה בה שינוי (כנ\"ל סעיף ג), וזה שהמלכות מקבלת את המדות דז\"א כמו שהם [דזהו\"ע יתרון ארץ בכל היא, שגם בארץ מאיר הגילוי דבחינת כל כמו שהוא בעצמותו], הוא ע\"י ששרש ההמשכה הוא מהמוחין, דכיון שהמוחין הםלמעלה משייכות לזולת (ענין הדיבור, מלכות), לכן, גם כשההמשכה באה בדיבור, אין ביכולת הדיבור לפעול בה שינוי.\nו) <b>והנה</b> גם המוחין שלמעלה משייכות לזולת הם בכלל סדר ההשתלשלות. והגילוי דבחינת מלך עילאה שע\"י קיום המצוות (מלך לשדה נעבד) שלמעלה מבחינת כל, הוא למעלה מהשתלשלות. ולהוסיף, דע\"פ המבואר במק\"א<sup data-n=\"2628\">24</sup> דכל הוא בחינת סובב<sup data-n=\"2629\">25</sup>, וזה שהיסוד נקרא בשם כל הוא לפי שהיסוד הוא בקו האמצעי שמגיע בכתר (סובב) [וזהו מ\"ש<sup data-n=\"2630\">26</sup> כי כל בשמים ובארץ ותרגם דאחיד בשמיא ובארעא, כי לגבי הסובב שמים וארץ הם בשוה], צריך לומר, שהגילוי דבחינת מלך עילאה (שע\"י קיום המצוות) הוא למעלה גם מבחינת סובב. דסובב הוא שייך לעולמות אלא שהוא למעלה מהם וכולל את כולם כאחד. וזהו כי כל בשמים ובארץ, שגם לגבי סובב יש שמים וארץ, אלא שהוא מחברם ומאחדם – דאחיד בשמיא ובארעא. וע\"י המצוות הוא המשכת גילוי עצמות אוא\"ס שלמעלה משייכות לעולמות, למעלה גם מסובב. וכמבואר בהמאמר, דההמשכה שע\"י קיום המצוות היא מפנימיות הכתר. והחילוק שבין אריך (חיצוניות הכתר) לעתיק (פנימיות הכתר) הוא, דאריך הוא שרש ומקור הנאצלים אלא שהוא מקיף עליהם – סובב<sup data-n=\"2631\">27</sup>, ועתיק הוא בחינה תחתונה שבמאציל – אוא\"ס שלמעלה משייכות לעולמות.\n<b>ומבואר</b> בהמאמר, דמלך עילאה הוא ת\"ת [כדאיתא בזהר שם מלך דא קוב\"ה, וקוב\"ה הוא בחינת ת\"ת] ות\"ת ממשיך מפנימיות הכתר. ויש לומר, דזה שהת\"ת (דוקא) ממשיך מפנימיות הכתר, אף שגם היסוד הוא בקו האמצעי, הוא, כי חג\"ת הם עצם המדות ונה\"י הם שעל ידם היא ההשפעה (דהמדות חג\"ת)<sup data-n=\"2632\">28</sup>, ולכן, הגילוי דכתר שע\"י היסוד (שעל ידו היא ההשפעה) הוא בחינת שרש הנאצלים, והגילוי דכתר שע\"י הת\"ת (שלמעלה מהשפעה) הוא בחינת פנימיות הכתר.\nז) <b>והנה</b> ידוע<sup data-n=\"2633\">29</sup> ששני הענינים דממלא וסובב שרשם הוא באוא\"ס שלפני הצמצום, דאור הגבול (שלפני הצמצום) הוא השרש דאור הממלא, ואור הבלי גבול הוא השרש דאור הסובב. והחילוק בין פעולת הצמצום באור הגבול (שרש הממלא) ופעולת הצמצום באור הבל\"ג (שרש הסובב) הוא, דפעולת הצמצום באור הגבול היא בהאור עצמו, שע\"י הצמצום בא במדה וגבול לפי ערך העולמות, ממלא כל עלמין. ופעולת הצמצום באור הבל\"ג היא (לא בהאור עצמו, אלא) שלא יאיר במקום החלל. ומזה נעשה הענין דסובב, שהאור אינו מאיר (בעולמות, מקום החלל) בגילוי ובפנימיות אלא בבחינת מקיף והעלם. ועפ\"ז יש לומר, שב' הענינים שבבחינת כל [שעל ידי היסוד הוא המשכת המדות והמוחין, ושע\"י היסוד הואהמשכת הכתר] בשרשם באוא\"ס שלפני הצמצום הם אור הגבול ואור הבל\"ג, וע\"י קיום המצוות נמשך<sup data-n=\"2634\">30</sup> אור חדש שלא האיר גם קודם הצמצום.\n<b>וזהו</b> שלע\"ל יהיו שמים חדשים וארץ חדשה<sup data-n=\"2635\">31</sup>, כי אז יתגלו כל הענינים שנמשכים ע\"י מעשינו ועבודתינו עכשיו<sup data-n=\"2636\">32</sup>, כולל האור חדש שנמשך ע\"י קיום התומ\"צ עכשיו, ועי\"ז תהי' התחדשות גם בעולם, שמים חדשים וארץ חדשה. דזה שלע\"ל יומשך בעולם גילוי אור הבל\"ג שהאיר קודם הצמצום, אין זה חידוש אמיתי. דכיון שאור זה הי' כבר בגילוי במקום החלל אלא שע\"י הצמצום נסתלק האור, לכן, כשהאור חוזר ונמשך, אין זה חידוש אמיתי. וזה שלע\"ל יהיו שמים חדשים וארץ חדשה הוא, כי אז יהי' גילוי האור חדש (שנמשך ע\"י קיום התומ\"צ עכשיו) שלא הי' גם קודם הצמצום.\nח) <b>והנה</b><sup data-n=\"2637\">33</sup> ידוע, דזה שהבריאה היא בשביל ישראל<sup data-n=\"2638\">34</sup>, הכוונה בזה היא לא רק לבריאת העולם אלא גם לכל הגילויים, גם לגילויים הכי נעלים. ומזה מובן גם בנוגע לאור הנ\"ל שלא האיר גם קודם הצמצום, דזה שנעשה (כביכול) אור זה (שלמעלה מגדר המשכה וגילוי) הוא בכדי שע\"י עבודתם של ישראל יהי' אח\"כ בהמשכה וגילוי, ושההמשכה והגילוי שלו יהיו בעולם [וכנ\"ל שע\"י האור חדש, <i>השמים והארץ</i> יהיו חדשים], ועי\"ז תושלם הכוונה דדירה בתחתונים. ועפ\"ז יש לקשר פירוש הזהר במלך לשדה נעבד (שנעבד קאי על שדה) עם הפירוש (הפשוט) שנעבד קאי על מלך, שגם עצם האור שלמעלה מגדר המשכה וגילוי (מלך עילאה) נעבד כביכול לעבודת השדה (שדה נעבד), קיום המצוות.\n<b>ויש</b> להוסיף בביאור לשון הכתוב <i>לשדה</i> נעבד, כי הכוונה דדירה בתחתונים היא שהגילוי אלקות שנמשך בהתחתונים יהי' מצד ענין התחתונים עצמם. ויש לומר, דזהו הטעם על זה שהגילוי שע\"י המצוות הוא ע\"י שהמקום שבו נעשית המצוה הוא מוכשר להגילוי [וכנ\"ל (סעיף ב) דזה שגן עדן נק' בשם שדה הוא לפי שהגן עדן הוא מקום מוכשר להגילוי שעל ידי זריעת המצוות. ועד\"ז הוא בנוגע להמקום דכללות העולם, דזה שוישלחהו גו' לעבוד את האדמה הוא לעשות המקום דעולם להיות מוכשר להגילוי שע\"י המצוות], כי ע\"י שהמשכת הגילוי בעולם שע\"י המצוה היא גם לפי שה(מקום ד)עולם מוכשר לזה, הגילוי בעולם הוא מצד ענינו דהעולם עצמו. וזהו מלך <i>לשדה</i> נעבד, כי שלימות הכוונה דדירה בתחתונים היא שהגילוי בעולם יהי' (לא רק מצד קיום המצוה, אלא גם) מצד העולם, שדה, וכיון דזה שנעשה כביכול בחינת עצם האור, מלך עילאה, הוא בשביל כוונה זו, לכן מלך <i>לשדה</i> נעבד.<b>ולהוסיף</b><b>,</b> דהטעם (בפנימיות הענינים) על זה שהאדם גורש מגן עדן הוא, כי הכוונה דדירה בתחתונים היא שדירה תהי' בהתחתון שאין תחתון למטה ממנו<sup data-n=\"2639\">35</sup>, ושהדירה בו תהי' מצד ענינו (דתחתון זה), ולכן וישלחהו ה' אלקים מגן עדן לעבוד את האדמה גו', לעשות המקום דעולם (תחתון ביותר<sup data-n=\"2640\">36</sup>) מוכשר להגילוי, בכדי שגם התחתון שאין תחתון למטה ממנו יהי' דירה לו ית', ושהדירה בו תהי' מצד ענינו. ועד\"ז הוא בענין שדה וארץ דלמעלה, דתכלית הכוונה בהמשכת הגילוי דבחינת מלך עילאה בשדה, פנימיות המלכות, הוא, שעי\"ז יומשך הגילוי בארץ<sup data-n=\"2641\">37</sup>, חיצוניות המלכות (ועי\"ז בבי\"ע, עד בעוה\"ז התחתון), ובאופן שהגילוי בארץ יהי' (לא כמו דבר נוסף עליו, אלא שזה) יהי' ענינה של הארץ, בדוגמת פנימיות המלכות (שדה<sup data-n=\"2642\">38</sup>) שענינה הוא זה שמקבלת את הגילויים שלמעלה ממנה.\nט) <b>וזהו</b> ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים, ומבאר בהמאמר, דמאה שנה הוא פנימיות הכתר, בחינת מלך עילאה. עשרים שנה ושבע שנים הם מוחין ומדות (שנמשכים ע\"י היסוד), בחינת כל. וצריך ביאור, הרי זה שזכתה שרה לחיין עילאין הי' באופן דמלמטה למעלה, בתחילה בחינת כל ואח\"כ בחינת מלך עילאה, והסדר בכתוב הוא מאה שנה ואח\"כ עשרים שנה ושבע שנים. ויש לומר הביאור, שהוא בכדי לרמז שההמשכה דבחינת מאה שנה, מלך עילאה, המשיכה אח\"כ גם בבחינת עשרים שנה ושבע שנים, בחינת כל. ועי\"ז, הגילוי דבחינת מאה שנה שנמשך תחלה בבחינת שדה (פנימיות המלכות) נמשך אח\"כ גם בבחינת ארץ (חיצוניות המלכות)<sup data-n=\"2643\">39</sup>. ולאח\"ז נאמר שני חיי שרה, שהמשיכה גילוי זה גם בבי\"ע.\n<b>ולהוסיף</b><b>,</b> דע\"י המשכת בחינת מאה שנה (מלך עילאה) בחיצוניות המלכות ובפרט בבי\"ע, נעשה בו עלי'. דמלך עילאה מצד עצמו הוא אור (אלאשהוא אור שלמעלה מהמשכה וגילוי), וע\"י המשכתו למטה, מתגלית בו כוונת העצמות. ועפ\"ז, סדר הענינים שבכתוב הוא מלמטה למעלה, הן בנוגע לשרה, דכל מה שנתעלתה לדרגא עליונה יותר המשיכה בחינת מאה שנה למטה יותר, וגם בנוגע להענין דמאה שנה עצמו, שע\"י המשכתו למטה נעשה בו עלי'. וזהו שני חיי שרה כולן שוין לטובה<sup data-n=\"2644\">40</sup>, דהאור מצד עצמו הוא בחינת מאה שנה, מאה הו\"ע התחלקות פרטים אלא שכולם הם מתאחדים כאחד, שנה לשון יחיד, ולאח\"ז נאמר שני חיי שרה ולא נזכר מספר, למעלה מגדר התחלקות.\n<b>וממשיך</b> הכתוב בקרית ארבע היא חברון, דלאחרי המשכת בחינת מאה שנה בבי\"ע, נמשך גילוי זה בגוף הגשמי שמחובר (חברון) מארבע יסודות<sup data-n=\"2645\">41</sup>, ועי\"ז מיתוסף בהחיבור דהנשמה והגוף<sup data-n=\"2646\">42</sup> לאריכות ימים ושנים טובות, תורה ומצוות יאָרן<sup data-n=\"2647\">43</sup>, חסידישע יאָרן, ובאופן דהרחבה עד למרחב העצמי, והולכים לקראת משיח צדקנו, ובאופן דשמחת עולם על ראשם<sup data-n=\"2648\">44</sup>.\n**********",[["2604","*","יצא לאור ב<b>קונטרס</b>*<b> כ\"ף מרחשון – תשנ\"ב</b>, \"לקראת כ\"ף מרחשון הבעל\"ט, יום הולדת את כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע . . <i>מוצש\"ק פ' וירא ה'תשנ\"ב</i>\"."],["2605","1","ריש פרשתנו."],["2606","2","דשנת פר\"ת – נדפס בסה\"מ פר\"ת ס\"ע קמ ואילך. וכנראה שהוא מיוסד על מאמר ד\"ה זה בסה\"מ תר\"ל ע' יט ואילך."],["2607","3","פרשתנו (קכב, א)."],["2608","4","קהלת ה, ח."],["2609","5","זהר שם (קכב, ב)."],["2610","6","כדלקמן סעיף ט."],["2611","7","בכמה ענינים דלקמן ראה גם ביאוה\"ז לאדהאמ\"צ בהוספות קכט, ד ואילך. וראה גם ד\"ה נחמו עת\"ר (בסה\"מ עת\"ר ע' ריח. ע' רכב ואילך). לקמן ח\"ד ע' קסח ואילך.\n*) <i>קונטרס זה חילק כ\"ק אדמו\"ר שליט\"א בידו הק' לכאו\"א מאנשים נשים וטף</i>."],["2612","8","סה\"מ עת\"ר ע' רטו ואילך."],["2613","9","בראשית ב, טו."],["2614","10","אוה\"ת בראשית (כרך ו תתרמא, סע\"ב – בשם ארז\"ל). וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381323\" data-slug=\"likkutei-torah\" data-id=\"4001381323\">לקו\"ת שה\"ש (מח, ד</a>). יל\"ר עה\"פ בראשית שם. זח\"א כז, א. תקו\"ז תכ\"א (סב, א). שם תנ\"ה (פח, ב)."],["2615","11","בראשית ג, כג."],["2616","12","אבל מ\"מ \"אין זה דומה כלל לכמו שהי' קודם\" (סה\"מ עת\"ר שם)."],["2617","13","ראה זח\"ג רנז, סע\"ב (ברע\"מ). פרדס שער יג (שער השערים) ספ\"ו. הנסמן לקמן ח\"ד ע' קסט הערה 26."],["2618","14","ראה תו\"א ס\"פ תרומה (פא, ב). המשך תרס\"ו ע' רפד ואילך. ובכ\"מ."],["2619","15","תקו\"ז בהקדמה (\"פתח אליהו\") יז, א."],["2620","16","ראה גם סה\"מ ה'ש\"ת ע' 24 (דזהו החילוק בין מדות למלכות). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061125\" data-slug=\"likkutei-sichot\" data-id=\"1300061125\">לקו\"ש ח\"ו ע' 114</a> ואילך."],["2621","17","ע\"ד הלבנה (ששרשה היא מהמלכות), שע\"י שהיא מקבלת את אור השמש (ז\"א) היא משנית את האור, שנעשה אור הלבנה ולא אור השמש."],["2622","18","וע\"ד והי' אור הלבנה כאור החמה (ישעי' ל, כו), דהגם שגם אז תקבל הלבנה מהחמה, מ\"מ \"לא יהי' שינוי האור כלל בהלבנה מכמו שהוא בהחמה\" (המשך תרס\"ו ע' רצא)."],["2623","19","ב\"ב טז, סע\"ב ואילך."],["2624","20","חיי שרה כד, א."],["2625","21","תולדות כז, לג."],["2626","22","וישלח לג, יא."],["2627","23","ראה פרדס שבהערה 13. מאמרי אדמו\"ר האמצעי דברים ח\"ב ע' תרפז. וש\"נ."],["2628","24","ראה שערי אורה פה, ב."],["2629","25","ראה גם לקו\"ת שבת שובה סז, ד."],["2630","26","דברי הימים-א כט, יא."],["2631","27","ראה ע\"ח שער מב (שער דרושי אבי\"ע) פ\"א. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380276\" data-slug=\"likkutei-torah\" data-id=\"4001380276\">לקו\"ת בחוקותי מו, ג</a>. ובכ\"מ."],["2632","28","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310092\" data-slug=\"tanya\" data-id=\"3401310092\">תניא</a> <a class=\"ft-cite\" href=\"#/read/tanya/3401310092\" data-slug=\"tanya\" data-id=\"3401310092\">אגה\"ק סט\"ו (קכב, סע\"א</a>). סהמ\"צ להצ\"צ יב, ב ואילך. המשך תרס\"ו ע' רפט. ובכ\"מ."],["2633","29","ראה בארוכה המשך תער\"ב ח\"ב ע' תתקלד ואילך. סה\"מ תרפ\"ז ע' לט ואילך. ובכ\"מ."],["2634","30","כמפורש בהמאמר (סה\"מ פר\"ת ע' קמה)."],["2635","31","ישעי' סו, כב. וראה בארוכה בהמאמר שם (ע' קמו)."],["2636","32","<a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא פל\"ז</a>."],["2637","33","ראה <i>עד\"ז</i> לקמן ח\"ד ע' רכ."],["2638","34","פרש\"י ר\"פ בראשית."],["2639","35","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["2640","36","דנוסף לזה שגם בתחילת הבריאה המקום דכללות העולם הי' \"תחתון\"*, הרי שע\"י חטא עה\"ד נעשה תחתון עוד יותר.\nויש לומר, דשני הענינים שבה\"תחתון\" דעולם [שמצד עצמו ושע\"י חטא עה\"ד] הם ע\"ד שני הענינים דלקמן בפנים ובהערה הבאה – ארץ, ושדה דלעו\"ז."],["2641","37","להעיר, שבזהר שם יש עוד פירוש במלך לשדה נעבד (הובא גם במאמר הנ\"ל ע' קמו ואילך), שהמלכות דקדושה נעבדת לשדה דלעו\"ז. ויש לומר (וראה עד\"ז לקמן ח\"ד ע' קעא), דזה שפירוש זה במלך לשדה נעבד בא לאחרי ובהמשך להפירוש דמלך לשדה נעבד הוא מלך עילאה דאתחבר לשדה כד איהו נעבד, הוא, כי הכוונה בשדה דלעו\"ז הוא שיתהפך לקדושה, והגילוי דמלך עילאה יומשך גם לשם [ובאופן נעלה יותר, ע\"ד המעלה בתשובה]."],["2642","38","ועפ\"ז יומתק לשון הזהר \"מלך עילאה דאתחבר <i>לשדה</i>\", דנוסף לזה שתחלת ההמשכה היא בשדה ועי\"ז נמשכת גם בארץ, יש לומר שבזה מרמז שגם ההמשכה בארץ היא באופן ד\"שדה\"."],["2643","39","להעיר ממ\"ש בהמאמר (ע' קמז) דעשרים שנה ושבע שנים \"הו\"ע ויתרון <i>ארץ</i> בכל היא\" – אף שלכאורה הול\"ל שהוא בחינת כל.\n*) <i>דנוסף לזה שלא הי' מוכשר להגילוי שע\"י מצוות דקרקע הג\"ע</i>,<i> הי' </i>\"<i>צ\"ל </i><b>תיקון</b><b><i> בכללות העולם</i></b>\"<i> (אלא שלולי חטא עה\"ד הי' התיקון בדרך ממילא) – ראה סה\"מ עת\"ר שבהערה 8</i>."],["2644","40","פרש\"י עה\"פ (ריש פרשתנו)."],["2645","41","זהר פרשתנו קכב, ב (במדרש הנעלם)."],["2646","42","דכל שהגוף מזדכך יותר, רוצה הנשמה להיות בהגוף, וזה שבשרה הי' ההיפך מזה, הוא מפני סיבה צדדית, ראה פרש\"י עה\"פ."],["2647","43","ראה \"היום יום\" ו' חשון."],["2648","44","ישעי' לה, יו\"ד. נא, יא."]]],[1500360040,"<h3>– יום הולדת כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע –</h3><h3>ה'תשמ\"א<sup data-n=\"2649\">*</sup></h3>\n<b>ויהיו</b> חיי שרה מאה שנה ועשרים שנה ושבע שנים שני חיי שרה<sup data-n=\"2650\">1</sup>, ומדייק כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע בעל יום ההולדת במאמרו ד\"ה זה דשנת עטר\"ת<sup data-n=\"2651\">2</sup>, מהו אומרו שני חיי שרה, הרי כבר נאמר ויהיו חיי שרה [ומפרט שנותי' במאות עשיריות ואחדות], ולמה כפל עוד לומר שני חיי שרה. וגם צ\"ל (כמו שמדייק בזהר<sup data-n=\"2652\">3</sup>) מפני מה בשרה דוקא נאמר ימי שני חיי' [ועד שכל הפרשה (חיי שרה) נקראת על שם זה, שמזה משמע<sup data-n=\"2653\">4</sup> שזהו תוכן כל הסדרה], שלא נאמר זה בשארי אמהות<sup data-n=\"2654\">5</sup>. ומביא בזה מאמר הזהר<sup data-n=\"2655\">6</sup>, אתת חוה לעלמא ואתדבקת בחויא<sup data-n=\"2656\">7</sup> כו' אתא נח<sup data-n=\"2657\">8</sup> לעלמא מה כתיב בי'<sup data-n=\"2658\">9</sup> וישת מן היין וישכר כו' אתת שרה ונחתת וסלקת [ולא אתדבקת בי'<sup data-n=\"2659\">10</sup>] כד\"א<sup data-n=\"2660\">11</sup> ויעל אברם ממצרים הוא ואשתו ובגין כך זכתה לחיין עילאין. ומסיים (בזהר שם) ועל דא דילה הוו חיין. ועפ\"ז מבאר כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע במאמרו הנ\"ל<sup data-n=\"2661\">12</sup> שני דיוקים הנ\"ל, שדוקא בשרה נאמר ימי שני חיי' (שלא נאמר בשאר אמהות) לפי שדוקא שרה, ע\"י שנחתת וסלקת, זכתה לחיין עילאין. ומה שכפל עוד פעם לאמר שני חיי שרה, אף שכבר נאמר בתחלה ויהיו חיי שרה, הוא כי \"ויהיו חיי שרה\" הוא מה שזכתה לחיין עילאין, ו\"שני חיי שרה\" הו\"ע \"דילה הוו חיין\", דלא רק שזכתה לחיין עילאין אלא גם שהחיין נעשו שלה, \"דילה הוו\". וצריך להבין תוכן שני ענינים אלו. וגם צריך להבין, דמלשון הזהר אתת חוה אתא נח אתת שרה מובן, שיש שייכות בין ג' ענינים אלו. היינו דחוה ונח רצו לפעול אותו הענין שפעלה שרה, אלא שלאעלתה בידם, ולא עוד אלא שעי\"ז נעשית אצלם ירידה (אתדבקת בחויא, וישכר). משא\"כ שרה, אף שגם אצלה היתה (בתחלה) ירידה, ע\"י ירידה זו הי' אח\"כ העלי', נחתת וסלקת. וצריך להבין השייכות דג' ענינים אלו.\nב) <b>והנה</b> מעשה אבות סימן לבנים<sup data-n=\"2662\">13</sup>, וידוע שהכוונה בסימן כאן היא לא רק סימן והוראה אלא גם נתינת כח<sup data-n=\"2663\">14</sup>. וע\"ד הידוע<sup data-n=\"2664\">15</sup> בענין פתח ר' פלוני וכו', דלאחרי שפתח את הצינור והדרך, ועאכו\"כ כאשר סלל את הדרך, הרי עי\"ז ניתן הכח לכאו\"א שיוכל לעשות עבודה זו, ואינו צריך ליגיעה גדולה כ\"כ (כבפעם הראשונה)<sup data-n=\"2665\">16</sup>. ועאכו\"כ שכן הוא במעשה אבות, מכיון שהם האבות של כאו\"א מישראל, והענינים והעבודות שלהם נמשכים בירושה לכאו\"א מישראל<sup data-n=\"2666\">17</sup>. וכן הוא גם בנוגע לאמהות<sup data-n=\"2667\">18</sup>, ובפרט בנוגע לשרה אמנו, הראשונה שבד' אמהות, וכתיב בה<sup data-n=\"2668\">19</sup> כל אשר תאמר אליך שרה שמע בקולה. ומזה מובן דענין הנ\"ל, אתת שרה ונחתת וסלקת, הוא (ככל מעשה אבות ואמהות) הוראה וגם נתינת כח בעבודתו של כאו\"א מישראל<sup data-n=\"2669\">20</sup>. וצריך להבין ההוראה דנחתת וסלקת בהעבודה דבנים לאחרי מ\"ת.ג) <b>ונקודת</b> הענין בזה הוא כמו שמבאר בעל יום ההולדת במאמרו הנ\"ל<sup data-n=\"2670\">21</sup>, דעבודת ה' צריכה להיות בשמחה דוקא כמ\"ש<sup data-n=\"2671\">22</sup> עבדו את ה' בשמחה. ועד שהשמחה בעבודת ה' היא עיקר גדול, וכידוע פירוש האריז\"ל<sup data-n=\"2672\">23</sup> והובא בתניא<sup data-n=\"2673\">24</sup> עה\"פ<sup data-n=\"2674\">25</sup> תחת אשר לא עבדת את ה' אלקיך בשמחה וגו', ואיתא בתו\"א<sup data-n=\"2675\">26</sup> דמה שהאריז\"ל זכה לרוה\"ק<sup data-n=\"2676\">27</sup> הוא ע\"י שמחה של מצוה [ומכיון שזהו סיפור בתורה (שבעל פה) מלשון הוראה<sup data-n=\"2677\">28</sup>, הרי זה הוראה לכאו\"א מישראל], דכאשר העבודה היא בשמחה, אז העבודה היא בשלימות [ועי\"ז נעשה שלימות גם בהעולם. שהרי תכלית הבריאה היא בשביל ישראל שנקראים ראשית<sup data-n=\"2678\">29</sup>, ופירוש בשביל ישראל הוא בשביל העבודה דישראל [שזהו עיקר מציאותם, כמארז\"ל<sup data-n=\"2679\">30</sup> אני לא נבראתי אלא לשמש את קוני], היינו שישראל ע\"י עבודתם פועלים שהעולם יהי' בתכלית השלימות. דהגם שעולם על מילואו נברא<sup data-n=\"2680\">31</sup>, ובפרט ע\"פ הידוע<sup data-n=\"2681\">32</sup> שמהטעמים על בריאת העולם הוא לפי שעלה ברצונו ית' להטיב לברואיו, שטבע הטוב להטיב<sup data-n=\"2682\">33</sup>, שמזה מובן שבריאת העולם (מלכתחילה) הי' בשלימות, מ\"מ, ענין זה גופא דלהטיב לברואיו, הוא אחד הטעמים על זה שעלה ברצונו ית' שהבריאה תהי' בשביל<sup data-n=\"2678\">29</sup> ישראל ובשביל התורה, שעי\"ז יושפע להנבראים שלימות הטוב, ע\"י שישראל ע\"י עבודתם יוסיפו שלימות בהעולם, שלימות נעלית יותר מהשלימות דעולם כמו שהוא מצד הבריאה. ומכיוןששלימות העבודה היא כאשר היא בשמחה, לכן עי\"ז מתוסף גם בהשלימות דעולם, שנעשה ע\"י עבודת ישראל]. ולא זו בלבד ששלימות העבודה היא כאשר היא בשמחה, אלא שהשמחה בעבודת ה' היא גם הכרח בעבודת ה', שלכן כאשר חסר השמחה בעבודת ה' מגיע על זה עונש ח\"ו כמ\"ש&lt;25&gt; תחת אשר לא עבדת את ה' אלקיך בשמחה וגו', כי ענין העבודה הוא להמשיך גילוי אלקות למטה וזה נעשה ע\"י השמחה.\n<b>אך</b> ביחד ע\"ז כתיב<sup data-n=\"2683\">34</sup> עבדו את ה' ביראה, אלא שבפסוק זה עצמו ממשיך <i>וגילו</i> ברעדה, שצ\"ל שמחה. אלא כאשר השמחה היא במורגש, אפשר שמזה יבוא להרגשת הישות, ועי\"ז לכמה דברים בלתי רצויים שמסתעפים מזה. ולכן צ\"ל עבדו את ה' ביראה וגילו ברעדה, שעי\"ז תהי' השמחה (שלא בבחי' מורגש, כ\"א) בבחי' ביטול וענוה, ובלשון הכתוב<sup data-n=\"2684\">35</sup> ויספו ענוים בה' שמחה, שהשמחה היא ביחד או מצד הענוה והביטול (וכדלקמן סעיף ו).\nד) <b>ועפ\"ז</b> מבאר בעל יום ההולדת במאמרו הנ\"ל<sup data-n=\"2685\">36</sup> ענין אתת חוה כו' אתת שרה כו', שהצד השוה שבהם הוא שרצו לפעול ענין השמחה. כמארז\"ל גבי חוה<sup data-n=\"2686\">37</sup> אשכול של ענבים סחטה ונתנה לו, ובנח כתיב<sup data-n=\"2687\">38</sup> ויטע כרם וישת מן היין, דיין הו\"ע השמחה כמ\"ש<sup data-n=\"2688\">39</sup> יין המשמח אלקים ואנשים. אלא שבחוה היתה השמחה בבחי' מורגש, דבחוה כתיב<sup data-n=\"2689\">40</sup> ותרא האשה כי טוב העץ למאכל וכי תאוה הוא גו' שזהו\"ע ההרגשה<sup data-n=\"2690\">41</sup>. ונח רצה לתקן את חטא עה\"ד<sup data-n=\"2691\">42</sup>, שהוא ענין ההרגשה, ע\"י הרגשה, ולא עלתה בידו. דוישת מן היין הביא אותו (לא לשמחה שבבחי' ביטול, יין המשמח, כי אם) לוישכר, יין המשכר. והגם דבשכרות הוא העדר ההרגשה, אבל העדר ההרגשה שבזה הוא לא מצד הענוה והביטול כ\"א מצד בלבול הדעת (וההרגשה). והתיקון על חטא עה\"ד (ענין ההרגשה) נעשה ע\"י שרה דוקא [כמבואר בקבלה<sup data-n=\"2692\">43</sup> ששרה תיקנה מה שקלקלה חוה], דשרה היא בחי' מלכות<sup data-n=\"2693\">44</sup> [שלכן נקראת שרה מלשון<sup data-n=\"2694\">45</sup> שררה]<sup data-n=\"2695\">46</sup>,ענין הביטול, ולכן על ידה דוקא נעשה התיקון, שמחה שבבחי' ביטול. וזהו אתת שרה ונחתת וסלקת, שמצד הביטול שבמלכות הנה גם כשהיא יורדת למטה, הירידה (נחתת) היא בשביל העלי' (וסלקת), דירידת המלכות למטה היא בכדי לברר ולתקן הניצוצות דקדושה שנמצאים למטה ולהעלותם למעלה. וכמו\"כ הוא בירידת (אברהם ו)שרה למצרים (בגשמיות), שזה הי' בכדי<sup data-n=\"2696\">47</sup> שהעלי' ממצרים, ויעל אברם ממצרים הוא ואשתו&lt;11&gt;, תהי' באופן של ואברם כבד מאד במקנה בכסף ובזהב<sup data-n=\"2697\">48</sup>, שזה נעשה ע\"י שרה כמ\"ש<sup data-n=\"2698\">49</sup> ולאברם הטיב בעבורה. ועי\"ז זכתה לחיין עילאין, ועד אשר <i>דילה</i> הוו חיין, שהחיין הן דילה (גם) במורגש, דלהיות שהמלכות היא בבחי' ביטול בעצם לכן גם המורגש שבה הוא בבחי' ביטול. ובעבודה הוא, דגם כשהשמחה היא בהתגלות מ\"מ היא בבחי' ביטול [ובדוגמת מלך שעם היותו ברוממות ובשמחה, עוז וחדוה במקומו<sup data-n=\"2699\">50</sup>, אין זה בבחי' ישות]. ולכן משמחה זו, הנה נוסף על שאינו שייך שיהיו מזה תוצאות בלתי רצויות (כמו שהי' בחוה ובנח), אלא אדרבא היא מביאה לתכלית העילוי, ועד לדרגא שבדוגמת לעתיד לבוא, וכמבואר בהמאמר (של בעל יום ההולדת)<sup data-n=\"2700\">51</sup> שענין דילה הוו חיין הוא דוגמת ונחי' לפניו<sup data-n=\"2701\">52</sup> שיהי' לעתיד, חיים בתכלית השלימות.\nה) <b>ויש</b> לקשר זה עם הכתוב<sup data-n=\"2702\">53</sup> אז ימלא שחוק פינו, שלעתיד לבוא תהי' השמחה בתכלית השלימות, ועד שהשמחה דעכשיו, גם כשהיא בתכלית השלימות (עד כמה שאפשר להיות עכשיו), היא באין ערוך לגבי השמחה והשחוק שיהיו לעתיד לבוא<sup data-n=\"2703\">54</sup>, אז <i>ימלא</i> שחוק פינו. והגם שהשמחה דלעתיד לבוא תבוא (ככל הענינים דלעתיד<sup data-n=\"2704\">55</sup>) ע\"י עבודת ה' בשמחה במשך זמן הגלות, מ\"מ השכר שיהי' מזה לעתיד לבוא (אז ימלא שחוק פינו) הוא שלא בערך ועד שלא בערך כלל, ועד שהוא למעלה מגדר שכר. ועפ\"ז יש לבאר מה שבנה של שרה, ששרה התפללה עליו וביותר (עוד יותר מאברהם אבינו<sup data-n=\"2705\">56</sup>), נקרא בשם יצחק על שם צחוק עשה לי אלקים<sup data-n=\"2706\">57</sup>, כי ענין דילה הוו חיין (דשרה) הוא כמו ונחי' לפניו שיהי' לעתיד (כנ\"ל מהמאמר דבעל יום ההולדת), וזהו שבנה של שרה הוא יצחק שענינו הוא צחוק ושמחה, ועד לשחוקושמחה שבדוגמת ימלא שחוק פינו דלעתיד לבוא<sup data-n=\"2707\">58</sup>, שלכן לעתיד לבוא יאמרו ליצחק (דוקא) כי אתה אבינו<sup data-n=\"2708\">59</sup>.\nו) <b>וביאור</b> ענין השמחה שבבחי' ביטול (ועד שגם כשהשמחה היא בהתגלות מ\"מ היא בבחי' ביטול), הנה אמיתית ענין השמחה בא מצד הענוה והביטול, כמ\"ש&lt;35&gt; ויספו ענוים בה' שמחה. וביאור השייכות דענוה ושמחה (אף שלכאורה הם שני ענינים הפכיים), מבאר כ\"ק אדמו\"ר הזקן בד\"ה ויספו ענוים בה' שמחה<sup data-n=\"2709\">60</sup> [ובכמה דרושי רבותינו נשיאינו שלאח\"ז<sup data-n=\"2710\">61</sup>, וגם במאמר הנ\"ל של בעל יום ההולדת], דענין הענוה הוא לא שהעניו טועה בעצמו ואינו יודע את מעלותיו, כי אם, דהגם שהוא יודע את המעלות שלו, ועד שיודע את כל המעלות שלו [דכאו\"א מישראל, אפילו אלו שהנהגתם היא שלא כדבעי כלל, לא רק שיש להם מצוות אלא שהמצוות <i>ממלאים</i> את מציאותם, ובלשון רז\"ל<sup data-n=\"2711\">62</sup> <i>מלאים</i> מצוות כרימון, ובפרט אשר ועמך כולם צדיקים<sup data-n=\"2712\">63</sup> וכל ישראל בחזקת כשרות<sup data-n=\"2713\">64</sup>], מ\"מ אינו נעשה עי\"ז למציאות בעיני עצמו ועאכו\"כ שאינו בבחי' ישות, כי יודע את האמת שהמעלות שיש לו אינם כחו ועוצם ידו כ\"א ניתנו לו (הכחות על זה) מלמעלה, ובאם היו נותנים כחות אלו לאחר הי' ג\"כ במדריגה זו, ומצד הענוה והביטול שלו הוא חושב, שאילו היו כחות אלו אצל אחר הי' מגלה אותם עוד יותר. וענוה זו [מכיון שהוא יודע את המעלות, אלא שאינו נעשה עי\"ז למציאות] הנה לא רק שאינה מביאה להיפך השמחה, אלא אדרבא, הענוה והביטול שלו (שחושב שאינו מגיע לו כלום) מביאה אותו לשמחה גדולה ושלימה. דשלימות השמחה היא דוקא במי שהוא בטל, כמבואר בהמאמר בארוכה. ומכיון שהשמחה באה בסיבת הענוה והביטול, לכן גם השמחה עצמה (גם כשהיא בהתגלות) היא בבחי' ביטול.\nז) <b>וזהו</b> ויהיו חיי שרה גו' שני חיי שרה, ויהיו חיי שרה הוא מה שזכתה לחיין עילאין. ומפרט בזה מאה שנה ועשרים שנה ושבע שנים שקאי על כל הספירות<sup data-n=\"2714\">65</sup>. וכמבואר בהמאמר<sup data-n=\"2715\">66</sup> דמאה שנה הוא בחי' אריך כמו שמאיר בו בחי'עתיק, שלכן נאמר (מאה) שנה לשון יחיד, ויש לומר שבנדו\"ד למעלה מבחי' אחד<sup data-n=\"2716\">67</sup>. ועשרים שנה הוא בחי' חו\"ב, ושבע שנים הוא בחי' ז' מדות, שבעת ימי הבנין. ואח\"כ מוסיף שני חיי שרה, דילה הוו חיין, שהחיין הן דילה (גם) במורגש, שבעבודה הו\"ע הביטול בהשמחה (גם) כמו שהיא בהתגלות (כנ\"ל מהמאמר דבעל יום ההולדת). וזהו גם הטעם לזה שבהסיום שני חיי שרה אינו מפרט המספרים דמאה עשרים ושבע, כי זה שגם המורגש הוא בביטול, שהוא יחוד שני ענינים הפכים (מורגש וביטול), הוא מבחי' שלמעלה מהתחלקות<sup data-n=\"2717\">68</sup>. וזהו העילוי דשני חיי שרה על חיי שרה מאה שנה וגו', דענין מאה שנה ועשרים שנה ושבע שנים, עם היותו נעלה ביותר, כמובן גם מפרש\"י עה\"פ, מ\"מ הם ג' ענינים חלוקים, משא\"כ שני חיי שרה הוא שכולן שוין<sup data-n=\"2718\">69</sup>, למעלה מהתחלקות. ומצד בחינה זו (שלמעלה מהתחלקות), גם המורגש הוא בביטול<sup data-n=\"2719\">70</sup>, דילה הוו חיין.\n<b>ויש</b> לומר, דע\"י ענין דילה הוו חיין בעבודה, שגם המורגש (שמחה שבהתגלות) הוא בביטול (כפירוש בעל יום ההולדת בדידה הוו חיין), עי\"ז נעשה דילה הוו חיין גם בפשטות, שהחיים הן שלה והיא נעשית בעה\"ב על החיים. כי שמחה פורץ כל הגדרים<sup data-n=\"2720\">71</sup>, ולכן ע\"י השמחה בהתגלות (ובבחי' ביטול) נעשה תגבורת החיים (למעלה מגדר והגבלה), וע\"ד הידוע<sup data-n=\"2721\">72</sup> בענין יצחק [שענינו הוא צחוק ושמחה, כנ\"ל], שהגבורות דיצחק הו\"ע תגבורת החיות (ותגבורת הברכות), ועד לחיים בתכלית השלימות, דוגמת ונחי' לפניו שיהי' לעתיד לבוא.\nח) <b>ומעשה</b> אבות סימן לבנים, שהעבודה דשרה היא הוראה ונתינת כח לכאו\"א מישראל [ועד שענין זה שבכאו\"א מישראל הוא (ככל הענינים דהאבות והאמהות) בירושה<sup data-n=\"2722\">73</sup>], שיוכל לעבוד את ה' בשמחה בהתגלות, והשמחה תהי' מיוסדתעל ענין הביטול, ונפשי כעפר לכל תהי'<sup data-n=\"2723\">74</sup>. ולכן אין חשש<sup data-n=\"2724\">75</sup> שיסתעף מזה איזה ענין בלתי רצוי ח\"ו, ואדרבא, מכיון ששמחה פורץ גדר, הנה ע\"י השמחה יוסיף אומץ בעבודתו ביתר שאת וביתר עז, עד לעבודה שלמעלה ממדידה והגבלה, ענין תגבורת החיות בעבודה. ועי\"ז נעשה גם תגבורת החיים כפשוטו, אריכות ימים ושנים טובות בפשטות.\nט) <b>ויש</b> לקשר זה עם יום ההולדת של כ\"ק אדמו\"ר נ\"ע דשנה זו, (סיום וחותם) שנה המאה ועשרים<sup data-n=\"2725\">76</sup>, דאיתא בזהר<sup data-n=\"2726\">77</sup> עה\"פ<sup data-n=\"2727\">78</sup> והיו ימיו מאה ועשרים שנה שהוא רמז למשה כו' שממשיך חיין לבני נשא (לכאו\"א מישראל) מההוא אילנא דחיין, שבזה נכלל גם אריכות ימים בפשטות, וכדאיתא בזהר שם (לפנ\"ז) בשגם<sup data-n=\"2727\">78</sup> דא משה<sup data-n=\"2728\">79</sup> כו' ומחילא דא קיימין בני נשא בעלמא יומין סגיאין. וענין זה ממשיך משה גם עכשיו, כמו שממשיך בזהר שם משה לא מית כו', וארז\"ל<sup data-n=\"2729\">80</sup> מה להלן עומד ומשמש אף כאן עומד ומשמש. וכמו שהוא במשה רבינו רעיא מהימנא, כמו\"כ הוא ברועי ישראל שבכל דור ודור, עד לבעל יום ההולדת ובנו כ\"ק מו\"ח אדמו\"ר ממלא מקומו, וכידוע המכתב של כ\"ק מו\"ח אדמו\"ר<sup data-n=\"2730\">81</sup> (בנוגע לאביו. ומזה מובן שכ\"ה גם אצלו<sup data-n=\"2731\">82</sup>) שרועי ישראל לא יפרדו ח\"ו מעל צאן מרעיתם, שהוא ע\"ד מארז\"ל הנ\"ל בנוגע למשה מה להלן עומד ומשמש אף כאן עומד ומשמש, שגם עכשיו הוא (בעל יום ההולדת, ובמילא מובן – בנו ממלא מקומו) ממליץ זכות על כל אחד ואחת מישראל, וממשיך להם ברכות הצלחות וישועות, ועד שממשיך מבחי' אילנא דחיין (עץ החיים) וגם אריכות ימים בפשטות לכל אחד ואחת מישראל.\nי) <b>והנה</b> כמו שענין דילה הוו חיין (דשרה) הוא דוגמת ונחי' לפניו שיהי' לעתיד (כנ\"ל סוף סעיף ד וסעיף ה מהמאמר דבעל יום ההולדת), עד\"ז הוא גם בענין הנתינת כח שנמשך מזה לכל אחד מישראל על העבודה בשמחה (כנ\"ל סעיף ח), שע\"י העבודה בשמחה נזכה בקרוב ממש לקיום היעוד&lt;52&gt; ביום השלישי יקימנו ונחי' לפניו. והענין הוא, דהנה מבואר בלקו\"ת (ד\"ה יחיינו מיומיים ביום השלישייקימנו ונחי' לפניו<sup data-n=\"2732\">83</sup>), דיומיים הם בחי' ממכ\"ע וסוכ\"ע, וביום השלישי הוא בחי' שלמעלה גם מבחי' סוכ\"ע. היינו שאין בו שום מדידות והגבלות, גם לא המדידה דסוכ\"ע. ומכיון ששמחה פורץ גדר, וע\"י השמחה מגיעים (כנ\"ל סעיף ח) לעבודה שלמעלה ממדידה והגבלה, לכן השמחה (בעבודת ה') היא הכנה קרובה וכלי לגילוי בחי' ביום השלישי (יקימנו ונחי' לפניו), בחי' שלמעלה (גם) מבחי' סוכ\"ע, שגילוי זה יהי' בביהמ\"ק השלישי, וכהפירוש<sup data-n=\"2733\">84</sup> דביום השלישי קאי על ביהמ\"ק השלישי, שיבנה מלך המשיח<sup data-n=\"2734\">85</sup>, מלך מבית דוד<sup data-n=\"2735\">86</sup>. וגם ענין זה שייך במיוחד לענין השמחה, כמובן מזה שהרמב\"ם<sup data-n=\"2736\">87</sup> מביא ראי' על ענין השמחה שישמח אדם (כל אדם) בעשיית המצוה מדוד מלך ישראל דכתיב בי'<sup data-n=\"2737\">88</sup> והמלך<sup data-n=\"2738\">89</sup> דוד מפזז ומכרכר לפני ה' וגו'. ויש לומר הביאור בזה, דדוד מלך ישראל הו\"ע ספירת המלכות<sup data-n=\"2739\">90</sup>, וזהו שהי' בתכלית הביטול, אם לא שויתי ודוממתי<sup data-n=\"2740\">91</sup>, כי מלכות היא בחי' ביטול, כנ\"ל (סעיף ד). וזהו שעבודתו היתה בשמחה גדולה, והמלך דוד מפזז ומכרכר לפני ה', כי מצד הביטול דמלכות גם כשהשמחה היא בהתגלות אין שייך שיסתעף מזה ענין בלתי רצוי. ומכיון שדוד מלך ישראל חי וקיים<sup data-n=\"2741\">92</sup>, היינו שהוא חי וקיים (בכאו\"א מישראל) בתור דוד <i>מלך</i> ישראל (הביטול דמלכות), לכן הוא נותן הכח לכל אחד מישראל שישמח בעשיית המצוה (אף שעבודה גדולה היא<sup data-n=\"2742\">93</sup>), ושהשמחה תהי' באופן הרצוי.\nיא) <b>וע\"י</b> השמחה בעשיית המצוה, כולל גם בקיום הציווי<sup data-n=\"2743\">94</sup> וכל<sup data-n=\"2744\">95</sup> מעשיך יהיו לשם שמים ובכל<sup data-n=\"2745\">96</sup> דרכיך דעהו, יפרצו את גדרי הגלות, ואתי מר דאמלכא משיחא, דוד מלך ישראל, יחד עם משה רבינו רעיא מהימנא, שהרי גואל ראשון הוא גואל אחרון<sup data-n=\"2746\">97</sup>, כולל גם הרעיא מהימנא שבכל דור ודור עד להרעיא מהימנא של דורנו הוא כ\"ק מו\"ח אדמו\"ר נשיא דורנו,\n<b>שבקרוב</b> ממש תקויים ההבטחה הקיצו ורננו שוכני עפר<sup data-n=\"2747\">98</sup> ועמהם יחד נלך לקבל פני משיח צדקנו, ושמחת עולם על ראשם<sup data-n=\"2748\">99</sup>, במהרה בימינו ממש.\n**********",[["2649","*","יצא לאור ב<b>קונטרס כ\"ף מרחשון – תשמ\"ח</b>, \"לקראת כ\"ף מרחשון הבעל\"ט, יום הולדת כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע . . <i>מוצש\"ק ט\"ו מ\"ח</i>,<i> שנת הקהל</i>,<i> שנת תשמח</i>\"."],["2650","1","ריש פרשתנו."],["2651","2","נדפס בסה\"מ עטר\"ת ע' פז ואילך."],["2652","3","ח\"א פרשתנו קכב, רע\"א."],["2653","4","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300051057\" data-slug=\"likkutei-sichot\" data-id=\"1300051057\">לקו\"ש ח\"ה ע' 57</a> ואילך."],["2654","5","כ\"ה הלשון ברד\"ה הנ\"ל שם. ולהעיר, שבזהר שם (קכא, סע\"ב) \"מכל נשי <i>דעלמא</i>\" [וגם בהדוגמאות שבזהר שם, רובן אינן מהאמהות]."],["2655","6","שם קכב, ב. – הלשון כאן נעתק מרד\"ה הנ\"ל שם."],["2656","7","כ\"ה בד\"ה הנ\"ל שם. ועד\"ז בד\"ה תחת אשר לא עבדת גו' לאדמו\"ר הזקן (סה\"מ תקס\"ב ח\"א ע' עח) ולאדמו\"ר האמצעי (מאמרי אדהאמ\"צ דברים ח\"ב ע' תרצב). ובזהר שם: אתדבקת בהאי חויא."],["2657","8","כן הוא (אתא נח לפני אתת שרה) בד\"ה הנ\"ל עטר\"ת שם. ועד\"ז גם בד\"ה הנ\"ל לאדה\"ז (ע' עה. שם ע' עח) ולאדהאמ\"צ (ע' תרפב. שם ע' תרצג). ובזהר שם אתא נח כו' הוא לאחרי אתת שרה כו'."],["2658","9","נח ט, כא."],["2659","10","בד\"ה הנ\"ל (עטר\"ת שם) לא נעתקו תיבות אלו."],["2660","11","לך לך יג, א."],["2661","12","בסופו (סה\"מ עטר\"ת ע' צז)."],["2662","13","ראה רמב\"ן עה\"פ לך לך יב, ו: כל מה שאירע לאבות סימן לבנים. וראה תנחומא לך לך ט. ב\"ר פ\"מ, ו. אוה\"ת ר\"פ לך לך (עב, סע\"ב)."],["2663","14","ראה אוה\"ת שם (עג, א): מעשה כו' סימן לבנים <i>שיוכלו</i> אח\"כ כו'. וראה גם ב\"ר שם (הובא ברמב\"ן עה\"פ שם, י): צא <i>וכבוש את הדרך</i> לפני בניך. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201110\" data-slug=\"likkutei-sichot\" data-id=\"1300201110\">לקו\"ש ח\"כ ע' 110</a> ובהנסמן שם בהערה 21."],["2664","15","סה\"מ תרע\"ח ע' רפג. תרפ\"ח ע' קב. ובכ\"מ."],["2665","16","עד\"ז מצינו גם בנוגע להבנה בתורה: מרן הקדוש [הב\"י] ז\"ל הוקשה לו בבית מדרשו לשון הרמב\"ם קשה מאד כו', ולילה א' כו' בא לדעתו ישוב נכון ושמח הרבה. ולמחר כו' נענה ת\"ח רך בשנים כו' ואמר לו הת\"ח הדרך כמו שהוא כו', מרן ז\"ל נצטער שכל מה שטרח הוא ז\"ל אותו הת\"ח אמרו בנקל, ואמר לו המגיד אל תצטער, שאתה זכית לטורח מאד ועי\"ז כוונת אל האמת כו', אך אחר שטרחת והוצאת לאור הענין עתה כל חכם יכול להבינו כו' – חומת אנ\"ך להחיד\"א משלי ג. וראה גם מגיד מישרים פ' תצא. אורים גדולים (לר' אברהם ישראל זאבי, אזמיר תקי\"ח) חלק אור לישרים לז, א. מדבר קדמות להחיד\"א מערכת יו\"ד ערך יוסף (סי' ח\"ן). ובכתר שם טוב (הוצאת קה\"ת) סרנ\"ו (לד, סע\"ד ואילך), ועד\"ז בתולדות יעקב יוסף פ' צו הובא שהאריז\"ל אמר להב\"י כו'. ובמאה שערים (כח, סע\"א ואילך) ביאור אדה\"ז בהנהגת הה\"מ ממעזריטש. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131209\" data-slug=\"likkutei-sichot\" data-id=\"1300131209\">לקו\"ש חי\"ג ע' 209</a> בהערה."],["2666","17","תו\"א ר\"פ וארא. ובכ\"מ."],["2667","18","בתו\"א שם מיוסד זה על מרז\"ל (ברכות טז, ב) אין קורין אבות אלא לשלשה. ומזה מובן שכ\"ה גם באמהות – מכיון שאין קורין אמהות אלא לארבע (ברכות שם)."],["2668","19","וירא כא, יב. וראה פרש\"י עה\"פ, משמו\"ר פ\"א, א."],["2669","20","והגם שעבודת הבנים היא לאחרי מ\"ת ומעשה אבות הי' לפני מ\"ת – הרי יש מעלה במעשה אבות (שלפני מ\"ת) על עבודת הבנים (שלאחרי מ\"ת), כמרז\"ל (פרש\"י עה\"פ פרשתנו כד, מב, מב\"ר פ\"ס, ח) יפה שיחתן של עבדי (בתי*) אבות לפני המקום מתורתן של בנים, שהרי פרשה של אליעזר כפולה בתורה** והרבה גופי תורה לא נתנו אלא ברמיזה. ומהטעמים לזה הוא, לפי שמעשה האבות הם ענינים כלליים. וכמבואר בכ\"מ (סה\"מ תקס\"ג ח\"א ע' לו ואילך. תו\"ח פרשתנו קלה, א ואילך. אוה\"ת פרשתנו קכז, ב ואילך. ובכ\"מ. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381113\" data-slug=\"likkutei-torah\" data-id=\"4001381113\">לקו\"ת ברכה צו, סע\"ג</a> ואילך) בביאור מרז\"ל הנ\"ל, ד\"שיחתן של עבדי אבות\" – ובפרטיות נישואי יצחק ורבקה דבי' עסקינן*** – הוא <i>כללות</i> ענין התורה ומצוותי', והוא כללות ענין עבודת הבנים לאחר מ\"ת.\n*) <i>כ\"ה בב\"ר שם</i>.\n**) <i>ובב\"ר שם</i>:<i> שנים וג' דפים הוא אומרה ושונה</i>.\n***) <i>שהרי </i>\"<i>ויהיו חיי שרה גו'</i>\"<i> הוא הקדמה לנישואי יצחק ורבקה – ראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300151145\" data-slug=\"likkutei-sichot\" data-id=\"1300151145\">לקו\"ש חט\"ו ע' 145</a> ואילך</i>."],["2670","21","וראה גם ד\"ה תחת אשר לא עבדת גו' לאדה\"ז ס\"ג ואילך (סה\"מ תקס\"ב ח\"א ע' עז ואילך) ולאדהאמ\"צ ס\"ד ואילך (מאמרי אדהאמ\"צ דברים ח\"ב ע' תרפח ואילך). ד\"ה ויספו ענוים בהוי' שמחה לאדהאמ\"צ (מאמרי אדהאמ\"צ נ\"ך ע' כז ואילך). ד\"ה וכה\"ע רואים תרצ\"ז (תש\"י) פ\"ב ואילך והמשכו ד\"ה וירא העם וינועו ס\"ח ואילך (סה\"מ ה'תש\"י ע' 225 ואילך. שם ע' 235 ואילך). ד\"ה עבדו את ה' בשמחה תרצ\"ט (סה\"מ תרצ\"ט ס\"ע 94 ואילך). ועוד."],["2671","22","תהלים ק, ב."],["2672","23","שער רוח הקודש להאריז\"ל (י, ב בהוצאת ירושלים, תער\"ב; לג, ב בהוצאת אה\"ק, תשכ\"ג). הקדמת ס' חרדים (תנאי המצות, התנאי הרביעי), הובא בשל\"ה רלט, סע\"ב ואילך. של\"ה מט, א. ס\"פ תבוא (שפו, א). וראה גם רבינו יונה לברכות רפ\"ה."],["2673","24","פרק כו."],["2674","25","תבוא כח, מז."],["2675","26","תולדות כ, ב. וראה גם מאמרי אדהאמ\"צ: במדבר ח\"ג ע' א'מח, ובהנסמן ב\"מילואים להמראי מקומות\" שם (ס\"ע א'רפ ואילך). דברים ח\"ג ע' תתקד. וש\"נ. סה\"מ תרצ\"ט שם ע' 101. ה'תש\"י שם ע' 235. ועוד."],["2676","27","כ\"ה גם בשל\"ה מט, א. ובהקדמת ס' חרדים שם: שערי החכמה ורוח הקודש. ובכ\"מ בדא\"ח: רוה\"ק וגילוי אליהו."],["2677","28","ראה רד\"ק לתהלים יט, ח (ובס' השרשים שלו ערך ירה). גו\"א ר\"פ בראשית. וראה זח\"ג נג, ב: אמאי אקרי תורה בגין דאורי."],["2678","29","פרש\"י ר\"פ בראשית."],["2679","30","משנה וברייתא סוף מס' קידושין (ע\"פ גירסת הש\"ס כת\"י (אוסף כתבי-היד של תלמוד הבבלי, ירושלים תשל\"ד). וכן הובא במלאכת שלמה למשנה שם. ובכ\"מ. וראה גם יל\"ש ירמי' רמז רעו. ובגירסא הנפוצה \"ואני נבראתי לשמש את קוני\")."],["2680","31","ראה ב\"ר פי\"ד, ז. פי\"ג, ג."],["2681","32","ע\"ח שער הכללים בתחלתו."],["2682","33","ד\"ה אתה אחד לאדמו\"ר האמצעי (מאמרי אדהאמ\"צ קונטרסים ע' ה) בשם הע\"ח (וראה בהערה שם). עמק המלך שער שעשועי המלך רפ\"א. שעהיוה\"א פ\"ד (עט, א). שומר אמונים ויכוח ב סי' יד. ולהעיר משו\"ת ח\"צ סי\"ח."],["2683","34","תהלים ב, יא. וראה מאמרי אדהאמ\"צ דברים ח\"א ע' קצ ואילך. וראה זח\"ג ר\"פ אחרי: עבדו את ה' ביראה וגילו ברעדה, וכתיב עבדו את ה' בשמחה . . הני קראי קשיין אהדדי."],["2684","35","ישעי' כט, יט."],["2685","36","וראה גם ד\"ה תחת אשר לא עבדת גו' לאדה\"ז ס\"ד ואילך (סה\"מ תקס\"ב ח\"א ע' עח ואילך) ולאדהאמ\"צ ס\"ו ואילך (מאמרי אדהאמ\"צ דברים ח\"ב ע' תרצב ואילך)."],["2686","37","ראה ב\"ר פי\"ט, ה. זהר ח\"א לו, סע\"א. קצב, א. ח\"ב רסז, סע\"ב. ועוד. וראה ג\"כ ב\"ר פט\"ו, ז."],["2687","38","נח ט, כ-כא."],["2688","39","ראה ס' שופטים ט, יג. ברכות לה, א."],["2689","40","בראשית ג, ו."],["2690","41","ראה בארוכה סה\"מ עזר\"ת ע' פט ואילך."],["2691","42","זח\"א עג, סע\"א."],["2692","43","ראה קה\"י ערך חוה (ב). שם ערך שרה (פיסקא הב'). וראה ב\"ר ספי\"ז. תנחומא ר\"פ נח וס\"פ מצורע. ביאוה\"ז להצ\"צ כרך ב ע' תתקמב ואילך."],["2693","44","קה\"י ערך שרה שם."],["2694","45","פרש\"י עה\"פ נח יא, כט. וראה גם ברכות יג, א. פרש\"י עה\"פ לך לך יז, טו."],["2695","46","ד\"ה ויהיו חיי שרה עטר\"ת הנ\"ל (ע' צג). וראה גם ד\"ה תחת אשר לא עבדת גו' לאדה\"ז ס\"ד (סה\"מתקס\"ב ח\"א ע' עח) ולאדהאמ\"צ ס\"ז (מאמרי אדהאמ\"צ דברים ח\"ב ריש ע' תרצד). וראה גם אוה\"ת ר\"פ לך לך (עב, ב). ועוד."],["2696","47","ראה אוה\"ת לך לך שם (עג, א). <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201039\" data-slug=\"likkutei-sichot\" data-id=\"1300201039\">לקו\"ש ח\"כ</a> שיחה א' לפ' לך לך ס\"ג (ע' 39 ואילך)."],["2697","48","לך לך יג, ב."],["2698","49","שם יב, טז. וראה לקו\"ש שם ס\"ב ואילך."],["2699","50","דברי הימים-א טז, כד."],["2700","51","בסופו, בד\"ה \"נ\"ל תוכן הענין\" (סה\"מ עטר\"ת ע' צח)."],["2701","52","הושע ו, ב. וראה תרגום, פרש\"י, ראב\"ע ורד\"ק עה\"פ."],["2702","53","תהלים קכו, ב."],["2703","54","להעיר מברכות לא, א. טושו\"ע או\"ח סו\"ס תקס."],["2704","55","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["2705","56","ראה לך לך טז, ב. וברד\"ק שם: ולא המתין כו' כי חשב כי . . מה שיעדו הא-ל לתת לו זרע מהגר יהי'. ולהעיר מפרש\"י עה\"פ שם, ה."],["2706","57","וירא כא, ו. וראה פרש\"י עה\"פ לך לך טז, יט."],["2707","58","ראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560053\" data-slug=\"or-hatorah-hb\" data-id=\"8316560053\">אוה\"ת</a> (יהל אור) לתהלים שם (ריש ע' תצג, ושם ד\"ה בחיי). ולהעיר גם מ<a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">תו\"א (תולדות יז, ד</a> ואילך. ויצא כא, ג. וראה גם תו\"ח ויצא כד, סע\"ד ואילך. ועוד) דזה שנקרא יצחק ע\"ש העתיד הוא לפי שאז יהי' גילוי הצחוק והתענוג (דבחי' יצחק)."],["2708","59","ישעי' סג, טז. שבת פט, ב. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370083\" data-slug=\"torah-or\" data-id=\"3901370083\">תו\"א תולדות יז, ג</a>. תו\"א ותו\"ח ויצא שם. סה\"מ תקס\"ח ח\"א ע' תקכא ואילך. תו\"ח תולדות ד\"ה ואלה תולדות פי\"א ואילך (ד, ד ואילך). ועוד."],["2709","60","תקס\"ב – נדפס בסה\"מ תקס\"ב ח\"א ע' נא ואילך."],["2710","61","ד\"ה ויספו ענוים בהוי' שמחה לאדהאמ\"צ (מאמרי אדהאמ\"צ נ\"ך ע' כח). ד\"ה הנ\"ל תרצ\"ז (תש\"י) – נדפס בסה\"מ ה'תש\"י ע' 237 ואילך. ובד\"ה שלפנ\"ז שם (סה\"מ שם ע' 235 ואילך). ד\"ה עבדו את ה' בשמחה תרצ\"ט ס\"ט (סה\"מ תרצ\"ט ע' 101). ולהעיר גם מביאוה\"ז לאדהאמ\"צ (נט, ב) ולהצ\"צ (ע' שט)."],["2711","62","ערובין יט, א. חגיגה בסופה."],["2712","63","ישעי' ס, כא. סנהדרין ר\"פ חלק."],["2713","64","רמב\"ם הל' קדה\"ח פ\"ב ה\"ב (וראה נו\"כ שם). השגת הראב\"ד לרמב\"ם הל' גירושין פ\"י הי\"ט. ובכ\"מ."],["2714","65","להעיר, שהשנה (תשמ\"ח [שנת הדפסת המאמר בפעם הראשונה]) ימלאו קכ\"ז שנה לבעל יום ההולדת, השלימות דכל הספירות – נתבאר בארוכה בשיחת ש\"פ וירא, ט\"ו מרחשון שנה זו (תשמ\"ח – סה\"ש תשמ\"ח ח\"א ע' 70 ואילך).\nולהעיר ממזמור קכח בתהלים."],["2715","66","ע' צז. וראה בארוכה ביאוה\"ז לאדהאמ\"צ ולהצ\"צ ואוה\"ת ריש פרשתנו. ביאוה\"ז לאדהאמ\"צ בהוספות קלא, סע\"ב ואילך. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670036\" data-slug=\"torat-chaim\" data-id=\"2300670036\">תו\"ח</a> ד\"ה ויהיו חיי שרה ס\"א (קכא, א). שם סכ\"א ואילך (קכו, ב ואילך). סה\"מ תקס\"ו ע' נ ואילך. ד\"ה תחת אשר לא עבדת גו' לאדהאמ\"צ ס\"ט (מאמרי אדהאמ\"צ דברים ח\"ב ע' תשא)."],["2716","67","ביאוה\"ז להצ\"צ שם ע' עח. אוה\"ת שם קיא, א."],["2717","68","ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670376\" data-slug=\"torat-chaim\" data-id=\"2300670376\">תו\"ח שם סכ\"ד (קכז, א</a>) \"וזה ענין שני חיי שרה . . שלא נזכר בזה מספר כלל . . דלפני א' מה אתה סופר\". ולהעיר, דלשון זה (לפני אחד מה אתה סופר) הובא בביאוה\"ז ובאוה\"ת שם לענין \"מאה שנה\" לשון יחיד. ויש לומר, דענין \"לפני אחד מה אתה סופר\" הוא עתיק (יחיד) כמו שנמשך ומאיר באריך (\"מאה\"), משא\"כ \"לפני אחד מה אתה סופר\" ד\"שני חיי שרה\" (שלמעלה מגדר מספר) הוא בחי' עתיק כמו שהוא במקומו."],["2718","69","פרש\"י עה\"פ (ריש פרשתנו). משא\"כ \"בת ק' <i>כ</i>בת כ', ובת כ' <i>כ</i>בת ז'\" הוא רק בכ\"ף הדמיון (ולא \"שווין\"), ו\"כל אחד נדרש <i>לעצמו</i>\"."],["2719","70","ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670365\" data-slug=\"torat-chaim\" data-id=\"2300670365\">תו\"ח שם (קכו, ד</a> ואילך) ד\"שני חיי שרה\" הו\"ע הבירורים, ואעפ\"כ (ואדרבא מצד זה) שייך זה לענין שני חיי שרה שלמעלה ממספר \"משום דסוף מעשה דבירורים . . עלה במחשבה תחלה\"."],["2720","71","ראה ד\"ה ויספו ענוים בה' שמחה לאדה\"ז ס\"ד (סה\"מ תקס\"ב ח\"א ע' נג). ד\"ה הנ\"ל לאדהאמ\"צ (מאמרי אדהאמ\"צ נ\"ך ע' לו ואילך). ד\"ה הנ\"ל תרצ\"ז (תש\"י) בתחלתו (סה\"מ ה'תש\"י ע' 238). ובארוכה – ד\"ה שמח תשמח תרנ\"ז ס\"ע 49 ואילך (סה\"מ תרנ\"ז ע' רכג ואילך)."],["2721","72","סידור (עם דא\"ח) שער התקיעות רמז, א-ב. מאמרי אדהאמ\"צ דברים ח\"ג ע' א'כח ואילך. ועוד."],["2722","73","ראה ד\"ה ויהיו חיי שרה עטר\"ת הנ\"ל (ע' צא). ד\"ה ויספו ענוים בהוי' שמחה לאדאהמ\"צ (מאמרי אדהאמ\"צ נ\"ך ע' כט). סה\"מ ה'תש\"י ע' 236. ד\"ה עבדו את ה' בשמחה תרצ\"ט (ע' 101).דירושה \"הוא ענין עצמי אצל הבן\" ומתיישבת אצלו (ד\"ה ויהיו חיי שרה עטר\"ת שם. סה\"מ ה'תש\"י שם. וראה גם ד\"ה ויספו ענוים בה' שמחה לאדה\"ז (סה\"מ תקס\"ב ח\"א ע' נא) ולאדאהמ\"צ שם)."],["2723","74","תפלת \"אלקי נצור\" בסיום העמידה (מברכות יז, א). וראה ד\"ה ויספו ענוים לאדהאמ\"צ (מאמרי אדהאמ\"צ שם ע' לא)."],["2724","75","ראה גם ד\"ה ויהיו חיי שרה עטר\"ת הנ\"ל בסופו (ד\"ה \"נ\"ל תוכן הענין\" – ע' צח): דכל בנ\"י . . יש בהם ביטול העצמי . . אין מזה יניקה."],["2725","76","ראה שיחת ש\"פ וירא, כ\"ף מרחשון ה'תש\"מ סכ\"ד ואילך (<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201413\" data-slug=\"likkutei-sichot\" data-id=\"1300201413\">לקו\"ש ח\"כ ס\"ע 400</a> ואילך)."],["2726","77","ח\"א לז, סע\"ב."],["2727","78","בראשית ו, ג."],["2728","79","וראה גם חולין קלט, ב ובפרש\"י שם."],["2729","80","סוטה יג, סע\"ב."],["2730","81","לקראת יום ההילולא הראשון של אביו כ\"ק אדמו\"ר (מהורש\"ב) נ\"ע – נדפס באגרות-קודש שלו ח\"א ע' קלח ואילך. וש\"נ. – ראה שם ע' קמא. וראה גם שם ע' קלא. ועוד."],["2731","82","וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061293\" data-slug=\"likkutei-sichot\" data-id=\"1300061293\">לקו\"ש ח\"ו ע' 283</a> ואילך."],["2732","83","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380975\" data-slug=\"likkutei-torah\" data-id=\"4001380975\">לקו\"ת</a> דרושים לר\"ה סד, א."],["2733","84","פרש\"י עה\"פ."],["2734","85","רמב\"ם הל' מלכים פי\"א ה\"א וה\"ד. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300111106\" data-slug=\"likkutei-sichot\" data-id=\"1300111106\">לקו\"ש (חי\"א ע' 98</a> <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300131061\" data-slug=\"likkutei-sichot\" data-id=\"1300131061\">הע' 61</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271219\" data-slug=\"likkutei-sichot\" data-id=\"1300271219\">חי\"ג ע' 84</a> הע' 36. <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300271001\" data-slug=\"likkutei-sichot\" data-id=\"1300271001\">לקו\"ש חכ\"ז ע' 205</a> סי\"ח ובהערות שם. \"חידושים וביאורים בהלכות בית הבחירה\" (קה\"ת, תשמ\"ו) סי\"ט. וש\"נ) התיווך עם דרשת חז\"ל (פרש\"י ותוס' סוכה מא, סע\"א. ועוד) שהבנין דלעתיד יתגלה ויבוא מן השמים."],["2735","86","רמב\"ם שם ה\"ד."],["2736","87","סוף הל' לולב."],["2737","88","שמואל-ב ו, טז. וראה גם ד\"ה ויהיו חיי שרה עטר\"ת הנ\"ל (ע' צו). סד\"ה ויספו ענוים בהוי' שמחה תרצ\"ז (תש\"י) (סה\"מ ה'תש\"י ע' 241)."],["2738","89","כ\"ה ברמב\"ם שם. ובכתוב שם: ותרא את המלך דוד מפזז ומכרכר לפני ה'. ושם לפנ\"ז (פסוק יד): ודוד מכרכר בכל עוז לפני ה'."],["2739","90","סהמ\"צ להצ\"צ מצות מינוי מלך פ\"א (דרמ\"צ קח, א). וראה גם מאמרי אדהאמ\"צ דברים ח\"א ע' רטו, ובהנסמן שם בהערה ד\"ה בדוד . . מרכבה לבחי' מל' שמים."],["2740","91","תהלים קלא, ב."],["2741","92","ר\"ה כה, א. נוסח קידוש לבנה. וראה גם מאמרי אדהאמ\"צ שם ע' ריד."],["2742","93","רמב\"ם שם."],["2743","94","דנוסף לזה שהמעשים שעושים לשם שמים הם (גם מצד עצמם) בכלל עבודת ה' (ראה רמב\"ם הל' דעות ספ\"ג: המהלך בדרך זו . . עובד את ה' תמיד . . שינה שלו עבודה למקום ברוך הוא. וכ\"ה גם בטושו\"ע או\"ח סרל\"א), ובמילא חל בזה הציווי (תהלים ק, ב) \"עבדו את ה' בשמחה\" – מתוסף בזה גם קיום <i>הציווי</i> (דוכל מעשיך יהיו לש\"ש ובכל דרכיך דעהו), ולכן הוא בכלל \"השמחה שישמח אדם <i>בעשיית המצוה</i>\" (רמב\"ם סוף הל' לולב)."],["2744","95","אבות פ\"ב מי\"ב. רמב\"ם וטושו\"ע שם. וראה <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300241661\" data-slug=\"likkutei-sichot\" data-id=\"1300241661\">לקו\"ש חכ\"ד ע' 646</a> בהערה ד\"ה כל מעשיך לשם שמים."],["2745","96","משלי ג, ו. רמב\"ם וטושו\"ע שם. שו\"ע אדה\"ז או\"ח סקנ\"ו ס\"ב."],["2746","97","ראה שמו\"ר פ\"ב, ד. זח\"א רנג, א. שער הפסוקים להאריז\"ל פ' ויחי. תו\"א ר\"פ משפטים."],["2747","98","ישעי' כו, יט. ואמרז\"ל שצדיקים ראשונים בתחה\"מ (זח\"א קמ, א) וביומא (ה, ב. וראה תוד\"ה אחד – פסחים קיד, ב) דמשה (ואהרן) עמהם בבנין ביהמ\"ק הג'."],["2748","99","ישעי' לה, י. נא, יא."]]],[1500360041,"<h3>בס\"ד. אור ליום ה' פ' חיי שרה, כ\"ף מרחשון ה'תשמ\"ה<sup data-n=\"2749\">*</sup></h3>\n<b>ויהיו</b> חיי שרה מאה שנה ועשרים שנה ושבע שנים שני חיי שרה<sup data-n=\"2750\">1</sup>, ומדייק אדמו\"ר (מהורש\"ב) נ\"ע בעל יום ההולדת במאמרו ד\"ה זה דשנת עטר\"ת<sup data-n=\"2751\">2</sup>, הרי כבר נאמר ויהיו חיי שרה [ומפרט שנותי' במאות עשיריות ואחדות], ומה מוסיף שני חיי שרה. ומבאר זה ע\"פ מה דאיתא בזהר<sup data-n=\"2752\">3</sup> דהטעם על זה שבשרה דוקא נאמר ימי שני חיי' שלא נאמר בשאר אמהות<sup data-n=\"2753\">4</sup>, הוא, כי שרה נחתת (למצרים) וסלקת כד\"א<sup data-n=\"2754\">5</sup> ויעל אברם ממצרים הוא ואשתו, ובגין כך זכתה לחיין עילאין. ומסיים (בזהר שם) ועל דא דילה הוו חיין. ועפ\"ז מבאר בהמאמר<sup data-n=\"2755\">6</sup> מה שכפל עוד פעם לומר שני חיי שרה, כי ויהיו חיי שרה הוא שזכתה לחיין עילאין, ושני חיי שרה הוא שהחיין נעשו <i>שלה</i>, דילה הוו [וכמבואר בהמאמר<sup data-n=\"2756\">7</sup> החילוק דשני הענינים]. וצריך להבין הקשר והשייכות דפירוש המאמר ששני חיי שרה הוא שהחיין נעשו שלה, עם פירוש רש\"י<sup data-n=\"2757\">8</sup> עה\"פ ששני חיי שרה הוא שכולן שוין לטובה.\nב) <b>ויובן</b> זה בהקדים דכל הסיפורים שבתורה (מלשון הוראה<sup data-n=\"2758\">9</sup>) הם הוראות לכאו\"א מישראל. ובפרט מעשה אבות [ואמהות] שהם סימן ונתינת כח לבנים<sup data-n=\"2759\">10</sup>. דכיון שהם האבות [והאמהות] של כל אחד מישראל, לכן הענינים והעבודות שלהם נמשכים בירושה לכל אחד מישראל<sup data-n=\"2760\">11</sup>. ועפ\"ז, זה שהתורה מספרת שכל שני חיי שרההם שוין לטובה הוא הוראה ונתינת כח לכל אחד מישראל שכל שנותיו יהיו שוים לטובה. וצריך ביאור, דהוראה לאדם שייכת (לכאורה) בנוגע לההוה והעתיד ולא בנוגע להעבר, וכיון שידע אינש בנפשי' מעמדו ומצבו בעבר, ומאי עביד באורתא<sup data-n=\"2761\">12</sup> ובהימים שלפנ\"ז [ואפילו הענינים שעשה בשוגג, הם מהתגברות נפש הבהמית<sup data-n=\"2762\">13</sup>], איך שייך לומר לו הוראה שכל שנותיו (גם שנותיו שבעבר) יהיו שוין לטובה.\n<b>ויש</b> לומר הביאור בזה, דע\"י תשובה מאהבה משנים גם את העבר<sup data-n=\"2763\">14</sup>, ולכן בכחו של כל אחד (גם מי שחטא ופגם והעביר את הדרך) שכל שנותיו (גם שנותיו שבעבר) יהיו שוין לטובה. ועפ\"ז יש לבאר הקשר והשייכות דשני הפירושים בשני חיי שרה, דילה הוו חיין וכולן שוין לטובה, כי כל הענינים שבגשמיות משתלשלים מענינם ברוחניות<sup data-n=\"2764\">15</sup>, וע\"י ענין דילה הוו חיין בנוגע לחיין עילאין, עי\"ז נעשה דילה הוו חיין גם בנוגע לחיים בפשטות, שהחיים הן שלה והיא נעשית בעה\"ב עליהם, ועי\"ז ניתן הכח לכל אחד מישראל<sup data-n=\"2765\">16</sup> שכל שני חייו (גם השנים שעברו) יהיו שלו ושהוא יהי' בעה\"ב עליהם, ולכן בכחו שיהיו כל שנותיו (גם השנים שבעבר) שוין לטובה.\nג) <b>ועפ\"ז</b> יובן מה שכתוב בתניא<sup data-n=\"2766\">17</sup> שכל אחד יכול להיות בינוני בכל עת ובכל שעה, דלכאורה, כיון שבינוני הוא זה שלא עבר עבירה מימיו ולא נקרא עליו שם רשע אפילו שעה אחת ורגע אחד כל ימיו<sup data-n=\"2767\">18</sup>, איך כל אדם (כולל גם זה שעבר עבירה) יכול להיות בינוני<sup data-n=\"2768\">19</sup>. ויש לומר הביאור בזה, דכמו שבנוגע לכל המצוות רשות לכל אדם נתונה ואין מי שיעכב בידו<sup data-n=\"2769\">20</sup>, כמו\"כ הוא בנוגע למצות התשובה, שלכל אחד מישראל יש לו בחירה חפשית לקיים מצות התשובה<sup data-n=\"2770\">21</sup>. ויש לומר, דהבחירה בנוגע למצות התשובה היא עוד יותר מבשאר המצוות. לפי שתשובה היא מצוה כללית, ולכן יש על זה נתינת כח מיוחדת. וגם, דכיון שכל אחד מישראל רוצה לעשות כל המצוות ולהתרחק מן העבירות אלא שיצרו הוא שתקפו<sup data-n=\"2771\">22</sup>, הרי כשעשה עבירה היפך רצונו דהאדם האמיתי, בפנימיותו הוא מתחרט ומיצר ודואגעל זה. היינו, שבפנימיותו הוא עושה תשובה<sup data-n=\"2772\">23</sup> מיד. ולכן זה שאין מי שיעכב בידו לקיים מצות התשובה הוא (בפרט אחד) יותר מבשאר המצוות, כי בכדי לקיים מצוה זו אינו צריך לעשי' ופעולה חדשה ורק לגלות התשובה שבפנימיותו. וזהו שכל אדם יכול להיות בינוני בכל עת ובכל שעה, דכיון שיש לו בחירה חפשית לקיים מצות התשובה, דעיקר ושלימות התשובה הוא תשובה מאהבה, שעי\"ז נעקר עונו <i>מתחלתו</i><sup data-n=\"2773\">24</sup>, הרי ביכלתו להיות בינוני שלא עבר עבירה מימיו<sup data-n=\"2774\">25</sup>.\nד) <b>ויש</b> להוסיף בביאור הקשר והשייכות דשני הפירושים בשני חיי שרה, דילה הוו וכולן שוין, שבכל אחד מהם כלולים שני הענינים. דגם בהפירוש ששני חיי שרה הוא כולן שוין לטובה, כלול הענין דדילה הוו חיין [כנ\"ל סעיף ב, שבכדי שיהי' כולן שוין לטובה גם השנים שבעבר, הוא ע\"י ששני חייו הם שלו], ועד\"ז לאידך, שגם בהפירוש ששני חיי שרה הוא דילה הוו חיין, כלול הענין דכולן שוין.\n<b>והענין</b> הוא, דמבואר בהמאמר<sup data-n=\"2775\">26</sup>, דשרה היא בחינת מלכות<sup data-n=\"2776\">27</sup> [שלכן נקראת שרה מלשון שררה<sup data-n=\"2777\">28</sup>] וחיין עילאין הם הספירות שלמעלה ממלכות. וע\"פ הידוע<sup data-n=\"2778\">29</sup> (ומבואר גם במאמר הנ\"ל<sup data-n=\"2779\">30</sup>) ששרש המלכות הוא למעלה משרש כל הספירות, דשרש כל הספירות הוא באריך ושרש המלכות הוא ברדל\"א, יש לומר, שע\"י המשכת הספירות במלכות, ובאופן שהם מתאחדים עם המלכות ועד <i>שדילה</i> הוו חיין, נעשה עלי' בהספירות, שנמשך בהם מעין הגילוי דרדל\"א (שרש המלכות)<sup data-n=\"2780\">31</sup>. ועי\"ז, הם מתכללים ומתאחדים כולם כאחד, כולן שוין. וזהו שבויהיו חיי שרה נאמר מאה שנה ועשרים שנה ושבע שנים, ובשני חיי שרה אינו מפרט המספרים דמאה עשרים ושבע, כי החיין עילאין (ספירות) כמו שהם מצד עצמם, כולל גם כמו שנמשכים במלכות אבל באופן שהחיין עילאין והמלכות הם שני ענינים (<i>זכתה</i> לחיין עילאין), הם בהתחלקות, ובכללות נחלקים לג' בחינות (מאה, עשרים ושבע)<sup data-n=\"2781\">32</sup>, וע\"י שנעשים ענינם של המלכות [שני חיי <i>שרה</i>, <i>דילה</i> הוו], מאיר בהם הגילוי דשרש המלכות שלמעלה מהתחלקות.\nה) <b>ויש</b> להוסיף, דשלילת ההתחלקות שבשני חיי שרה הוא בשני ענינים. שאינם נחלקים לג' חלוקות דמאה עשרים ושבע, כנ\"ל סעיף ד. ויתירה מזו, דבג'החלוקות דמאה ועשרים ושבע, אף שכל אחד מהם הו\"ע כללי, מ\"מ, כיון שהכלל הוא במספר מסויים (מאה, עשרים, שבע) הרי יש בו (בהעלם עכ\"פ) פרטים מחולקים. והטעם שבשני חיי שרה לא נאמר מספר (גם לא המספר מאה ועשרים ושבע, שאינו נחלק לג' חלוקות) הוא, לפי שהם למעלה גם מענין דהתחלקות פרטים כמו שהם כלולים בהכלל.\n<b>וביאור</b> הענין בפרטיות יותר, יובן בהקדים המבואר בכ\"מ<sup data-n=\"2782\">33</sup>, דמאה שנה הוא כתר (אריך) שכולל את כל העשר ספירות כמו שהם בשלימות היותר משובחת<sup data-n=\"2783\">34</sup>, שכל אחד מהם כלול מעשר, מאה. ובהטעם שנאמר (מאה) שנה לשון יחיד, שני ביאורים. כי ההתחלקות דהספירות (חכמה, בינה וכו') הוא בספירות הגלויות משא\"כ בהיותם כלולים בשרשם (אריך) הם כלולים כולם כאחד<sup data-n=\"2784\">35</sup>. ויתירה מזו, דבחינת עתיק אינה בגדר עשר ספירות (היינו שאינה גם מקור לעשר ספירות), וע\"י הגילוי דעתיק שמאיר באריך, גם הספירות הכלולות באריך, מאה, הם בבחינת שנה לשון יחיד<sup data-n=\"2785\">36</sup>. עשרים שנה הם חכמה ובינה שכל אחד מהם כלול מיו\"ד. וגם בהם נאמר שנה לשון יחיד, כי חו\"ב הם<sup data-n=\"2786\">37</sup> תרין ריעין דלא מתפרשין. ושבע שנים הם שבעת המדות. ונאמר שבע שנים לשון רבים, כי המדות הם בהתחלקות. ועפ\"ז יובן עוד יותר העילוי דשני חיי שרה שלא נאמר בהם מספר, שהם למעלה יותר גם ממאה שנה לשון יחיד, גם להביאור דמאה שנה לשון יחיד הוא מצד הגילוי דעתיק<sup data-n=\"2787\">38</sup>.\nו) <b>ויש</b> לבאר זה ע\"פ מ\"ש בהמאמר<sup data-n=\"2788\">39</sup>, דבמלכות ישנם שני ענינים הפכיים. דענין המלוכה הוא הגבהה והתנשאות (בחינת יש), ואעפ\"כ המלכות היא בתכלית הביטול. ומבאר, שהביטול דהמלכות הוא מצד שרשה ברדל\"א, שלכן הביטול שלה הוא ביטול בעצם, ובביטול בעצם, גם היש הוא בביטול. והענין בעבודה הוא (כמבואר בהמאמר<sup data-n=\"2789\">40</sup>) דעבודת ה' צריכה להיות בשמחה דוקא כמ\"ש<sup data-n=\"2790\">41</sup> עבדו את ה' בשמחה. ועד שהשמחה בעבודת ה' היא עיקר גדול, וכידוע פירוש האריז\"ל<sup data-n=\"2791\">42</sup> והובא בתניא<sup data-n=\"2792\">43</sup> עה\"פ<sup data-n=\"2793\">44</sup> תחת אשר לא עבדת את ה' אלקיך בשמחה וגו', ואיתא בתו\"א<sup data-n=\"2794\">45</sup> דזהשהאריז\"ל זכה לרוה\"ק הוא ע\"י שמחה של מצוה [וכיון שזהו סיפור בתורה (שבעל פה) מלשון הוראה, הרי זה הוראה לכאו\"א מישראל]. אלא שאעפ\"כ יש זמנים<sup data-n=\"2795\">46</sup> שהשמחה צריכה להיות בהעלם, כמ\"ש<sup data-n=\"2796\">47</sup> עבדו את ה' ביראה וגילו ברעדה, דבגילוי הוא היראה והרעדה, והשמחה (גילה) היא בהעלם<sup data-n=\"2797\">48</sup>. כי כאשר השמחה היא בהתגלות ובמורגש, אפשר שמזה יבוא להרגשת הישות, ועי\"ז אפשר שדברים בלתי רצויים יבואו עי\"ז, ולכן צ\"ל עבדו את ה' ביראה וגילו ברעדה. ובכדי שהשמחה תהי' בהתגלות ואעפ\"כ לא יבוא מזה להרגשת הישות, הוא ע\"י שהוא בטל בעצם, שאז, גם המורגש שלו הוא בביטול. וע\"ד המבואר לעיל בענין הביטול דמלכות, שגם היש (הגבהה והתנשאות) הוא בביטול.\n<b>וזהו</b><sup data-n=\"2798\">49</sup> ההוספה והחידוש דדילה הוו חיין על זה שזכתה לחיין עילאין, כי זה ששרה נחתת וסלקת (שעי\"ז זכתה לחיין עילאין) הוא ע\"י היראה וביטול (ולא ע\"י השמחה)<sup data-n=\"2799\">50</sup>, ולכן המשכת החיין עילאין [שע\"י נחתת וסלקת] בהמלכות הוא בהמלכות כמו שהיא בבחינת עלי' וביטול לז\"א [ובעבודת האדם הוא שהגילוי שמאיר לו ע\"י עבודתו הוא כמו שהוא במצב דיראה וביטול, ולא בהמציאות שלו]. וענין דילה הוו חיין הוא שההמשכה והגילוי הוא גם בהמציאות דמלכות, כי כיון שהביטול דמלכות הוא ביטול בעצם, לכן גם המורגש דמלכות הוא בביטול, כנ\"ל.\n<b>ועפ\"ז</b> יש לבאר מעלת האחדות שלמעלה מהתחלקות דשני חיי שרה שלא נאמר בהם מספר על האחדות דמאה שנה לשון יחיד, דענין האחדות (שנה לשון יחיד) בהספירות שבכתר (מאה), הוא, ע\"י שבהיותם כלולים בשרשם <i>אינם</i> במציאות. והחידוש שבשני חיי שרה הוא, דהגם שבמלכות הוא התחלקות פרטים [וכידוע<sup data-n=\"2800\">51</sup> שעיקר ההתחלקות הוא במלכות], שלכן, גם החיין עילאין הנמשכים במלכות באופן שהם <i>דילה</i> הם בהתחלקות, <i>שני</i> חיי שרה (שני לשון רבים), מ\"מ הם בהתכללות ובהתאחדות כמו דבר אחד ממש (שלכן לא נאמר בהם מספר). ועי\"ז מתגלה אמיתית ענין האחדות<sup data-n=\"2801\">52</sup>, שגם הריבוי (פרטים מחולקים) אינו סותר לאחדות.\nז) <b>והנה</b> נתבאר לעיל (סעיף ב) הקשר והשייכות דשני הפירושים בשני חיי שרה (דילה הוו חיין וכולן שוין לטובה), דע\"י שהחיין הן דילי', שהוא הבעה\"ב על כל שני חייו, ביכלתו לפעול שכולן (כל שנותיו, גם השנים שבעבר) יהיו שוין לטובה. וצריך להבין השייכות דענין זה בדילה הוו חיין (שהוא הבעה\"ב על כל שני חייו) עם המבואר בהמאמר דענין דילה הוו חיין הוא שגם המורגש הוא בביטול. וישלומר הביאור בזה ע\"פ המבואר במק\"א<sup data-n=\"2802\">53</sup>, דזה שע\"י תשובה (מאהבה) נעשה שינוי בהעבר הוא, כי שרש הזמן הוא במלכות<sup data-n=\"2803\">54</sup>, ולמעלה יותר – הקדימה ואיחור שבסדר ההשתלשלות<sup data-n=\"2804\">55</sup>, וכיון שתשובה היא למעלה מהשתלשלות (שבאדם, שלכן הגילוי שנמשך ע\"י התשובה הוא גילוי שלמעלה מהשתלשלות)<sup data-n=\"2805\">56</sup>, לכן אין בה ההגבלות דעבר הוה ועתיד.\n<b>והגם</b> שגם עשיית התשובה היא ברגע מסויים שמוגבל בהגדר דזמן, עבר הוה ועתיד, ומצד גדר הזמן אי אפשר שע\"י פעולה בהוה יהי' שינוי בהעבר (כי סיבה צריכה להיות <i>לפני</i> המסובב), מ\"מ, כיון שהתשובה עצמה היא למעלה מהגבלת הזמן, לכן, נמשך על ידה הבל\"ג דלמעלה מזמן גם בהזמן (בהרגע דעשיית תשובה), וכאילו שרגע זה הי' מקודם, לפני המסובב. ועפ\"ז יש לבאר השייכות דשני הענינים בדילה הוו חיין [שגם המורגש הוא בביטול, ושהוא בעה\"ב על כל שני חייו], דע\"י שהמורגש (מציאות, גבול) הוא בביטול (למעלה ממציאות והגבלה), עי\"ז, גם בהזמן (גבול) נמשך הבל\"ג דלמעלה מהזמן.\nח) <b>והגם</b> שענין זה (שהמורגש הוא בביטול) הוא מדריגה נעלית, מ\"מ, כיון שמעשה אבות ואמהות הוא סימן ונתינת כח לבנים, הענין דדילה הוו חיין שהי' אצל שרה הוא הוראה ונתינת כח לכל אחד מישראל שיוכל לעבוד את ה' בשמחה בהתגלות ובמורגש ושאעפ\"כ לא יבוא מזה להרגשת הישות<sup data-n=\"2806\">57</sup>, כי גם המורגש שלו הוא בביטול (כנ\"ל סעיף ו). וע\"י השמחה בעבודת ה' בכלל, ובפרט כשהשמחה היא בעבודת התשובה עצמה [וכמבואר במק\"א<sup data-n=\"2807\">58</sup> דשמחה של מצוה היא גם במצות התשובה, ואדרבה, השמחה דמצות התשובה היא גדולה יותר מהשמחה דכל המצוות], עי\"ז מיתוסף עוד יותר בכח התשובה לשנות גם את העבר.\n<b>ולהוסיף</b><b>,</b> דע\"פ הידוע<sup data-n=\"2808\">59</sup> בביאור לשון חז\"ל<sup data-n=\"2809\">60</sup> תשובה ומעשים טובים, שעל ידי התשובה המעשים (דהמצוות) הם טובים ומאירים, יש לומר, דעל ידי שהתשובה היא בשמחה שאז התשובה היא בשלימות, עי\"ז מיתוסף בהשמחה ובהשלימות דלימוד התורה וקיום המצוות שלאחרי התשובה.\n<b>וענין</b> זה [פעולת התשובה בהתומ\"צ (עבודת הצדיקים) שלאחרי התשובה] הוא הכנה קרובה לגאולה האמיתית והשלימה ע\"י משיח צדקנו, שאתא לאתבאצדיקייא בתיובתא<sup data-n=\"2810\">61</sup>. ועד\"ז הוא בנוגע לגאולה העתידה שיהיו בה שני הענינים, כמ\"ש<sup data-n=\"2811\">62</sup> בשובה ונחת תושעון, בשובה הו\"ע עבודת התשובה<sup data-n=\"2812\">63</sup>, ובנחת הו\"ע עבודת הצדיקים<sup data-n=\"2813\">64</sup>. ובפשטות, שכל ישראל, בנערינו ובזקנינו גו' בבנינו ובבנותינו<sup data-n=\"2814\">65</sup> [שלימות העם], <i>ישובו</i> לארצנו הקדושה, וכמו שהיא ארץ טובה ורחבה [שלימות הארץ], ביחד עם התורה ומצוות (עבודת הצדיקים). וע\"י שהתומ\"צ הם ע\"י קדימת התשובה, גם התומ\"צ הם בשלימות [שלימות התורה ומצוותי']. וכל זה – כלשון הידוע בנוגע לתשובה – בשעתא חדא וברגעא חדא<sup data-n=\"2815\">66</sup>.\n**********",[["2749","*","יצא לאור ב<b>קונטרס כ\"ף מרחשון – תנש\"א</b>, \"לקראת כ\"ף מרחשון הבעל\"ט, יום הולדת הק\"ל* דכ\"ק אדמו\"ר (מהורש\"ב) נ\"ע (כתר\"א–תנש\"א) . . <i>מוצש\"ק ט\"ו חשון</i>,<i> שנת ה'תנש\"א</i>\"."],["2750","1","ריש פרשתנו."],["2751","2","נדפס בסה\"מ עטר\"ת ע' פז ואילך. וראה ד\"ה זה ה'תשמ\"א (לעיל ע' רעז ואילך)."],["2752","3","ח\"א פרשתנו קכב, ב."],["2753","4","כ\"ה הלשון ברד\"ה הנ\"ל עטר\"ת. ולהעיר, שבזהר שם (קכא, סע\"ב) \"מכל נשי <i>דעלמא</i>\" [וגם בהדוגמאות שבזהר שם, רובן אינן מהאמהות]."],["2754","5","לך לך יג, א."],["2755","6","בסופו (סה\"מ עטר\"ת ע' צז)."],["2756","7","וראה לקמן ס\"ו."],["2757","8","דנוסף לזה שכל הפירושים שבאותו הפסוק שייכים זה לזה** – כיון שפירוש רש\"י על התורה הוא \"<i>יינה</i> של תורה\" (\"היום יום\" כט שבט), יש לו שייכות מיוחדת עם הפירוש ע\"ד הסוד (זהר). וראה בארוכה לקו\"ש ח\"ה בתחלתו, ובהערות שם."],["2758","9","ראה רד\"ק לתהלים יט, ח (ובס' השרשים שלו ערך ירה). גו\"א ר\"פ בראשית. וראה זח\"ג נג, ב: אמאי אקרי תורה בגין דאורי."],["2759","10","ראה רמב\"ן עה\"פ לך לך יב, ו: כל מה שאירע לאבות סימן לבנים. ובב\"ר פ\"מ, ו (הובא ברמב\"ן עה\"פ שם, י): צא <i>וכבוש את הדרך</i> לפני בניך. ועוד."],["2760","11","ראה תו\"א ר\"פ וארא. ובכ\"מ. וראה בארוכה ד\"ה זה ה'תשמ\"א ס\"ב (לעיל ע' רעח), ובהערות שם.\n*) <i>ראה בארוכה בשיחת ש\"פ וירא ט\"ו מרחשון דשנה זו (ה'תנש\"א [תורת מנחם – התוועדויות תנש\"א ח\"א ע' 286 ואילך])</i>.\n**) <i>כידוע הראי' לזה מ</i>\"<i>שעטנז</i>\"<i> (נדה סא</i>,<i> ב) – ראה לקו\"ש ח\"ג ע' 782</i>.<i> ובכ\"מ</i>."],["2761","12","ע\"פ לשון חז\"ל סוף מס' ע\"ז."],["2762","13","אגה\"ק סו\"ס כח (מל\"ת להאריז\"ל פ' ויקרא בטעהמ\"צ)."],["2763","14","ראה יומא פו, סע\"א ובפרש\"י שם ד\"ה כאן מאהבה \"השב מאהבה נעקר עונו <i>מתחלתו</i>\"."],["2764","15","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310008\" data-slug=\"tanya\" data-id=\"3401310008\">תניא רפ\"ג</a>. ובכ\"מ."],["2765","16","להעיר מזהר שם (קכב, ב) \"שרה זכתה לחיין עילאין לה ולבעלה ולבנהא בתראה\"."],["2766","17","רפי\"ד."],["2767","18","<a class=\"ft-cite\" href=\"#/read/tanya/3401310017\" data-slug=\"tanya\" data-id=\"3401310017\">תניא רפי\"ב</a>."],["2768","19","לכאורה אפשר לומר דפירוש \"לא עבר עבירה מימיו\" הוא <i>שעכשיו</i> (לאחרי שעשה תשובה) הוא במצב ש\"לא עבר עבירה מימיו\" כי לא נשאר רושם כלל מהעבירה שעשה. אבל מפשטות הלשון בתניא שם, ובפרט מזה שמוסיף \"ולא נקרא עליו שם רשע <i>אפילו שעה אחת ורגע אחד כל ימיו</i>\", משמע, דהפירוש הוא כפשוטו."],["2769","20","לשון הרמב\"ם הל' תשובה רפ\"ה."],["2770","21","השייכות דענין הבחירה להלכות תשובה בפשטות היא כמ\"ש הרמב\"ם (שם ה\"ב. ועד\"ז ברפ\"ז) \"הואיל ורשותנו בידינו ומדעתנו עשינו כל הרעות, ראוי לנו לחזור בתשובה\". אבל פשיטא שאין מקום לומר <i>ששני פרקים</i> (פ\"ה ופ\"ו) <i>בהלכות תשובה</i> מדברים רק בנוגע לשאר מצוות ולא בנוגע לתשובה."],["2771","22","רמב\"ם הל' גירושין ספ\"ב."],["2772","23","היינו, שבפנימיותו הוא עושה תשובה <i>בפועל</i>. משא\"כ בשאר המצוות שהוא רק <i>רוצה</i> לעשותם."],["2773","24","רש\"י שבהערה 14."],["2774","25","וכיון שתשובה היא בשעתא חדא וברגעא חדא (זח\"א פרשתנו קכט, סע\"א ואילך) לכן כל אדם יכול להיות בינוני <i>בכל עת ובכל שעה</i>."],["2775","26","ראה סה\"מ עטר\"ת ע' צג. שם ע' צז."],["2776","27","קה\"י ערך שרה (פיסקא הב')."],["2777","28","פרש\"י עה\"פ נח יא, כט. וראה גם ברכות יג, א. פרש\"י עה\"פ לך לך יז, טו."],["2778","29","ע\"ח שער יג (שער אריך אנפין) פ\"ב – הובא ונתבאר בכ\"מ. וראה בארוכה לעיל ע' לו ואילך. ועוד."],["2779","30","סה\"מ שם ס\"ע צו."],["2780","31","וע\"ד אורות וכלים, שע\"י התלבשות האורות בכלים מאיר בהם מבחי' שרש הכלים שלמעלה משרש האורות (סה\"מ תרמ\"ט ס\"ע רמג ואילך. ובכ\"מ)."],["2781","32","ראה לקמן ס\"ה."],["2782","33","ביאוה\"ז לאדהאמ\"צ בהוספות קלא, סע\"ב. תו\"ח פרשתנו קכו, ב ואילך. ביאוה\"ז להצ\"צ פרשתנו ע' עח ואילך. אוה\"ת פרשתנו קי, ב ואילך."],["2783","34","כ\"ה הלשון בביאוה\"ז להצ\"צ שם (ע' עח) ובאוה\"ת שם (קי, ב)."],["2784","35","כן משמע בהוספות לביאוה\"ז שם קלא, סע\"ב."],["2785","36","ביאוה\"ז להצ\"צ שם ע' עח. אוה\"ת שם קיא, א. וראה גם סה\"מ עטר\"ת ע' צז."],["2786","37","זהר ח\"א פרשתנו קכג, א (ובכ\"מ). ושם \"ובגין כך כתיב שנה\" (לשון יחיד)."],["2787","38","ראה ד\"ה זה שבהערה 2 הערה 68 (לעיל ע' רפג), דענין מאה שנה לשון יחיד הוא עתיק (יחיד) כמו שנמשך ומאיר באריך (\"מאה\"), ו\"שני חיי שרה\" שלמעלה מגדר מספר הוא עתיק כמו שהוא במקומו."],["2788","39","סה\"מ עטר\"ת ע' צו ואילך."],["2789","40","שם ע' פז. ס\"ע צ ואילך. וראה בד\"ה זה שבהערה 2 ס\"ג (לעיל ע' רעט). וש\"נ."],["2790","41","תהלים ק, ב."],["2791","42","נסמן לעיל שם הערה 23."],["2792","43","פרק כו."],["2793","44","תבוא כח, מז."],["2794","45","תולדות כ, ב. וראה בהנסמן לעיל שם הערה 27-26."],["2795","46","כ\"ה בסה\"מ עטר\"ת שם ע' פז."],["2796","47","תהלים ב, יא. וראה בהנסמן לעיל ע' רפ הערה 34."],["2797","48","ראה גם <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380907\" data-slug=\"likkutei-torah\" data-id=\"4001380907\">לקו\"ת נצבים מז, רע\"א</a>. ושם, שזהו \"ההפרש שבין שמחה לגילה\"."],["2798","49","בהבא לקמן, ראה סה\"מ עטר\"ת שם ע' צז."],["2799","50","כ\"ה להדיא בסה\"מ שם ע' צח."],["2800","51","המשך תער\"ב פכ\"ד. ובכ\"מ."],["2801","52","להעיר מסה\"מ תרנ\"ט ע' נט \"יש בזה יתרון מעלה מה שריבוי פרטים מתאחדים ונעשים דבר אחד\"."],["2802","53","ראה עד\"ז <a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300061054\" data-slug=\"likkutei-sichot\" data-id=\"1300061054\">לקו\"ש ח\"ו ע' 54</a>."],["2803","54","שעהיוה\"א פ\"ז (פב, א)."],["2804","55","ראה בארוכה סה\"מ תרנ\"ד ע' רפה ואילך. המשך תער\"ב ח\"ב ע' תתקכא."],["2805","56","ראה לקו\"ת דרושים לשבת שובה ד\"ה שובה הא' ס\"ד (סה, א). וראה בארוכה ד\"ה שובה ישראל ה'תשל\"ו (לעיל ע' פג ואילך)."],["2806","57","ראה גם ד\"ה זה עטר\"ת בסופו (ד\"ה \"נ\"ל תוכן הענין\" – סה\"מ עטר\"ת ע' צח): דכל בנ\"י . . יש בהם ביטול העצמי . . אין מזה יניקה."],["2807","58","אגה\"ת מהדו\"ק ע' תקכה."],["2808","59","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381199\" data-slug=\"likkutei-torah\" data-id=\"4001381199\">לקו\"ת</a> דרושים לשמע\"צ פה, א. שה\"ש יז, ג. וראה לקו\"ש ח\"ד ע' 1053 ואילך."],["2809","60","אבות פ\"ד מי\"ז."],["2810","61","הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381329\" data-slug=\"likkutei-torah\" data-id=\"4001381329\">לקו\"ת</a> דרושים לשמע\"צ צב, ב. שה\"ש נ, סע\"ב. ובהנסמן במאמרי אדהאמ\"צ דברים ח\"ג ע' א'קכט. וראה זח\"ג קנג, ב."],["2811","62","ישעי' ל, טו."],["2812","63","ראה המשך וככה תרל\"ז ר\"פ קלה \"איתא בספרים בשובה הוא תשובה\"."],["2813","64","ראה המשך הנ\"ל פקל\"ד."],["2814","65","כמ\"ש ביצי\"מ (בא י, ט), והרי \"כימי צאתך מארץ מצרים אראנו נפלאות\" בגאולה העתידה (מיכה ז, טו)."],["2815","66","זהר שבהערה 25."]]],[1500360042,"<h3>בס\"ד. ש\"פ חיי שרה, כ\"ב מרחשון ה'תנש\"א<sup data-n=\"2816\">*</sup></h3>\n<b>ויהיו</b> חיי שרה מאה שנה ועשרים שנה ושבע שנים שני חיי שרה<sup data-n=\"2817\">1</sup>, וידועים הדיוקים בדרושי רבותינו נשיאינו [החל מדרושי רבינו הזקן<sup data-n=\"2818\">2</sup>, ובתוספת הגהות וביאורים בדרושי רבותינו נשיאינו שלאח\"ז<sup data-n=\"2819\">3</sup>, וגם בדרושי אדמו\"ר (מהורש\"ב) נ\"ע<sup data-n=\"2820\">4</sup>, בעל יום ההולדת דכ\"ף מרחשון<sup data-n=\"2821\">5</sup>], שבמספר מאה ובמספר עשרים נקט שנה (מאה שנה ועשרים שנה) לשון יחיד, ובמספר שבע נקט שנים (שבע שנים) לשון רבים. גם, מהו אומרו שני חיי שרה, הרי כבר נאמר ויהיו חיי שרה (ומפרט המספר דקכ\"ז שנה), ולמה כופל שני חיי שרה. גם צריך להבין הלימוד וההוראה משני חיי שרה בעבודת כאו\"א מישראל, כידוע שכל עניני התורה (גם סיפורי התורה<sup data-n=\"2822\">6</sup>) הם הוראות לכאו\"א מישראל, ובפרט מעשה אבות (ואמהות) שהם סימן (ונתינת-כח) לבנים<sup data-n=\"2823\">7</sup>.\nב) <b>ומבואר</b> בהדרושים, שבפסוק זה נכלל כל סדר ההשתלשלות (למעלה וגם) בנפש האדם, בכאו\"א מישראל, שעבודתו צריכה להיות בכל פרטי הענינים דמאה שנה ועשרים שנה ושבע שנים, כמו בשרה<sup data-n=\"2824\">8</sup>. וביאור הענין, דאיתא בזהר<sup data-n=\"2825\">9</sup> ויהיו חיי שרה כו' מאה שנה כללא דכולא קוב\"ה דאתכליל מאתר עילאה סתימא דכל סתימין במאה ברזא דמאה ברכאן בכל יומא, וכן עשרים שנה, ובגין כך כתיב שנה רזא דיחודא דלא אתפרש מחשבה ויובלא לעלמין, שבע שנים אלין אתפרשן ונפקאן מכללא כו' בדינא ורחמי בכמה סטרין ואורחין כו' ובגין כך כו' כתיב בהו שנים ולא שנה, וכולהו אקרון חיים כו'. והענין בזה, שמאה שנה קאי על הכתר (כי כתר כולל כל היו\"ד ספירות, וכל א' מהם כלול מיו\"ד, ויו\"ד פעמים יו\"ד הם מאה), שענינו בנפש האדם הוא רצון (חיצוניות הכתר) ותענוג (פנימיות הכתר). ועשרים שנה קאי על חכמה ובינה (שכל א' מהם כלול מיו\"ד), בחי' המוחין [ובכמה דרושים<sup data-n=\"2826\">10</sup>מבואר שגם מאה שנה הוא בחי' המוחין (כידוע שיחידות במלכות, עשיריות בז\"א, ומאות באו\"א (חו\"ב), ואלפים בכתר), ועפ\"ז י\"ל, שמאה שנה הוא מוחין בעצם, ועשרים שנה הוא מוחין השייכים להמדות (עשיריות בז\"א)]. ובשניהם נאמר שנה (מאה שנה ועשרים שנה) לשון יחיד, כי, בכתר (מאה) כלולים כל הספירות יחד, וגם חכמה ובינה (עשרים) הם תרין ריעין דלא מתפרשין<sup data-n=\"2827\">11</sup>, ולכן נכללים יחד. ושבע שנים קאי על שבע המדות, ולהיותם באופן של התחלקות עד לקוין הפכיים דחסד וגבורה (דינא ורחמי), נאמר בהם שבע שנים, לשון רבים. ומוסיף ומסיים שני חיי שרה, שע\"י שלימות העבודה דמאה שנה ועשרים שנה ושבע שנים באים לדרגא נעלית יותר שלמעלה מהתחלקות, שלכן לא נזכר בזה מספר (ע\"ד לפני אחד מה אתה סופר<sup data-n=\"2828\">12</sup>).\nג) <b>וצריך</b> להבין, דלפירוש זה, שני חיי שרה הו\"ע בפ\"ע שלמעלה מג' החלוקות דמאה שנה ועשרים שנה ושבע שנים, ופשטות הכתוב ששני חיי שרה הם הקכ\"ז שנים עצמם, ולא ענין בפ\"ע שלמעלה מהם. וכמודגש בפירוש רש\"י<sup data-n=\"2829\">13</sup> שני חיי שרה כולן שוין לטובה, שהענין דשוין לטובה (למעלה מהתחלקות) הוא בכולן, היינו, בג' החלוקות דמאה שנה ועשרים שנה ושבע שנים (ולא בדרגא שלמעלה מהם). גם צריך להבין מ\"ש בפירוש רש\"י בת ק' כבת כ' ובת כ' כבת ז', שמזה משמע שיש עילוי בז' לגבי כ' (בת כ' כבת ז') ובכ' לגבי ק' (בת ק' כבת כ'), אע\"פ שכתר (ק') הוא למעלה מהמוחין (כ'), ומוחין הם למעלה ממדות (ז').\nד) <b>ויובן</b> בהקדם המבואר בכמה דרושים<sup data-n=\"2830\">14</sup> המשך דברי הזהר מאה שנה כללא דכולא, שמאה שנה הוא רזא דמאה ברכאן בכל יומא, שחייב אדם לברך מאה ברכות בכל יום, כפי שלמדו חז\"ל<sup data-n=\"2831\">15</sup> מהפסוק<sup data-n=\"2832\">16</sup> ועתה ישראל מה ה' אלקיך שואל מעמך, א\"ת מה אלא מאה<sup data-n=\"2833\">17</sup>. ונקודת הביאור, שמאה שנה הוא גם הכלל דעשרים שנה ושבע שנים, כללא דכולא. דנוסף לזה שכל מאה הדרגות (עשר ספירות שכל א' מהם כלולה מעשר) שבכתר הם כלל אחד שלמעלה מהתחלקות [למעלה גם מהכלל דעשרים שנה, שיש בו שתי דרגות (חכמה בינה) אלא שהם תרין ריעין דלא מתפרשין], הוא גם הכלל דכל ג' החלוקות, גם דעשרים שנה ושבע שנים. וכמבואר בהדרושים<sup data-n=\"2834\">18</sup> שמאה שנה (כללא דכולא) נמשך ומתלבש בהפרטים דעשרים שנה (מוחין) ושבעשנים (מדות). ויש לומר, שזה שמאה הוא (גם) הכלל דעשרים ושבע, הוא, לא רק להביאור שמאה הוא כתר, דכיון שכתר הוא מקיף ה\"ה הכלל דכל העשר ספירות, אלא גם להביאור שמאה הוא עצם המוחין, דאף שמוחין הם כחות פנימיים, יש לומר, שעצם המוחין הוא גם הכלל דהדרגות שלמטה ממנו, שלכן, עצם המוחין נמשך ומתלבש (אח\"כ) בהמוחין השייכים אל המדות, שנחלקים (בכללות) לב' קוין (עשרים שנה), חיוב ושלילה (עשה ולא תעשה)<sup data-n=\"2835\">19</sup>, ועד שנמשך בהמדות עצמם (שבע שנים) שבהם היא עיקר העבודה.\nה) <b>וביאור</b> הענין דמאה שנה כללא דכולא שהוא רזא דמאה ברכות שבכל יום, יובן ע\"פ המבואר בכמה דרושים<sup data-n=\"2836\">20</sup> שענין הברכות הוא כללות העבודה. דהנה, ברכה היא מלשון המשכה, והפירוש דברוך אתה הוי' הוא להמשיך שם הוי'<sup data-n=\"2837\">21</sup> שיהי' ברוך ונמשך בגילוי למטה. וסדר ההמשכה הוא, שתחלה נמשך שם הוי' בנפש האדם, הוי' אלקינו, להיות גילוי אוא\"ס בנפש כל ישראל שתתחזק אמונת ה' בלבם בגילוי עד שנעשה אלקה שלנו, כוחינו וחיותנו, ולאחרי שנמשך ונתגלה בישראל, נמשך על ידם הגילוי גם למטה להיות מלך העולם. ויש להוסיף, שההמשכה והגילוי למטה מודגשים גם בתוכן הברכות, כי, נוסף לכך ש(רוב ה)ברכות <i>קשורים</i> עם עניני העולם (שהרי אפילו ברכות המצוות קשורים עם עניני העולם שבהם מקיימים המצוות, ציצית בצמר גשמי ותפילין בקלף גשמי כו'), הרי הברכות עצמם הם <i>על עניני העולם</i>, וכמו ברכות השחר<sup data-n=\"2838\">22</sup> שתקנום חכמים על סדר העולם והנהגתו מה שהבריות נהנין בכל יום שיברכו להקב\"ה על זה בפעם ראשונה שנהנין הנאה זו בכל יום<sup data-n=\"2839\">23</sup>, ועד\"ז הברכות על בקשת צרכיו הגשמיים רופא חולים ומברך השנים וכיו\"ב, ועאכו\"כ ברכות הנהנין שמברכים לפני אכילה ושתי', שע\"י הברכה נעשה הדבר מותר באכילה ושתי', כמארז\"ל<sup data-n=\"2840\">24</sup> כל הנהנה מעוה\"ז בלא ברכה כאילו נהנה מקדשי שמים, שנאמר<sup data-n=\"2841\">25</sup> לה' הארץ ומלואה, לאחר ברכה הרי היא לבני אדם, היינו, שפעולת הברכה היא (לא לבטל ח\"ו העילוי דקדשי שמים שבדבר זה, אלא) שקדשי שמים נעשים שלו, שאכילתו ושתייתו היא בבחינת קדשי שמים, כיון שע\"י הברכה נעשה הבירור והזיכוך דהדברים הגשמיים להיות נמשך בהם הגילוי ד(הוי' אלקינו) מלך העולם. וזהו הפירוש בדברי הזהר מאה שנה כללא דכולא ברזא דמאה ברכאן בכל יומא<sup data-n=\"2842\">26</sup>, כי הענין דמאה ברכותהוא כללות כל העבודה להמשיך אלקות למטה, וזהו\"ע דמאה שנה כללא דכולא, כללות העבודה להמשיך אלקות למטה, ע\"י ההמשכה וההתלבשות בהמוחין השייכים אל המדות (עשרים שנה) ועד לבחינת המדות (שבע שנים), שבעת ימי הבנין, שעל ידם נברא העולם<sup data-n=\"2843\">27</sup>, ובהם (בבחינת המדות) היא עיקר העבודה בזמן הזה<sup data-n=\"2844\">28</sup>.\nו) <b>והנה</b><b>,</b> ע\"י ההמשכה וההתלבשות דמאה שנה כללא דכולא בהמוחין השייכים אל המדות (עשרים שנה) ובהמדות (שבע שנים) עד לעבודה במעשה בפועל כדי שיהי' גילוי אלקות בעולם, אזי נעשה (נוסף על בירור וזיכוך המטה) גם עילוי גדול יותר בבחי' מאה שנה כללא דכולא, כידוע<sup data-n=\"2845\">29</sup> שע\"י הירידה דהעליון להשפיע להתחתון מקבל גם העליון מעלת התחתון (שלכן כל סדר ההשתלשלות הוא באופן דנעוץ תחילתן בסופן<sup data-n=\"2846\">30</sup>, שהעליון צריך גם לקבל מהתחתון). ויתירה מזה, כיון שההמשכה למטה היא מפני שנתאווה הקב\"ה להיות לו ית' דירה בתחתונים<sup data-n=\"2847\">31</sup>, הרי, ע\"י ההמשכה למטה נשלמת כוונת העצמות שלמעלה מכל תואר וגדר, שלכן, מעלה ומטה, בלי גבול וגבול, שוין ממש. והחילוק דב' אופנים אלו בעבודה, שבאופן הא' יש חילוק בין עליון (עבודה בעניני קדושה) לתחתון (עבודה בעניני העולם), והעבודה למטה הו\"ע של ירידה, אלא שירידה זו היא צורך עלי'. ובאופן הב', כיון שכל ענינו אינו אלא למלא חפצו ורצונו של הקב\"ה שנתאוה להיות לו ית' דירה בתחתונים, הרי, מצד כוונת העצמות אין חילוק בין עליון (עבודה בעניני קדושה) לתחתון (עבודה בעניני העולם), ובמילא, העבודה למטה אינה ענין של ירידה, כיון שנרגש בה הנקודה הכללית (כללא דכולא) שבכל עניני העבודה בשוה ממש, כוונת העצמות. וזהו גם רזא דמאה ברכות בכל יום, כפי שלמדו חז\"ל ממש\"נ מה ה' אלקיך שואל מעמך, א\"ת מה אלא מאה, כמבואר בהדרושים<sup data-n=\"2848\">32</sup> שמאה הוא מה בתוספת אל\"ף, מה הו\"ע הביטול (ונחנו מה<sup data-n=\"2849\">33</sup>), וע\"י הביטול דמה ממשיכים האל\"ף, בחי' הכתר (מאה), שיומשך בגילוי למטה ע\"י הברכות. דכיון שעבודתו היא מצד הביטול והקבלת עול שבה מתגלה עצם הנשמה, הרי כל ענינו אינו אלא למלא רצונו וחפצו של הקב\"ה, שזוהי הנקודה הכללית דכל עניני העבודה, כוונת העצמות.\nז) <b>ועפ\"ז</b> יש לבאר מ\"ש ויהיו חיי שרה מאה שנה ועשרים שנה ושבע שנים שני חיי שרה, ששני חיי שרה (אינו ענין בפ\"ע שלמעלה מג' החלוקות דמאה שנה ועשרים שנה ושבע שנים, אלא) הם הקכ\"ז שנה עצמם, שכולן שוין לטובה. כי, בתחילת הכתוב מבואר העילוי שנעשה במאה שנה ע\"י ההמשכה למטה, שזהו\"עדבת ק' כבת כ' ובת כ' כבת ז', שבמאה נוסף גם העילוי דעשרים, ובעשרים נוסף גם העילוי דשבע. ולאח\"ז מוסיף בכתוב שני חיי שרה, שכל סוגי העבודה דמאה שנה (כתר) עשרים שנה (מוחין) ושבע שנים (מדות) הם שוין לטובה, שכל ענינם הוא להשלים כוונת העצמות, שהיא בכל עניני העבודה בשוה<sup data-n=\"2850\">34</sup>. ויש להוסיף בהביאור דכולן שוין לטובה, שטובה רומז על עצם ומקור הטוב וטבע הטוב להיטיב<sup data-n=\"2851\">35</sup> כפי שנמשך ומתגלה בנשמתו של כאו\"א מישראל שהיא \"חלק אלקה ממעל ממש\"<sup data-n=\"2852\">36</sup>, חלק מן העצם שעל ידו תופסים בהעצם<sup data-n=\"2853\">37</sup>, וכאשר העבודה היא מצד עצם הנשמה, שזהו\"ע הביטול והקבלת עול, אזי כל עניני העבודה הם בשוה, וההשתוות היא לטובה, שכל עניני העבודה חדורים בהנקודה הכללית דהמשכת וגילוי עצם הטוב למטה, להיות לו ית' דירה בתחתונים.\nח) <b>ויהי</b> רצון, שכיון שבימינו אלה נשלמו כל מעשינו ועבודתינו בכל פרטי הענינים דמאה שנה ועשרים שנה ושבע שנים, ובאופן דשני חיי שרה שכולן שוין לטובה, כדברי כ\"ק מו\"ח אדמו\"ר נשיא דורנו שכבר צחצחו את הכפתורים<sup data-n=\"2854\">38</sup>, ועומדים מוכנים<sup data-n=\"2855\">39</sup> לקבל פני משיח צדקנו, ובפרט שלאחרי זה עברו עוד עשיריות שנים שבהם צעקו בנ\"י עד מתי (וואָס דאָס דאַרף דאָך אויך האָבן אַ שיעור), תבוא תיכף ומיד הגאולה האמיתית והשלימה ע\"י משיח צדקנו, ואז יתגלה הענין דתולדות יצחק (כפי שמתחילין לקרוא בתורה במנחה), כמארז\"ל<sup data-n=\"2856\">40</sup> שלעתיד לבוא יאמרו ליצחק דוקא כי אתה אבינו<sup data-n=\"2857\">41</sup>, כיון שהתענוג והצחוק (יצחק<sup data-n=\"2858\">42</sup>) שנעשה ע\"י מעשינו ועבודתינו כל משך זמן הגלות<sup data-n=\"2859\">43</sup> יתגלה לעתיד לבוא, שאז<sup data-n=\"2860\">44</sup> ימלא שחוק פינו<sup data-n=\"2861\">45</sup>, ואז יהי' הענין דמאה שנה ועשרים שנה ושבע שנים באופן נעלה יותר<sup data-n=\"2862\">46</sup>, הן הענין דמאה שנה, מאהברכות, והן הענין דכ\"ז שנה, שרומז (גם) לכ\"ז<sup data-n=\"2863\">47</sup> אותיות התורה<sup data-n=\"2864\">48</sup>, כיון שכל עניני התומ\"צ יהיו בתכלית השלימות, כמצות רצונך<sup data-n=\"2865\">49</sup>, ותורה חדשה מאתי תצא<sup data-n=\"2866\">50</sup>, טעמי תורה שיתגלו לעתיד לבוא בתורתו של משיח<sup data-n=\"2867\">51</sup>, כולל גם התורה חדשה דרבותינו נשיאינו עד לבעל יום ההולדת דכ\"ף מרחשון, ובנו יחידו ממלא מקומו כ\"ק מו\"ח אדמו\"ר נשיא דורנו, שהקיצו ורננו שוכני עפר<sup data-n=\"2868\">52</sup>, והם בראשם, ויאמרו תורה חדשה, חידוש גם לגבי הקב\"ה, כביכול, ע\"ד מארז\"ל<sup data-n=\"2869\">53</sup> נצחוני בני נצחוני, עד לתורה חדשה מאתי תצא, מאתי<sup data-n=\"2870\">54</sup> דייקא, ובאופן שלא ילמדו עוד איש את רעהו גו' כי כולם ידעו אותי<sup data-n=\"2871\">55</sup>, אותי<sup data-n=\"2870\">54</sup> דייקא, ועוד והוא העיקר, שכל זה יהי' תיכף ומיד ממש, ממש ממש.\n**********",[["2816","*","יצא לאור בשעתו, \"<i>יום ג' כ\"ה מ\"ח</i>,<i> שנת ה'תנש\"א</i>\"."],["2817","1","ריש פרשתנו."],["2818","2","לקו\"ת ר\"פ ברכה. ד\"ה זה במאמרי אדמו\"ר הזקן על פרשיות התורה (ע' קלא ואילך). תקס\"ו (סה\"מ תקס\"ו ע' מח ואילך)."],["2819","3","ביאורי הזהר לאדמו\"ר האמצעי ריש פרשתנו. שם בהוספות (קלא, סע\"ב ואילך). תורת חיים ריש פרשתנו. ביאורי הזהר ואוה\"ת להצ\"צ ריש פרשתנו. ד\"ה ויהיו חיי שרה תר\"ל. תרל\"א (נדפס בהוספות לסה\"מ תרמ\"ג ע' רפג ואילך). תשמ\"א (לעיל ע' רעז ואילך). תשמ\"ה (לעיל ע' רפז ואילך)."],["2820","4","ד\"ה זה תרמ\"ג. תרע\"ה (בהמשך תער\"ב ח\"ב). עטר\"ת. פר\"ת."],["2821","5","דמיני' אזלינן, ובתוך ג' ימים, שנחשבים בכמה ענינים למציאות אחת (ראה לדוגמא – פסחים קו, סע\"א)."],["2822","6","ראה זח\"ג קנב, א. מכתבי תורה (להרגצ'ובי) מכתב צט."],["2823","7","ראה רמב\"ן עה\"פ לך לך יב, ו. וראה ד\"ה הנ\"ל ה'תשמ\"א ס\"ב (לעיל ע' רעח), ובהערות שם."],["2824","8","ראה זהר פרשתנו (קכב, סע\"ב): שרה זכתה לחיין עלאין לה ולבעלה <i>ולבנאה בתראה</i>, הה\"ד הביטו אל צור חוצבתם ואל מקבת בור נוקרתם, ועל דא ויהיו חיי שרה כו'."],["2825","9","ח\"א פרשתנו קכג, א."],["2826","10","ביאורי הזהר לאדמו\"ר האמצעי ריש פרשתנו. וראה גם <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670365\" data-slug=\"torat-chaim\" data-id=\"2300670365\">תורת חיים שם קכו, ד</a>."],["2827","11","זהר ח\"ב נו, א. ח\"ג ד, א. פרדס שער ח (שער מהות והנהגה) פי\"ד."],["2828","12","ספר יצירה פ\"א מ\"ז.\nובפרטיות יותר: לפני א' מה אתה סופר הוא בחי' עתיק, וכשנמשך ומאיר בבחי' אריך נקרא \"מאה שנה\", ובהיותו במקומו ה\"ה למעלה מגדר מספר, \"שני חיי שרה\" (ראה ד\"ה ויהיו חיי שרה ה'תשמ\"א – לעיל ע' רפג הערה 68)."],["2829","13","שנוסף על היותו פשוטו של מקרא, ה\"ה גם יינה של תורה (\"היום יום\" כט שבט), ששייך לחלק הסוד שבתורה."],["2830","14","ד\"ה ויהיו חיי שרה תרל\"א. תרמ\"ג."],["2831","15","מנחות מג, סע\"ב."],["2832","16","עקב יו\"ד, יב."],["2833","17","תוספות שם (מפרש\"י. וראה חדא\"ג מהרש\"א שם). וכ\"ה בתניא רבתי בתחלתו. ערוך ערך מאה. שו\"ע אדה\"ז או\"ח הל' ברכות השחר רסמ\"ו. ובכ\"מ."],["2834","18","שבהערה 14. וראה גם ביאורי הזהר לאדמו\"ר האמצעי ריש פרשתנו. <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670354\" data-slug=\"torat-chaim\" data-id=\"2300670354\">תורת חיים שם קכו, ג</a>."],["2835","19","ויש לקשר זה עם הפירוש שעשרים שנה קאי על חכמה ובינה (מוחין עצמם) – כי, חכמה היא בקו הימין, גילוי (חיוב), ובינה היא בקו השמאל, העלם (שלילה)."],["2836","20","ד\"ה להבין ענין הברכות ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370022\" data-slug=\"torah-or\" data-id=\"3901370022\">תו\"א בראשית ו, א</a> ואילך. ועם הגהות – ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316560169\" data-slug=\"or-hatorah-hb\" data-id=\"8316560169\">אוה\"ת בראשית כרך ג תקנא, א</a> ואילך. המשך חייב אדם לברך תרל\"ח [סה\"מ תרל\"ח ע' פז ואילך]. וראה גם ד\"ה ויהיו חיי שרה תרע\"ה (המשך תער\"ב ח\"ב פשנ\"ט ואילך)."],["2837","21","ויתירה מזה – להמשיך בחי' אתה שלמעלה משם הוי' שיומשך ויתגלה בשם הוי', ועד שיומשך ויתגלה גם בשם אלקים."],["2838","22","ראה גם המשך תער\"ב שם פש\"ס."],["2839","23","לשון אדה\"ז בשו\"ע שם."],["2840","24","ברכות לה, סע\"א ובפרש\"י שם. שו\"ע אדה\"ז או\"ח ר\"ס קסז. סדר ברכת הנהנין בתחילתו."],["2841","25","תהלים כד, א."],["2842","26","ראה גם ביאורי הזהר ותורת חיים שבהערה 18."],["2843","27","זהר ח\"א רמז, א. ח\"ג חצר, ב. ועוד."],["2844","28","ראה בארוכה ד\"ה אל תצר את מואב לאדמו\"ר האמצעי (מאמרי אדמו\"ר האמצעי דברים ח\"א ע' ד ואילך)."],["2845","29","ראה סידור (עם דא\"ח) צז, ג ואילך. ובכ\"מ."],["2846","30","ספר יצירה פ\"א מ\"ז."],["2847","31","ראה תנחומא נשא טז. בחוקותי ג. ב\"ר ספ\"ג. במדב\"ר פי\"ג, ו. תניא רפל\"ו."],["2848","32","שבהערה 14. וראה גם ביאורי הזהר להצ\"צ פרשתנו ע' עט ואילך. אוה\"ת פרשתנו שם קיא, ב. המשך תער\"ב שבהערה 20."],["2849","33","בשלח טז, ז."],["2850","34","להעיר, שהענין ד\"כולן שוין\" שייך גם בהעילוי שנעשה בהעליון (מאה) ע\"י ההמשכה למטה (בת ק' כבת כ' ובת כ' כבת ז'), כי, העילוי שנעשה בעליון ע\"י ירידתו למטה הוא (לא רק שנוסף אצלו מעלת המטה, אלא) גם שעי\"ז מתגלה הבלי גבול שלו, שאינו מוגדר בהגדר דמעלה וביכלתו לירד גם למטה. אבל, אין זה אמיתת הענין ד\"כולן שוין\", כי, מזה עצמו שגילוי הבל\"ג שלו הוא ע\"י ירידתו למטה (וככל שיורד למטה יותר מתגלה יותר הבל\"ג שלו), מוכח, שישנו הענין ד\"מעלה\" ו\"מטה\" (שלכן שייך לומר עליו העילוי וההפלאה שאינו מוגדר בזה), משא\"כ לגבי העצמות אין מלכתחילה הגדר דמעלה ומטה, ולכן כשהעבודה היא להשלים כוונת העצמות, \"כולן שוין\" ממש."],["2851","35","עמה\"מ שער שעשועי המלך רפ\"א. שעהיוה\"א פ\"ד (עט, א)."],["2852","36","<a class=\"ft-cite\" href=\"#/read/tanya/3401310007\" data-slug=\"tanya\" data-id=\"3401310007\">תניא רפ\"ב</a>."],["2853","37","כתר שם טוב (הוצאת קה\"ת, תשנ\"ט) הוספות סי' רכז. וש\"נ."],["2854","38","שיחת שמח\"ת תרפ\"ט (סה\"ש תרפ\"ט ע' 42)."],["2855","39","ראה אגרות-קודש אדמו\"ר מהוריי\"צ ח\"ד ריש ע' רעט."],["2856","40","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370083\" data-slug=\"torah-or\" data-id=\"3901370083\">שבת פט, ב</a>. וראה תו\"א תולדות יז, ג. ויצא כא, ג. תורת חיים תולדות ד, ד ואילך. ויצא כד, סע\"ד ואילך. ועוד."],["2857","41","ישעי' סג, טז."],["2858","42","שנקרא בשם יצחק ע\"ש צחוק עשה לי אלקים – וירא כא, ו. וראה בפרש\"י עה\"פ לך לך טז, יט."],["2859","43","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310042\" data-slug=\"tanya\" data-id=\"3401310042\">תניא רפל\"ז</a>."],["2860","44","תהלים קכו, ב."],["2861","45","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370084\" data-slug=\"torah-or\" data-id=\"3901370084\">תו\"א תולדות יז, ד</a>. ואילך. תו\"א ותורת חיים ויצא שבהערה 40."],["2862","46","ראה <a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670365\" data-slug=\"torat-chaim\" data-id=\"2300670365\">תורת חיים פרשתנו קכו, ד</a> ואילך: מ\"ש עוד שני חיי שרה קאי לע\"ל בעוה\"ב לאחר תשלום כל הבירורים כו', עיי\"ש."],["2863","47","בצירוף האותיות הכפולות מנצפ\"ך (שרומזים על הגאולה – פרקי דר\"א פמ\"ח. יל\"ש ר\"פ לך לך. ועוד)."],["2864","48","סד\"ה ויהיו חיי שרה תר\"ל."],["2865","49","ראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370209\" data-slug=\"torah-or\" data-id=\"3901370209\">תו\"א ויחי מו, סע\"א</a> ואילך. תורת חיים ר\"פ ויחי (צה, א. צו, ג-ד). <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010223\" data-slug=\"or-hatorah-hb\" data-id=\"8159010223\">אוה\"ת ויחי כרך ו</a> תתשכח, ב ואילך. שם כרך ז תתתסח, סע\"ב ואילך. המשך וככה תרל\"ז פי\"ז ואילך. <i>ובכ\"מ</i>."],["2866","50","ישעי' נא, ד. ויק\"ר פי\"ג, ג."],["2867","51","ראה גם ד\"ה אנכי מגן לך תרע\"ח* (קה\"ת כ\"ף מרחשון תנש\"א. נדפס לאח\"ז בסה\"מ ליקוט ח\"ב ע' רלט ואילך) שגילוי טעמי תורה לעתיד לבוא \"זהו עיקר הגילוי דמשיח והוא עיקר הקבלת שכר האמיתי כו'\"."],["2868","52","ישעי' כו, יט."],["2869","53","ב\"מ נט, ב."],["2870","54","אותיות א' ת' – כל (כ\"ז) אותיות התורה."],["2871","55","ירמי' לא, לג.\n*) <i>שנתגלה עוה\"פ בהשגחה פרטית בסמיכות ליום הולדתו כ\"ף מרחשון השתא (ראה התוועדויות תנש\"א ח\"א ע' 318 ובהערות שם)</i>."]]],[1500360043,"<h3>בס\"ד. ש\"פ חיי שרה, מבה\"ח כסלו ה'תשל\"ז<sup data-n=\"2872\">*</sup></h3>\n<b>ואברהם</b> זקן בא בימים וה' ברך את אברהם בכל<sup data-n=\"2873\">1</sup>, ומדייק אדמו\"ר (מהורש\"ב) נ\"ע במאמרו ד\"ה זה (דשנת תרס\"ו<sup data-n=\"2874\">2</sup>) מה שאומר בכל סתם ואינו מפרש במה ברכו. ונקודת הביאור<sup data-n=\"2875\">3</sup>, דכל הוא בחינת העלם העצמי, שמשם נמשכים כל הגילויים. כדאיתא בזהר<sup data-n=\"2876\">4</sup> עה\"פ וה' ברך את אברהם בכל, דאברהם אתברך מאתר דכל ברכאן נפקי מתמן. ולכן אומר בכל סתם ואינו מפרט פרטים, לפי שהוא בחינת בלי גבול שלמעלה מפרטים. וצריך להבין הקשר והשייכות דפירוש הזהר שבכל הוא אתר דכל ברכאן נפקי מתמן עם פירוש רש\"י עה\"פ<sup data-n=\"2877\">5</sup> שבכל קאי על יצחק (בכל בגימטריא בן). וגם, דמהמשך הכתובים משמע שפסוק זה (ואברהם זקן וגו') הוא הקדמה לויאמר אברהם אל עבדו גו' ולקחת אשה לבני ליצחק<sup data-n=\"2878\">6</sup>, וצריך להבין מהי השייכות דוה' ברך את אברהם בכל, שנתברך מאתר דכל ברכאן נפקי מתמן, לזה ששלח את עבדו לקחת אשה לבנו<sup data-n=\"2879\">7</sup>. גם צריך להבין גודל העילוי דנשואי יצחק ורבקה שהוא נעלה יותר גם מבחינת בכל (אתר דכל ברכאן נפקי מתמן), ועד דזה שהוי' ברך את אברהם בכל הוא רק הקדמה לנשואי יצחק ורבקה.\nב) <b>ויובן</b> זה בהקדים מה דאיתא במדרש<sup data-n=\"2880\">8</sup> אין הקב\"ה מעלה את האדם לשררה עד שבודק ובוחן אותו וכו' וכן אתה מוצא באבינו אברהם נסהו הקב\"ה עשר נסיונות ועמד בהן ואח\"כ ברכו שנאמר וה' ברך את אברהם בכל. ומבאר הצ\"צ<sup data-n=\"2881\">9</sup>, דעשר נסיונות הם כנגד עשר ספירות, משא\"כ כל הוא פנימיות הכתר שאינו<sup data-n=\"2882\">10</sup>בחשבון ע\"ס. דבבחינה זו, אין אתערותא דלתתא מגעת לשם. ולאחרי שעמד אברהם בעשר נסיונות כנגד ע\"ס שבהן שייך אתעדל\"ת, אזי ברכו בכל, פנימיות הכתר. ויש לומר, דזהו גם דיוק לשון הכתוב ואברהם זקן בא בימים וה' ברך את אברהם בכל, דזה שהי' זקן בא בימים, עם היות שזהו ברכת הקב\"ה, מייחס הכתוב לאברהם (<i>ואברהם</i> זקן בא בימים), משא\"כ בנוגע כל אינו אומר שאברהם הי' לו כל כ\"א שהוי' ברכו בכל, דיש לומר הביאור בזה<sup data-n=\"2883\">11</sup>, דזה שנתברך בזקנה ובימים הוא אתערותא דלעילא שמתעוררת ונמשכת ע\"י אתעדל\"ת<sup data-n=\"2884\">12</sup>, עבודתו של אברהם, משא\"כ זה שנתברך בכל הוא אתעדל\"ע הבאה מלמעלה שאין אתעדל\"ת מגעת לשם [וזה שברכה זו באה דוקא לאחרי שעמד בעשר נסיונות הוא לפי שצריך להיות אתר<sup data-n=\"2885\">13</sup> שלים<sup data-n=\"2886\">14</sup>], ולכן כתיב בה וה' ברך גו'.\nג) <b>והגם</b> שגם זקן בא בימים הוא בחינת עתיק יומין, כדאיתא במדרש<sup data-n=\"2887\">15</sup> שאמר הקב\"ה לאברהם בא ולבוש לבושי שנאמר ואברהם זקן בא בימים, ופירש במתנות כהונה דזה שבא בימים הוא לבושו של הקב\"ה הוא כי הקב\"ה נק'<sup data-n=\"2888\">16</sup> עתיק יומין [והצ\"צ<sup data-n=\"2889\">17</sup> מוסיף שגם זקן (דיקנא<sup data-n=\"2890\">18</sup>) הוא לבושו דהקב\"ה, כי בעתיק יומין כתיב<sup data-n=\"2888\">16</sup> לבושי' כתלג חיוור<sup data-n=\"2891\">19</sup> שהוא<sup data-n=\"2892\">20</sup> בחינת י\"ג תיקוני דיקנא], יש לומר, שהכוונה בזה היא (לא לעתיק ממש, אלא<sup data-n=\"2893\">21</sup>) לאריך שנקרא ג\"כ בשם עתיק יומין<sup data-n=\"2894\">22</sup> [ויש לומר דזה שאריך נקרא בשם עתיק יומין הוא לפי שבו מלובשים ז\"ת דעתיק<sup data-n=\"2895\">23</sup>], משא\"כ כל הוא עתיק עצמו. ויתירה מזו, שבעתיק גופא הוא בחינת ג\"ר דעתיק שאינם מלובשים באריך<sup data-n=\"2896\">24</sup>,ועד לבחינת פנימיות עתיק ולמעלה יותר, וכנ\"ל (סעיף א) מהמאמר שכל הוא בחינת העלם העצמי. וזהו שהענין דזקן בא בימים מייחס הכתוב לאברהם (ואברהם זקן בא בימים) משא\"כ בנוגע כל אומר שהוי' ברך את אברהם בכל, כי זה שהי' לאברהם בחינת זקן בא בימים, שהוא בחיצוניות הכתר, המשיך זה ע\"י עבודתו. ויש לומר, דזוהי גם השייכות דהפירוש שזקן בא בימים הוא לבושו דהקב\"ה עם הפירוש<sup data-n=\"2897\">25</sup> שזקן הוא זה שקנה חכמה<sup data-n=\"2898\">26</sup> (תורה) ובא בימים הוא לבושי המצוות<sup data-n=\"2899\">27</sup>, כי זה שהי' לאברהם לבושו של הקב\"ה, המשיך זה ע\"י התורה והמצוות שלו.\n<b>ויש</b> לבאר זה בפרטיות יותר, דזקן ובא בימים הם שתי מדריגות. זקן שהוא י\"ג תיקוני דיקנא, הוא במוחא סתימאה דאריך, ובא בימים הוא אריך עצמו [דזה שאריך נקרא בשם עתיק יומין<sup data-n=\"2900\">28</sup> הוא בעיקר בעצמיות אריך], גלגלתא דאריך. וזוהי השייכות דשני ענינים אלו (זקן ובא בימים) שלמעלה (לבושו של הקב\"ה) עם שני ענינים אלו בעבודת האדם, כי מוחא סתימאה דאריך הוא פנימי, השרש דתורה<sup data-n=\"2901\">29</sup>, וגלגלתא דאריך הוא מקיף, השרש דמצוות<sup data-n=\"2901\">29</sup>. וע\"י עסק התורה דאברהם, זקן שקנה חכמה, המשיך בחינת הדיקנא ומוחא סתימאה דאריך (זקן), וע\"י שהי' בא בימים, לבושי המצוות, המשיך בחינת גלגלתא<sup data-n=\"2902\">30</sup> דאריך (בא בימים). משא\"כ כל שהוא בחינת עתיק, אין אתעדל\"ת מגעת לשם, ולכן כתיב <i>וה' ברך</i> את אברהם בכל, אתערותא דלעילא הבאה מלמעלה. אלא שאתערותא דלעילא זו<sup data-n=\"2903\">31</sup> שורה ומתגלה דוקא לאחרי שלימות העבודה (והאתערותא דלעילא שע\"י האתערותא דלתתא), לכן, מה שברך ה' את אברהם בכל הי' זה דוקא לאחרי שעמד בעשר נסיונות, כנ\"ל (סעיף ב בתחלתו).\nד) <b>והנה</b> גם בבחינת כל (עתיק) שלמעלה מבא בימים (אריך) יש כמה מדריגות. וכמובן מהמבואר בהמאמר (ד\"ה ואברהם זקן) דהצ\"צ<sup data-n=\"2904\">32</sup>, שבתחלה אומר, שאברהם זכה לבחינת כל ע\"י קיום מל\"ת וגם בבחינה זו דכל אומר שהוא פנימיותעתיק [כמבואר שם, דזה שוהוי' ברך את אברהם בכל הוא לאחרי שנאמר בא בימים, כי ימים הם מ\"ע, וע\"י העבודה דבא בימים קיום מ\"ע זכה לבחינת אריך (בחינת בא בימים דלמעלה), משא\"כ זה שזכה לבחינת כל שזכה לזה ע\"י קיום מל\"ת הוא פנימיות עתיק שלמעלה מאריך<sup data-n=\"2905\">33</sup>], ולאח\"ז אומר שאברהם זכה לזה ע\"י העשרה נסיונות (כנ\"ל סעיף ב מהמדרש), דיש לומר, שבחינת כל שזכה ע\"י הנסיונות הוא נעלה יותר מבחינת כל שזכה ע\"י קיום מל\"ת. וי\"ל הביאור בזה, דבחינת עתיק (כל) שזכה ע\"י קיום מל\"ת, יש לו שייכות להשתלשלות, ולכן, עבודת האדם שעל ידה זוכה לזה היא עבודה שתלוי' ברצונו (היינו עבודה שבסדר והדרגה), אלא שבזה גופא, מכיון שעתיק הוא למעלה מהשתלשלות, לכן העבודה היא לא בעשי' אלא בשב ואל תעשה, שלילה<sup data-n=\"2906\">34</sup>. משא\"כ בחינת עתיק (כל) שזכה ע\"י הנסיונות, הוא נעתק ונבדל לגמרי, וכנ\"ל (סעיף א) מהמאמר שהוא העלם העצמי. ולכן, כשעבודת האדם היא תלוי' ברצונו, אין לה שום דמיון<sup data-n=\"2907\">35</sup> לבחינה זו דעתיק שנעתק ומובדל לגמרי. ורק ע\"י העבודה דנסיונות שאינה תלוי' ברצון האדם [שהרי אסור לאדם להעמיד עצמו בנסיון, ולא עוד אלא שנצטווינו לבקש אל תביאנו לידי נסיון<sup data-n=\"2908\">36</sup>], עי\"ז דוקא זוכים לגילוי בחינה זו.\nה) <b>ויש</b> לומר, דזה שהוי' ברך את אברהם בכל דוקא לאחרי שעמד בנסיון העשירי הוא, כי עשרה הנסיונות הם כנגד ע\"ס (כנ\"ל סעיף ב), והשלימות דכל ענין הוא כשהוא כלול מכל הע\"ס. ובעומק יותר יש לומר, שבכדי לזכות לבחינת כל שנעתק ומובדל לגמרי מהשתלשלות, הוא דוקא ע\"י עבודה שלמעלה ממדידה והגבלה לגמרי. וכיון שעשר הנסיונות הם כנגד ע\"ס (השתלשלות), ועד שהם כנגד עשרה מאמרות<sup data-n=\"2909\">37</sup> (שהם למטה מהספירות עצמם<sup data-n=\"2910\">38</sup>), הרי זה שעמד בנסיונות אלו קשור עדיין עם מדידה והגבלה, ולכן הי' צריך להיות נסיון העשירי, הוא נסיון העקידה<sup data-n=\"2911\">39</sup>, המיוחד דכל הנסיונות, שלמעלה ממדידה והגבלה. דהגם שגם נסיון זה הוא בכלל עשר הנסיונות, יש לומר, שבנסיון זה יש (גם) ענין שלמעלה מע\"ס. וע\"ד דאיתא במדרש<sup data-n=\"2912\">40</sup> עה\"פ<sup data-n=\"2913\">41</sup> אחד עשר יום מחורב שקאי על הדבור אנכי (דבור הראשון דעשרת הדברות), המיוחד שבעשרה. ומבואר בחסידות<sup data-n=\"2914\">42</sup>, דזה שהדבור אנכינקרא בשם אחד עשר, הגם שהוא ממנין עשרת הדברות, הוא, כי הדבור אנכי הוא בכתר. וכיון שבכתר יש ב' מדריגות, חיצוניות הכתר שנמנה במנין הע\"ס ופנימיות הכתר שאינו נמנה עמהם<sup data-n=\"2915\">43</sup>, לכן, זה שהדבור אנכי הוא ממנין עשרת הדברות הוא מצד חיצוניות הכתר שבו, אבל מצד פנימיות הכתר שבו הוא אחד עשר שאינו במנין עשרת הדברות<sup data-n=\"2916\">44</sup>, חד ולא בחושבן<sup data-n=\"2917\">45</sup>. ויש לומר, שעד\"ז הוא בנסיון העקידה, שהי' נסיון גדול יותר מהנסיונות שלפניו (בדוגמת הכתר שלמעלה מכל הספירות), שיש בזה שני ענינים. זה שהגם שאברהם בטבעו הי' איש החסד (וטבע החסד שלו הי' מצד שרשו), מ\"מ עקד את יצחק בנו ולקח את המאכלת לשחוט את בנו, היפך הטבע שלו (שמצד שרשו)<sup data-n=\"2918\">46</sup>. וז\"ש<sup data-n=\"2919\">47</sup> עתה ידעתי כי ירא אלקים אתה, עתה דוקא, כי הנסיונות שלפני נסיון העקידה לא היו היפך הטבע דחסד, ועתה (לאחרי הנסיון דעקידה) ידעתי כי ירא אלקים אתה, מדת היראה והגבורה. וזה שכל הנסיונות היו בנוגע לעצמו, ונסיון העקידה הי' בנוגע לבנו יחידו. דאהבת אדם לבנו, ובפרט לבנו יחידו, היא גדולה יותר מהאהבה לעצמו, וכל אשר לאיש יתן בעד בנו. ולכן, נסיון העקידה הוא למעלה מהנסיונות שלפני העקידה. ויש לומר, דענין הראשון בנסיון העקידה, שזה הי' היפך טבע החסד דאברהם, מכיון שגם ענין זה הוא בנוגע לעצמו, יש לו איזה ערך לנסיונות שלפניו, אלא שהוא נעלה מהם. [ויש לומר, דזה שנסיון העקידה הוכיח שגם נסיונות הקודמים יש בהם ממש<sup data-n=\"2920\">48</sup>, הוא מפני שיש ערך ביניהם. דבדברים שאין שום ערך ביניהם, אין שייך להביא הוכחה מזה על זה]. בדוגמת חיצוניות הכתר (אריך), שעם היותו למעלה משאר הספירות, מ\"מ הוא שרש ומקור להם, ועד שהוא נמנה במנין הספירות. וענין השני שבנסיון העקידה, שנסיון זה הי' בנוגע לבנו יחידו, הוא ענין חדש לגמרי שלא הי' דוגמתו בהנסיונות שלפניו. ובדוגמת עתיק (פנימיות הכתר) שהוא נעתק ומובדל. וז\"ש<sup data-n=\"2921\">49</sup> בי נשבעתי גו', בי ממש בחינת עתיק<sup data-n=\"2922\">50</sup>, והטעם לזה הוא כי יען גו' ולא חשכת את בנך את יחידך<sup data-n=\"2921\">49</sup>. וע\"פ כל הנ\"ל מובן שלאחרי שעמד אברהם בנסיון העקידה, אז דוקא ברך ה' את אברהם בכל, כי זה שעקד גם את בנו יחידו היא עבודה שלמעלה ממדידה והגבלה לגמרי, ולכן אז דוקא ברך ה' את אברהם בכל, פנימית עתיק, העלם העצמי.\nו) <b>והנה</b> הכוונה בהמשכת העלם העצמי שנמשך לאברהם היא, שהעלם זה יהי' לא רק כמו שהוא במקומו, בעצמותו, אלא שיומשך ממנו השפעה בליגבול. וכדאיתא בזהר<sup data-n=\"2923\">51</sup>, מאי בכל, אתר דנהרא דלא פסיק מימוי לעלמין. וזוהי השייכות דפירוש הזהר שבכל הוא העלם העצמי עם פירוש רש\"י שבכל קאי על יצחק (בכל בגימטריא בן), כי אברהם הוא חסד דעתיק ויצחק גבורה דעתיק<sup data-n=\"2924\">52</sup>, וזהו שביצחק כתיב<sup data-n=\"2925\">53</sup> וארבה את זרעו ואתן לו את יצחק, דריבוי ההשפעה (וארבה את זרעו) הוא מהגבורות דוקא, תגבורת ההשפעה, כמבואר בארוכה בסידור (עם דא\"ח) ד\"ה להבין ענין תק\"ש ע\"פ כוונת הבעש\"ט<sup data-n=\"2926\">54</sup>. והגם שריבוי הוא התחלקות פרטים, הנה הריבוי שנמשך מהגבורות דיצחק, הוא באופן שגם בהפרטים נרגש בגילוי ששרש המשכתם הוא מהפשיטות דהעלם העצמי דלא פסיק מימוי לעלמין. וע\"י שגם בהפרטים ניכר הפשיטות, עי\"ז מתגלה הפנימיות והעצמיות שלו, שאינו מוגדר בשום גדר וביכלתו לבוא (בגילוי) גם בפרטים. וזהו שלע\"ל יאמרו ליצחק כי אתה אבינו כי אברהם לא ידענו<sup data-n=\"2927\">55</sup>, כי לע\"ל יהי' גילוי פנימיות עתיק<sup data-n=\"2928\">56</sup>, והגילוי דפנימיות עתיק הוא דוקא ע\"י הגבורות דיצחק<sup data-n=\"2929\">57</sup>.\n<b>וזהו</b> שוהוי' ברך את אברהם בכל הוא הקדמה לנשואי יצחק ורבקה, כי תכלית הכוונה הוא שפנימיות הכתר יומשך בגילוי עד למטה מטה, וזה נעשה ע\"י יחוד יצחק ורבקה, כי יצחק ורבקה, השרש דשניהם הוא בגבורה דעתיק, אלא שיצחק הוא בחינת מ\"ה ורבקה היא בחינת ב\"ן, והגילוי למטה הוא ע\"י שם ב\"ן<sup data-n=\"2930\">58</sup>. וזהו שוהוי' ברך את אברהם בכל הוא רק הקדמה לנשואי יצחק ורבקה, כי תכלית הכוונה דברכה זו הוא שבחינת כל יומשך גם בבי\"ע, בעוה\"ז התחתון, ועד בהמקום שבו היתה רבקה, שושנה בין החוחים<sup data-n=\"2931\">59</sup>, שגם שם יומשך הגילוי דפנימיות עתיק.\nז) <b>והנה</b> זה שמסופר בתורה שבע\"פ שאברהם זכה לבחינת כל ע\"י שעמד בעשר נסיונות הוא (ככל הענינים שבתורה מלשון הוראה<sup data-n=\"2932\">60</sup>) הוראה שצריך להיות (דוגמת<sup data-n=\"2933\">61</sup>) העבודה דנסיונות, היינו, שהעבודה צריכה להיות ביגיעה גדולה, יגיעה שלא ע\"ד הרגיל, בדוגמת העבודה דנסיונות. וזהו דאיתא בזהר שם עה\"פ<sup data-n=\"2934\">62</sup> עין לא ראתה גו' יעשה למחכה לו, מאי למחכה לו כו' אינון דדחקין למלה דחוכמתא כו' [וענין זה שבזהר בא בהמשך להפירוש מאי בכל, כמובא בהמאמר], שע\"י היגיעה בתורה, יגיעה שלא ע\"ד הרגיל [וכמבואר בהמאמר דדחקין למלה דחוכמתא הואיגיעה בדרך אור חוזר], ומזה נמשך שגם קיום המצוות יהי' ביגיעה גדולה (ע\"ד מרז\"ל<sup data-n=\"2935\">63</sup> גדול לימוד שמביא לידי מעשה), כולל גם היגיעה בהפצת המעינות חוצה, דנוסף להיגיעה שצריכה להיות בלימוד והבנת המעינות (דחקין למלה דחוכמתא), צריכה להיות יגיעה מיוחדת להפיץ את המעינות חוצה, להביא את המעינות גם לאלו שנמצאים חוצה, \"בין החוחים\", ועי\"ז יהי' אתי מר דא מלכא משיחא<sup data-n=\"2936\">64</sup>, שאז יהי' גילוי העלם העצמי, עין לא ראתה, במהרה בימינו ממש.\n**********",[["2872","*","יצא לאור ב<b>קונטרס כ\"ה מרחשון – תש\"נ</b>, \"לקראת יום הבהיר כ\"ה מרחשון הבעל\"ט, – שבשנה זו הוא גם יום התחלת לימוד הרמב\"ם במחזור השביעי* . . <i>מוצש\"ק כף מ\"ח שנת ה'תש\"נ</i>\"."],["2873","1","פרשתנו (חיי שרה) כד, א."],["2874","2","נדפס בהמשך תרס\"ו ע' עח ואילך."],["2875","3","המשך הנ\"ל ע' פד-ה."],["2876","4","ח\"א פרשתנו קל, ב."],["2877","5","דנוסף לזה שכל הפירושים שבאותו הפסוק שייכים זל\"ז** – מכיון שפירוש רש\"י על התורה הוא \"<i>יינה</i> של תורה\" (\"היום יום\" כט שבט), יש לו שייכות מיוחדת עם הפירוש ע\"ד הסוד (זהר). וראה בארוכה לקו\"ש ח\"ה בתחלתו, ובהערות שם."],["2878","6","פרשתנו שם, ב-ד."],["2879","7","בנצוצי אורות לזהר שם, שוהוי' ברך את אברהם בכל (לפירוש הזהר) הוא טעם על זה שצוה שלא לקחת אשה מבנות הכנעני. ואולי י\"ל, דכמו שלפירוש רש\"י, וה' ברך גו' בכל הוא טעם גם על השליחות לקחת אשה לבנו (\"מאחר שהי' לו בן הי' צריך להשיאו אשה\"), עד\"ז הוא גם לפי פירוש הזהר (ראה לעיל הערה 5)."],["2880","8","במדב\"ר פט\"ו, יב."],["2881","9","בד\"ה זה באוה\"ת פרשתנו (כרך ד) תשעט, סע\"א."],["2882","10","ע\"ח שער מב (שער דרושי אבי\"ע) פ\"א, הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380276\" data-slug=\"likkutei-torah\" data-id=\"4001380276\">לקו\"ת בחוקותי מו, ג</a>. אוה\"ת שם. <i>ובכ\"מ</i>. ע\"ח שער כג (שער מוחין דצלם) פ\"ה, הובא ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381170\" data-slug=\"likkutei-torah\" data-id=\"4001381170\">לקו\"ת שה\"ש י, ב</a>. <i>ובכ\"מ</i>.\n*) <i>להלומדים ג' פרקים ליום</i><b>.</b><i> וגם התחלת מחזור השלישי להלומדים פרק אחד ליום (וכן בספר המצוות)</i><b>.</b>\n**) <i>כידוע הראי' לזה מ</i>\"<i>שעטנז</i>\"<i> (נדה סא</i>,<i> ב) – ראה לקו\"ש ח\"ג ע' 782</i>.<i> ובכ\"מ</i>."],["2883","11","ראה עד\"ז ד\"ה ואברהם זקן תרע\"ג בסופו (המשך תער\"ב ח\"א ע' קצ)."],["2884","12","באוה\"ת שבהערה 9, שגם \"זקן בא בימים\" הוא פנימיות הכתר שאין שייך בו אתעדל\"ת. ואולי יש לומר, שזהו בכללות, אבל בפרטיות, ענין זה (המשכה מלמעלה שלא ע\"י אתעדל\"ת) הוא דוקא בבחינת בכל – ראה לקמן סוף ס\"ג ובהערה 31 שם. ועפ\"ז מובן: (א) לשון הכתוב \"<i>ואברהם</i> זקן בא בימים\", ולא שהוי' ברכו כמ\"ש בנוגע ל\"בכל\", כבפנים. (ב) זה שבמדרש שבהערה 8 מעתיק רק \"וה' ברך את אברהם בכל\" (ולא תחלת הכתוב) – כי רק לזה הוצרך להיות קדימת עשר נסיונות (שלימות העבודה, שרק אז נמשכת האתעדל\"ע <i>מלמעלה</i>), משא\"כ \"זקן בא בימים\"."],["2885","13","ראה זהר ח\"ג צ, ב."],["2886","14","ראה בארוכה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381225\" data-slug=\"likkutei-torah\" data-id=\"4001381225\">לקו\"ת שה\"ש כד, סע\"א</a> ואילך."],["2887","15","ב\"ר פרשתנו ספנ\"ח. וראה <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770411\" data-slug=\"or-hatorah-hb\" data-id=\"8316770411\">אוה\"ת שם תשעט, א</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010100\" data-slug=\"or-hatorah-hb\" data-id=\"8159010100\">תשפא, ב</a> ואילך. תשפג, ב ואילך. שם כרך ז תתתז, א ואילך. ד\"ה זה (הא') תרכ\"ז פ\"ו ואילך (סה\"מ תרכ\"ז ע' לז ואילך)."],["2888","16","דניאל ז, ט."],["2889","17","באוה\"ת שם תשפא, ב. ועד\"ז בד\"ה זה (הא') תרכ\"ז פ\"ה (סה\"מ שם ע' לה)."],["2890","18","ראה ב\"ר פס\"ה, ט (ועד\"ז בב\"מ פז, א) \"אברהם תבע זקנה . . כיון שעמד אברהם נתן לו זקנה ואברהם זקן\", וביפ\"ת שם (הובא באוה\"ת שם תשעח, ב. תשעט, ב. ד\"ה הנ\"ל תרכ\"ז בתחלתו – ע' כח) שמקודם הי' הזקנה ניכר מהפנים והגוף, ומאברהם הותחל חתימת זקן (דיקנא)."],["2891","19","בחדא\"ג מהרש\"א לב\"מ שם, שגם מקודם הי' חתימת זקן, והחידוש ד\"ואברהם זקן\" הוא שנעשה הזקנה <i>בליבון</i> שער. ועפ\"ז מובן הקשר ד\"ואברהם זקן\" עם \"לבושי' כתלג <i>חיוור</i>\"."],["2892","20","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380195\" data-slug=\"likkutei-torah\" data-id=\"4001380195\">לקו\"ת אחרי כז, ד</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380199\" data-slug=\"likkutei-torah\" data-id=\"4001380199\">שם כח, ד</a>. ובכ\"מ."],["2893","21","וכמפורש ב<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159200074\" data-slug=\"or-hatorah-hb\" data-id=\"8159200074\">אוה\"ת שם תשפה, ב</a> בהקיצורים \"בא בימים . . א\"א הנק' עתיק יומין\"."],["2894","22","ראה מאו\"א שבהערה הבאה. ובכ\"מ. וב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380518\" data-slug=\"likkutei-torah\" data-id=\"4001380518\">לקו\"ת שלח נא, ג</a> \"א\"א שנק' ג\"כ עתיקא, <i>כנודע</i>\"."],["2895","23","ראה מאו\"א מערכת ע' אות נה (הובא בהמשך תער\"ב ח\"ג ע' א'תלט) \"וא\"א המלביש אותו נק' ג\"כ ע\"ש שמו עתיק יומין\"."],["2896","24","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381313\" data-slug=\"likkutei-torah\" data-id=\"4001381313\">לקו\"ת שה\"ש מו, ב</a>, מע\"ח שער יב (שער אריך אנפין) פ\"א-ב. ובכ\"מ."],["2897","25","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8316770411\" data-slug=\"or-hatorah-hb\" data-id=\"8316770411\">אוה\"ת שם תשעט, א</a>. תשפד, א. ד\"ה הנ\"ל (הב') תרכ\"ז פ\"ח (סה\"מ שם ע' מד)."],["2898","26","ראה קידושין לב, ב. תו\"כ עה\"פ קדושים יט, לב."],["2899","27","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370074\" data-slug=\"torah-or\" data-id=\"3901370074\">ראה זח\"א רכד, א</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370352\" data-slug=\"torah-or\" data-id=\"3901370352\">תו\"א פרשתנו טז, א</a> ואילך. ובארוכה בד\"ה זה ה'תשל\"ח (לקמן ע' שז ואילך). <i>וש\"נ</i>.\nבתו\"א שם סע\"א ואילך, שהלבושים הם <i>תורה</i> ומצוות. וכ\"ה בתו\"א משפטים עט, סע\"ג (הובא באוה\"ת שם תשפב, א. ד\"ה הנ\"ל תרכ\"ז פ\"ו (סה\"מ תרכ\"ז ע' לח)) \"הימים הם בחינת לבושים והם לבושי <i>התורה</i> והמצוות\". אבל בפרטיות, רק המצוות הם לבושים (\"ימים\"), משא\"כ התורה הו\"ע \"זקן\", כמפורש באוה\"ת וסה\"מ תרכ\"ז שבהערה 25."],["2900","28","\"בא בימים\" הוא כמו \"עתיק יומין\". משא\"כ \"זקן\" שהוא \"<i>לבושי'</i> כתלג חיוור\" (כנ\"ל מהצ\"צ), אינו נקרא בשם \"עתיק יומין\" ורק לבושו של \"עתיק יומין\"."],["2901","29","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380199\" data-slug=\"likkutei-torah\" data-id=\"4001380199\">לקו\"ת אחרי כח, ד</a>. ובכ\"מ."],["2902","30","ב<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381226\" data-slug=\"likkutei-torah\" data-id=\"4001381226\">לקו\"ת שה\"ש כד, ב</a> משמע שאתעדל\"ת מגעת רק עד עצם ח\"ס, משא\"כ בגלגלתא. אבל ראה לקוטי לוי\"צ לתנ\"ך ומחז\"ל ע' קט, שבכללות – אתעדל\"ת מגעת גם בגלגלתא דאריך. עיי\"ש בארוכה."],["2903","31","ראה בארוכה לקו\"ת שה\"ש שבהערה 14, שבאתעדל\"ע שאין אתעדל\"ת מגעת לשם – שתי בחינות: אתעדל\"ע שלפני האתעדל\"ת, ואתעדל\"ע שלאחרי שלימות העבודה. ובלקוטי לוי\"צ שם ע' קי, שבחינה הראשונה היא בב\"ן דעתיק, והשני' במ\"ה דעתיק. עיי\"ש בארוכה."],["2904","32","אוה\"ת שם תשפד, ב. וכן הוא גם בסד\"ה הנ\"ל (הב') תרכ\"ז (סה\"מ תרכ\"ז ע' מה)."],["2905","33","וי\"ל שהכוונה כאן ב\"פנימיות עתיק שלמעלה מאריך\" היא לג\"ר דעתיק שאינם מתלבשות באריך. ולהעיר מהמשך תרס\"ו ע' רסא, דשרש המ\"ע הוא באריך ובז\"ת דעתיק שמתלבשות באריך, ושרש המל\"ת הוא בג\"ר דעתיק שאינן מתלבשות באריך."],["2906","34","ראה לקו\"ת ר\"פ פקודי. ובכ\"מ."],["2907","35","והגם שצורך העבודה להמשכת בחינה זו היא (לא שהעבודה <i>מעוררת</i> אותה, ורק) מפני שצ\"ל אתר שלים (כנ\"ל ס\"ב) – השלימות דהמקום (שבו נמשכת האתעדל\"ע) צריך להיות לו איזה שייכות וערך לההמשכה."],["2908","36","נוסח ברכות השחר, מברכות ס, ב. וראה מאמרי אדה\"ז על פרשיות התורה ח\"א ע' רו."],["2909","37","פרש\"י לאבות פ\"ה מ\"ג – הובא באוה\"ת שם תשעט, סע\"א ואילך."],["2910","38","ראה שעהיוה\"א פי\"א. ובכ\"מ."],["2911","39","תרגום ירושלמי וירא כב, א. פדר\"א פל\"א. מפרשי המשנה לאבות שם. <i>ובכ\"מ</i>."],["2912","40","שמו\"ר פמ\"ב, ח."],["2913","41","דברים א, ב."],["2914","42","סה\"מ עטר\"ת ע' תקפז."],["2915","43","ע\"ח שבהערה 10."],["2916","44","וראה סה\"מ עטר\"ת שם שזהו גם ביאור הפלוגתא (ראה סהמ\"צ להרמב\"ם מ\"ע א' ובהשגות הרמב\"ן שם) אם אנכי נמנה בתרי\"ג מצוות. עיי\"ש בארוכה."],["2917","45","תקו\"ז בהקדמה (\"פתח אליהו\") יז, א."],["2918","46","ראה אגה\"ק סי\"ג (קיט, ב). סט\"ו (קכא, סע\"א ואילך)."],["2919","47","וירא כב, יב."],["2920","48","סנהדרין פט, ב. תנחומא וירא כב. פרש\"י עה\"פ וירא שם. – נתבאר ב<a class=\"ft-cite\" href=\"#/read/likkutei-sichot/1300201073\" data-slug=\"likkutei-sichot\" data-id=\"1300201073\">לקו\"ש ח\"כ</a> שיחה ג' לפ' וירא (ע' 73 ואילך)."],["2921","49","וירא שם, טז."],["2922","50","זהר ח\"ג קל, ב. \"קיצורים והערות\" לתניא ע' נג. ד\"ה תניא כו' משביעין אותו להצ\"צ (\"קיצורים והערות\" לתניא הוצאת קה\"ת תשמ\"ט ע' קסח)."],["2923","51","שבהערה 4 – הובא בד\"ה ואברהם זקן תרס\"ו בסופו (המשך תרס\"ו ע' פה)."],["2924","52","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381113\" data-slug=\"likkutei-torah\" data-id=\"4001381113\">לקו\"ת ברכה צו, ג</a>."],["2925","53","יהושע כד, ג."],["2926","54","רמז, א-ב."],["2927","55","ישעי' סג, טז. שבת פט, ב."],["2928","56","פע\"ח שער ז (שער הק\"ש) פט\"ו. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381167\" data-slug=\"likkutei-torah\" data-id=\"4001381167\">לקו\"ת שה\"ש ט, רע\"ג</a> (מרמ\"ז – הובא במקדש מלך – לזח\"א ד, ב). שם נ, ג."],["2929","57","ראה לקו\"ת ברכה שם."],["2930","58","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381113\" data-slug=\"likkutei-torah\" data-id=\"4001381113\">לקו\"ת שם צו, סע\"ג</a> ואילך."],["2931","59","ב\"ר פס\"ג, ד."],["2932","60","ראה זח\"ג נג, ב. רד\"ק לתהלים יט, ח. גו\"א ר\"פ בראשית."],["2933","61","אבל לא ממש – שהרי נצטווינו לבקש אל תביאנו לידי נסיון (כנ\"ל סוף סעיף ד)."],["2934","62","ישעי' סד, ג."],["2935","63","קידושין מ, ב. ב\"ק יז, א."],["2936","64","אגה\"ק דהבעש\"ט, נדפסה גם בכתר שם טוב בתחלתו."]]],[1500360044,"<h3>בס\"ד. מוצאי ש\"פ חיי שרה, מבה\"ח כסלו – בחדרו – ה'תשל\"ח<sup data-n=\"2937\">*</sup></h3>\n<b>ואברהם</b> זקן בא בימים גו'<sup data-n=\"2938\">1</sup>, ומביא רבינו הזקן בתו\"א בפרשתנו ד\"ה<sup data-n=\"2939\">2</sup> להבין ענין מה שאמרו רז\"ל<sup data-n=\"2940\">3</sup> יפה שעה אחת בתשובה ומעשים טובים בעולם הזה מכל חיי עולם הבא (ולפני הדרוש – שהוא \"שייך לפסוק ואברהם זקן בא בימים\") מאמר הזהר<sup data-n=\"2941\">4</sup> על הפסוק באינון יומין עילאין כו', שהם הלבושים דתורה ומצוות<sup data-n=\"2942\">5</sup> (תשובה ומעשים טובים) שעל ידם תוכל הנשמה ליהנות מזיו השכינה בעוה\"ב. וענין זה שייך גם לימים כפשוטם<sup data-n=\"2943\">6</sup>, שצריכים להיות כל הימים שלמים, היינו שכל יום יהי' מלא בעשיית מצוה (יומין עילאין). וידוע מאמר הבעל שם טוב<sup data-n=\"2944\">7</sup> \"לא יניח שום יום מעשיית מצוה כו'\". וזהו בא בימים, שאברהם אבינו עבד את עבודתו בכל יום ויום<sup data-n=\"2945\">8</sup>, שכל ימיו היו יומין שלימין (ולא חסרין ח\"ו), ועי\"ז \"בא בימים – באינון יומין עילאין\"<sup data-n=\"2946\">9</sup>. וידוע הדיוק בזה<sup data-n=\"2947\">10</sup>, הרי העיקר הוא לבושי המצוות (יומין עילאין), ומה נוגע בזה ענין הימים (כפשוטם) שלא יניח שום יום מעשיית מצוה כו', הלא יוכל לעשות למחר שתי מצוות. דלכאורה גם כשעושה כמה מצוות במשך יום אחד יש לו אותו מספר המצוות כמו כשהי' מקיימם במשך כמה ימים<sup data-n=\"2948\">11</sup>, וא\"כ, מה נוגע שיקיים מצוה בכל יום דוקא, ועד שכאשר חסר לו יום אחד חסר לו לבוש<sup data-n=\"2949\">12</sup>.\nב) <b>והנה</b> מזה שמעלה זו דאברהם (בא בימים) בא בקרא לאחרי כו\"כ מעלות שלו שבפסוקים שלפנ\"ז, ועד שבכתוב זה גופא בתחילה הוא אומר ואברהםזקן ואח\"כ מוסיף בא בימים, מובן שענין בא בימים הוא מעלה גדולה יותר גם מהמעלה דזקן. דהגם שואברהם זקן פי' שהי' בעילוי נפלא ביותר, וכמרז\"ל<sup data-n=\"2950\">13</sup> שאמר לו הקב\"ה לאברהם בא לבוש לבושי (דהקב\"ה שנקרא<sup data-n=\"2951\">14</sup> עתיק יומין<sup data-n=\"2952\">15</sup>) שנאמר ואברהם זקן, היינו שואברהם זקן היא מעלת אברהם מה שלובש לבוש הקב\"ה כמו שהקב\"ה הוא בבחי' עתיק יומין, הנה בא בימים נעלה עוד יותר. וצריך להבין מהו גודל העילוי דבא בימים, לבושי המצוות [ובפרט בהענין דעשיית מצוה בכל יום דוקא, הגם שאינו מתוסף עי\"ז במספר המצוות], ועד שזה נעלה יותר מענין (ואברהם) זקן שהוא בחי' (הלבוש ד)עתיק יומין<sup data-n=\"2953\">16</sup>.\nג) <b>ויובן</b> זה בהקדים ביאור הידוע<sup data-n=\"2954\">17</sup> בזה שהנשמה צריכה להלבושים דתורה ומצוות בכדי שתוכל ליהנות מזיו השכינה, כי להיות שהנשמה היא נברא [וכמבואר בכ\"מ שהנשמה היא כמו שאלקות נעשה בבחי' נברא<sup data-n=\"2955\">18</sup>, ועד שהדביקות שלה באלקות היא דביקות בלתי ניכרת<sup data-n=\"2956\">19</sup>] וא\"א לנברא להשיג שום השגה באוא\"ס ב\"ה, לכן בכדי שתוכל הנשמה ליהנות מזיו השכינה שהוא הארה מאוא\"ס ב\"ה [ובפרט לחזות בנועם הוי'<sup data-n=\"2957\">20</sup>], צריכה היא ללבושים. וכמשל אור גדול [ביותר, וכמו אור השמש, בחי' שמש הוי'] שאין יכולים להביט בו, וע\"י המסך (שהוא כמו לבוש) יכולים לקבל [ולקלוט] את האור.\n<b>והנה</b> ידוע<sup data-n=\"2958\">21</sup> שכל ממוצע המחבר ב' דברים, צ\"ל כלול משניהם. ומזה מובן גם בענין הלבושים דתומ\"צ [שהם כמו ממוצע המחבר בחי' זיו השכינה (שהוא הארה מאוא\"ס הבל\"ג) עם הנשמה (שהיא נברא ובע\"ג)], שיש בהם מב' הענינים. דשרשם (של התומ\"צ) הוא מרצה\"ע וחכמתו ית' שהם מיוחדים בו ית' (שהוא<sup data-n=\"2959\">22</sup> וחכמתו ורצונו אחד) – ענין הבל\"ג [ועד שרצה\"ע וחכמתו ית' (שרש התומ\"צ) הם למעלה גם מבחי' זיו השכינה<sup data-n=\"2960\">23</sup>], וע\"י שירדו למטה בעוה\"ז הגשמי ציצית בצמר גשמי ותפילין בקלף גשמי וכן בכל המצוות [ועד\"ז הוא גם בתורה שנתלבשה בשכל אנושי, ועד בטענות של שקר, ונתלבשה בדיו על הספר<sup data-n=\"2961\">24</sup>] הם בבחי' מדידה והגבלהועד להמדידה והגבלה דעוה\"ז הגשמי שאין תחתון למטה ממנו<sup data-n=\"2962\">25</sup>, הנה ע\"י ב' ענינים אלו שבתומ\"צ [ענין הבל\"ג שבהם מצד שרשם, וענין הגבול שבהם מצד ירידתן למטה] הם נעשים לבוש וממוצע המחבר את הנשמה שהיא נברא ובע\"ג (וכמו שהיא מלובשת בגוף גשמי) עם בחי' זיו השכינה ועד עם בחי' נועם הוי' שלמעלה מכל מדידה והגבלה<sup data-n=\"2963\">26</sup>.\nד) <b>והנה</b> מצד ההתלבשות דתומ\"צ בעניני עוה\"ז הגשמי שהוא רובו ככולו רע<sup data-n=\"2964\">27</sup>, צריך לנקותן מכל פסולת הנופל בהן<sup data-n=\"2965\">28</sup>, וכמו בלימוד התורה, שמצד זה שהתורה נתלבשה בשכל אנושי ובענינים גשמיים הרי אפשר<sup data-n=\"2966\">29</sup> שהלימוד שלו יהי' שלא לשמה ועד לדרגא הכי תחתונה בשלא לשמה, ועד\"ז במצוות<sup data-n=\"2967\">30</sup>. וזהו מה שהלבושים דתומ\"צ צריכים לרחיצה וכיבוס, שיהי' לבושים נקיים וכו' (ואפילו לא יהיו באופן דמלבושי אגאלתי<sup data-n=\"2968\">31</sup>), בדוגמת לבוש הגשמי שבכדי שיהי' זך ונקי צריך לרחוץ ולכבס אותו<sup data-n=\"2965\">28</sup>. [וגם לאחרי שהאדם מכבס את הלבושים דתומ\"צ שיהיו נקיים מכל פסולת כו', בכדי שיעלו למעלה, צריכים הם להזדכך ע\"י המלאכים, דגפיף להון ונשיק להון<sup data-n=\"2969\">32</sup>. והענין הוא דהנה כתיב<sup data-n=\"2970\">33</sup> אין צדיק בארץ אשר יעשה טוב ולא יחטא, שמפני שהאדם נמצא בארץ בעוה\"ז הגשמי לכן יש בו חטא, חטא מל' חסרון<sup data-n=\"2971\">34</sup> (עכ\"פ). והגם שהחטא (החסרון) הוא לא באשמתו ח\"ו, שהרי ועמך כולם צדיקים<sup data-n=\"2972\">35</sup>, כי אם כמ\"ש<sup data-n=\"2973\">36</sup> נורא עלילה על בני אדם שרצון הקב\"ה הוא שבנ\"א נמצא בעולם כזה [ובדוגמת<sup data-n=\"2974\">37</sup> מלך ששלח את בנו למדינה רחוקה בכדי להראות את חכמת בנו שגם במדינה הרחוקה יכיר את האמת, בחי' ואמת הוי' לעולם<sup data-n=\"2975\">38</sup>], אעפ\"כ, מכיון שבפועל יש בו (חטא מל') חסרון, וגם התומ\"צ שלו אינם בשלימות, וכמ\"ש אין צדיק בארץ אשר יעשה טוב ולא יחטא, שהחסרון (יחטא) הוא גם בהתומ\"צ (ביעשה טוב) שלו, לכן בכדי שהתומ\"צ שלו יעלו למעלה, צריך הוא לסיוע המלאכים].ה) <b>והנה</b> זה מה שהתומ\"צ שבעוה\"ז הגשמי צריכים וזקוקים לסיוע המלאכים הוא לא רק מפני שעוה\"ז הגשמי הוא רובו ככולו רע, אלא (גם<sup data-n=\"2976\">39</sup>) מצד הגשמיות דעוה\"ז<sup data-n=\"2977\">40</sup>. שלהיותו גשמי הוא באין ערוך לעולמות העליונים (הרוחניים). וע\"ד הידוע בנוגע לנשמת האדם, שאפילו צדיק גמור כשעולה לג\"ע צריך טבילה בנהר דינור בכדי לשכוח על חיזו דהאי עלמא, כי מצד האין ערוך דעוה\"ז הגשמי לג\"ע הרי אפילו מקצת מעניני עוה\"ז מונע מלעלות לג\"ע<sup data-n=\"2978\">41</sup> [ובדוגמת העליות שבדרגות דג\"ע שמגעה\"ת לגעה\"ע וכו', שמכיון שהעליות הם באין ערוך, צריך להיות תחילה ביטול ההשגה דגעה\"ת<sup data-n=\"2978\">41</sup>. וכידוע המשל מענין השגת השכל, שבכדי לבוא להשגה עליונה שבאין ערוך להשגה הקודמת (אע\"פ שגם השגה העליונה היא בעוה\"ז הגשמי) צריך להיות תחילה ביטול השגה הקודמת. וכמו ר\"ז כי סליק לארעא דישראל יתיב<sup data-n=\"2979\">42</sup> מאה תעניתא (או מ' תעניות<sup data-n=\"2980\">43</sup>) לשכוח תלמוד בבלי בכדי שיוכל ללמוד תלמוד ירושלמי<sup data-n=\"2981\">44</sup>], עד\"ז הוא גם בנוגע להתומ\"צ של האדם, שמצד היותן מלובשות בענינים גשמיים, צ\"ל תחלה שיזדככו ויתפשטו מגשמיותן ע\"י המלאכים.\nו) <b>ויש</b> לומר בדרך אפשר דהגם שהזדככות התומ\"צ והעלאתן למעלה נעשה ע\"י המלאכים, מ\"מ, מכיון שתכלית השלימות דכל ענין הוא כאשר הוא נעשה ע\"י עבודת האדם (ולכן אדם רוצה בקב שלו דוקא<sup data-n=\"2982\">45</sup>), לכן גם ענין הזדככות התומ\"צ, ההתחלה בזה הוא ע\"י עבודת האדם. וזהו מה שאיתא בתו\"א<sup data-n=\"2983\">46</sup> שכיבוס וזיכוך התומ\"צ הוא ע\"י עבודת התפלה, שהכוונה בזה היא (לא רק שע\"י התפלה הוא מנקה את התומ\"צ מכל פסולת, שלא יהיו באופן דשלא לשמה וכיו\"ב, כי אם), שע\"י התפלה נעשה גם (התחלת<sup data-n=\"2984\">47</sup> ה)זיכוך שלהם, מה שמזדככות מגשמיותן ועולות למעלה. דהנה תפלה היא סולם מוצב ארצה וראשו מגיע השמימה<sup data-n=\"2985\">48</sup>, היינו שהתפלה היא מקשרת את ב' הקצוות דארץ ושמים (מטה ומעלה<sup data-n=\"2986\">49</sup>), ובפרט ע\"פ הידוע<sup data-n=\"2987\">50</sup> שארצה (בתוס' ה') הוא מדריגה היותר תחתונה שבארץ הלזו הגשמית גופא, ושמימה (בתוס' ה') הוא מדריגה היותר נעלית שבשמים (שמי השמים), והשמימה (בתוס' ה'גם בתחילה) הוא למעלה גם משמימה. וזהו סולם מוצב ארצה וראשו מגיע השמימה, שע\"י התפלה \"יוכל להיות עליית גם (האדם) הנמצא ארצה במדריגות היותר תחתונות שבארץ הלזו הגשמית להשמימה להמדרגות היותר נעלות ונפלאות\"<sup data-n=\"2988\">51</sup>. הנה כמו שהתפלה פועלת בהאדם, שגם כשהוא נמצא ארצה יכול הוא להתעלות להשמימה (אלא שצ\"ל גם סיוע המלאכים דחביק לה כו'), עד\"ז פועלת היא גם בכל עניני האדם<sup data-n=\"2989\">52</sup> ובפרט בהתומ\"צ<sup data-n=\"2990\">53</sup> שלו, שע\"י ד' השליבות דתפלה (שהם כנגד ד' עולמות) עולות הן מעולם לעולם, ועד שהן עולות בבחי' השמימה שלמעלה מהעולמות, ועד שהן עולות למהותו ועצמותו ית' ממש.\nז) <b>וזהו</b> אחד הביאורים בהשייכות דלבושי המצוות לענין הימים (כפשוטם), כי עליית המצוות הוא ע\"י התפלה, והתפלה הרי היא \"ענין עבודת היום\" [כמובן גם ממרז\"ל<sup data-n=\"2991\">54</sup> תפלות כנגד תמידין תקנום, עולת תמיד העשוי' בכל יום, שנים ליום<sup data-n=\"2992\">55</sup>], שהתפלה בכל יום מבררת ומעלה את הניצוצות שנתחדשו ביום זה<sup data-n=\"2993\">56</sup>, לכן המצוות [שעלייתן הוא ע\"י התפלה] זקוקים ל\"עבודת היום\"<sup data-n=\"2994\">57</sup>.\n<b>אמנם</b> ביאור זה מבאר רק השייכות דמצוות לימים. אבל עדיין אינו מובן ההכרח לעשיית המצוות בכל יום דוקא, דלכאורה, גם כשיחסיר יום אחד ולמחר יעשה שתי מצוות, יזדככו המצוות ע\"י התפלה דיום המחרת. ואין לומר שהתפלה יכולה לזכך ולהעלות רק המצוות השייכות ליום זה, דאין כל טעם לחילוק זה. ועוד דמכיון דיש ענין התשלומין (ביום שלאח\"ז, בתפלה הסמוכה לה)<sup data-n=\"2995\">58</sup> \"ואין אומרים כיון שעבר יומו בטל קרבנו\"<sup data-n=\"2996\">59</sup>, ועד ש(בנוגע לכוונת התפלה) תפלה אחת מלוקטת מתפלות כל השנה מעלית את התפלות דכל השנה<sup data-n=\"2997\">60</sup>, משמע מזה גם בנוגע לעליית המצוות שע\"י התפלה, שהתפלה מעלית גם המצוות דיום הסמוך וכו'. וסמוכין לדבר – התפלות דשבת שהן מעלות התפלות של כל ימי החול עם כל התורה ומע\"ט שנכללו בהן<sup data-n=\"2998\">61</sup>.\nח) <b>אך</b> הענין הוא, דהנה ידוע שהתכלית דתומ\"צ הוא לפעול בירור וזיכוך בעוה\"ז הגשמי. דזהו מה שתורה לא בשמים היא<sup data-n=\"2999\">62</sup>, וכל התורה ניתנה לעשות שלוםבעולם<sup data-n=\"3000\">63</sup>, ועאכו\"כ מצוות שלא ניתנו אלא לצרף בהן את הבריות<sup data-n=\"3001\">64</sup>. ועד שמצות צדקה היא שקולה כנגד כל המצוות (ונקראת בשם מצוה סתם), כי התכלית דמצוות [וכן התכלית דירידת הנשמה למטה] שהוא [לא בשביל הנשמה כ\"א] בכדי לתקן את הגוף ונה\"ב וחלקו בעולם, נשלם ע\"י מצות הצדקה (יותר מאשר ע\"י שאר כל המצוות), כמבואר בתניא<sup data-n=\"3002\">65</sup>. וזהו<sup data-n=\"3003\">66</sup> שצריך להיות יומין שלימין דוקא, שבכל יום ויום צריך להיות קיום מצוה, כי מכיון שגדר העולם הוא מקום וזמן<sup data-n=\"3004\">67</sup>, הרי מובן שהתומ\"צ (שתכליתם הוא לתקן את העולם) צריכים לתקן גם את הזמן. ולכן מוכרח שבכל יום תהי' עשיית מצוה (הגם שגם כשחסר לו יומא חדא יכול הוא לעשות את הלבוש ע\"י שיקיים מחר ב' מצוות), כי בכדי לתקן את הימים<sup data-n=\"3005\">68</sup> (הזמן) גופא צריך להיות כל<sup data-n=\"3006\">69</sup> יומא ויומא עביד עבידתי'.\nט) <b>וזהו</b> ואברהם זקן בא בימים, שלאחרי שואברהם זקן הוא גם בא בימים שהוא מעלה גדולה יותר גם מהמעלה דזקן. דהנה הכוונה האמיתית בהתהוות העולמות (בבחי' עצמות א\"ס) היא מה שנתאוה הקב\"ה להיות לו ית' דירה בתחתונים דוקא<sup data-n=\"3007\">70</sup>. וכוונה זו נשלמת ע\"י עבודת האדם, אתם קרויין אדם<sup data-n=\"3008\">71</sup>, שהאדם דוקא יכול להשלים כוונה זו. וזהו שנקרא בשם אדם, ע\"ש ב' הקצוות שהוא אדמה לעליון<sup data-n=\"3009\">72</sup> ושהוא נוצר מן האדמה<sup data-n=\"3010\">73</sup>, שגופו נעשה מהאדמה עצמה<sup data-n=\"3011\">74</sup> ובאופן שהי' תחילה דומם בפ\"ע (בלי שום נפש חיונית בתוכו) וכמ\"ש<sup data-n=\"3012\">75</sup> גלמי ראו עיניך (ולא כגוף הצומח והחי)<sup data-n=\"3013\">76</sup>, כי גם ענין זה שבתואר אדם (על שם האדמה) מורה על מעלתו<sup data-n=\"3014\">77</sup>, שהוא מברר מתקן ומעלה גם את הדומם שהוא תחתון ביותר שאין תחתון למטה ממנו.ומעלה זו שבו באה בפועל ע\"י העבודה דבא בימים דוקא. שע\"י העבודה דזקן (עצמה), אף שגם עי\"ז בירר ותיקן את חלקו בעולם (מקום), מ\"מ, מכיון שלא תיקן עדיין את הזמן, הרי לא השלים עדיין הכוונה דדירה בתחתונים. ולכן הגם שעבודה זו מגעת בבחינת עתיק יומין, שהיא בהעתקה (והבדלה) מבחי' יומין, אין זה תכלית השלימות. משא\"כ ע\"י העבודה דבא בימים<sup data-n=\"3015\">78</sup>, כשעובד לתקן את הימים, ועד דאת מספר ימיך אמלא<sup data-n=\"3016\">79</sup> מספר מלשון אבן ספיר (וכמ\"ש בתו\"א<sup data-n=\"3017\">80</sup> שמספר ימיך הוא כמו השמים מספרים<sup data-n=\"3018\">81</sup> שפירש בזהר<sup data-n=\"3019\">82</sup> מנהרין ומנצצין וספירין), היינו שהאדם מאיר את הימים (הזמן) באור התורה והמצוות, עי\"ז הוא משלים הכוונה דדירה בתחתונים (בהתחתון שבעולם הזה גופא<sup data-n=\"3020\">83</sup>), שזה (השלמת כוונה זו) הוא תכלית שלימות מעלת האדם, כנ\"ל.\n**********",[["2937","*","יצא לאור ב<b>קונטרס מוצאי ש\"פ חיי שרה – ה'תשל\"ח</b>, \"<i>ג' כסלו ה'תשל\"ח</i>\"."],["2938","1","פרשתנו כד, א."],["2939","2","טז, א. וראה <a class=\"ft-cite\" href=\"#/read/torah-or/3901370340\" data-slug=\"torah-or\" data-id=\"3901370340\">תו\"א משפטים עו, ג</a>. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370351\" data-slug=\"torah-or\" data-id=\"3901370351\">עט, ב</a>."],["2940","3","אבות פ\"ד מי\"ז."],["2941","4","ראה זח\"א רכד, א. וראה שם קכט, א הלשון \"יומין עילאין\"."],["2942","5","באגה\"ק וב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370351\" data-slug=\"torah-or\" data-id=\"3901370351\">תו\"א</a> מקץ שבהערה 17 [וכן בתו\"א ח\"ש שם (בתחילת הענין)] <i>שהמצוות</i> הם לבושים. אבל בתו\"א משפטים עט, ב (וראה גם תו\"א ח\"ש בהמשך הענין – נעתק לקמן ס\"ג): לבושי <i>התורה</i> והמצוות – בפרטיות יותר. וראה תניא ספ\"ה. אוה\"ת משפטים ע' א'רסו."],["2943","6","כ\"ה בתו\"א משפטים שם."],["2944","7","צוואת הריב\"ש בתחלתה."],["2945","8","ראה זח\"א קכט, א: ולא אתקריב אברהם ביומא חדא או בזמנא חדא אלא עובדוי קריבו לי' בכל יומוי כו'."],["2946","9","לשון הזהר שם."],["2947","10","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830262\" data-slug=\"or-hatorah-hb\" data-id=\"8158830262\">אוה\"ת שבועות ע' צא</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010084\" data-slug=\"or-hatorah-hb\" data-id=\"8159010084\">בלק ע' תתקמח</a>. פינחס ע' א'קצט. וראה גם אוה\"ת לתהלים ע' תקכז."],["2948","11","באוה\"ת וארא ע' קכ: \"וצריך לסגל תורה ומצוות אפילו מצוה אחת כמה פעמים במספר הימים אשר נתנו לו מן השמים כפי שיעור הלבושים הצריכים לפי שרש נשמתו . . כי מאחר שיש לו פנאי כו'\".\nוהשאלה שבפנים (ממקומות שבהערה הקודמת) \"הלא יוכל לעשות למחר שתי מצוות\" – כי מהלשון \"יומין שלימין\" מוכח דמה שצריך לעשות מצוה <i>בכל יום</i> (כתורת הבעש\"ט המובאה בפנים) הוא גם כשאין לו פנאי (במשך ב' הימים) לעשות יותר מב' מצוות, שאין נפק\"מ במספר המצוות."],["2949","12","\"ודוחק לומר דמיירי בביטול מ\"ע התלויות בו ביום כמו ק\"ש כו', (ועוד?) דא\"כ מלבד מה שחסר הלבוש הרי פגם ג\"כ בביטול המצוה וצריך תשובה\" (אוה\"ת בלק שם)."],["2950","13","ב\"ר ספנ\"ח."],["2951","14","דניאל ז, ט."],["2952","15","מ\"כ לב\"ר שם (הובא באוה\"ת פרשתנו תשעט, א). וראה גם פרש\"י לב\"ר שם. ובהגהות הרד\"ל שם מביא מילקוט \"דכתיב עתיק יומין יתיב\"."],["2953","16","ובפרט לפי מ\"ש ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370154\" data-slug=\"torah-or\" data-id=\"3901370154\">תו\"א מקץ לג, ב</a>, שעתיק יומין הוא \"נעתק ונבדל מבחי' היומין שהם הלבושים הנעשים מהמצוות\"."],["2954","17","ראה בכ\"ז אגה\"ק סכ\"ט. <a class=\"ft-cite\" href=\"#/read/torah-or/3901370152\" data-slug=\"torah-or\" data-id=\"3901370152\">תו\"א מקץ לב, ד</a> ואילך. וראה גם תו\"א פרשתנו שבהערה 2."],["2955","18","ראה ביאוה\"ז לאדהאמ\"צ (קטו, ב) ולהצ\"צ (ע' תקמח). המשך תרס\"ו ע' תנט. ס\"ע תע."],["2956","19","דנוסף לזה שהכלים דאצילות (שרש הנשמות) הם בדביקות בלתי ניכרת, הנה גם הדביקות דנשמות בהכלים היא בלתי ניכרת (ראה המשך תער\"ב ח\"א ריש ע' קע)."],["2957","20","אגה\"ק שם."],["2958","21","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001381161\" data-slug=\"likkutei-torah\" data-id=\"4001381161\">לקו\"ת שה\"ש ח, א</a>. המשך תער\"ב ח\"א ע' שצו. סה\"מ ה'ש\"ת ד\"ה עוטה אור כשלמה. ובכ\"מ."],["2959","22","שעהיוה\"א פ\"ח."],["2960","23","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370074\" data-slug=\"torah-or\" data-id=\"3901370074\">תו\"א פרשתנו טז, סע\"א</a>. וראה הגהות הצ\"צ לשם (אוה\"ת פרשתנו תשפו, סע\"ב)."],["2961","24","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310009\" data-slug=\"tanya\" data-id=\"3401310009\">תניא פ\"ד</a>. וזהו \"התלבשות\" יותר מזה שמתלבשת בטענות של שקר, כי ההתלבשות דתורהבטענות של שקר היא רק מה שהתורה <i>דנה</i> בזה, \"ולשון התלבשות הוא רק שם המושאל בלבד\" (ד\"ה ויאמר משה תש\"ד ס\"כ); משא\"כ בהתלבשותה \"בדיו על הספר עשרים וארבעה ספרים שבתורה נביאים וכתובים\", הרי <i>בתושב\"כ</i> נוגע דיני הדיו והקלף."],["2962","25","<a class=\"ft-cite\" href=\"#/read/tanya/3401310041\" data-slug=\"tanya\" data-id=\"3401310041\">תניא פל\"ו</a>."],["2963","26","בכל הבא לעיל – ראה תו\"א (פרשתנו ופ' מקץ) שבהערה 17."],["2964","27","<a class=\"ft-cite\" href=\"#/read/tanya/3401310012\" data-slug=\"tanya\" data-id=\"3401310012\">תניא פ\"ז (יא, ב</a>)."],["2965","28","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370338\" data-slug=\"torah-or\" data-id=\"3901370338\">תו\"א משפטים עו, א</a>."],["2966","29","ראה קונטרס עה\"ח פי\"א."],["2967","30","ראה אוה\"ת לתהלים שם, שענין כיבוס הלבושים הוא \"דאל\"כ י\"ל הם מטונפים שיש מצוה שלא לשמה\"."],["2968","31","ישעי' סג, ג. אוה\"ת לתהלים שם."],["2969","32","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370193\" data-slug=\"torah-or\" data-id=\"3901370193\">ראה זח\"א כג, ב</a>. ח\"ב רא, ב. תו\"א מקץ מג, סע\"א ואילך. סידור רעג, ב."],["2970","33","קהלת ז, כ."],["2971","34","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380650\" data-slug=\"likkutei-torah\" data-id=\"4001380650\">לקו\"ת מטות פב, א</a>. <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380923\" data-slug=\"likkutei-torah\" data-id=\"4001380923\">נצבים נא, א</a>. ד\"ה על כן יאמרו המושלים תרצ\"א בתחלתו (סה\"מ קונטרסים ח\"א ע' 382). ובכ\"מ."],["2972","35","ישעי' ס, כא."],["2973","36","תהלים סו, ה. תנחומא וישב ד. וראה תו\"ח תולדות יג, א ואילך."],["2974","37","ראה המשך תרס\"ו ס\"ע שפ ואילך."],["2975","38","תהלים קיז, ב."],["2976","39","ראה <a class=\"ft-cite\" href=\"#/read/tanya/3401310045\" data-slug=\"tanya\" data-id=\"3401310045\">תניא פ\"מ (נד, ב</a>), שעוה\"ז הוא עולם השפל בב' בחינות: (א) ש\"ההארה שבו מצומצמת מאד עד קצה האחרון ולכן הוא חומרי וגשמי\". (ב) שהארה זו גופא \"היא בלבושים ומסכים רבים כו'\"."],["2977","40","<i>וע\"ד</i> המבואר ב<a class=\"ft-cite\" href=\"#/read/tanya/3401310040\" data-slug=\"tanya\" data-id=\"3401310040\">תניא שם</a> בנוגע ל\"אותיות הקדושות של דברי תורה ותפלה\", ש\"מאחר שהקול והדיבור הוא גשמי\" – העלאתן למעלה היא דוקא ע\"י הכוונה המתלבשת בהם – אף ששתיהן (האותיות והכוונה) שוות בזה שאינן בבחי' הסתר."],["2978","41","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370145\" data-slug=\"torah-or\" data-id=\"3901370145\">תו\"א מקץ לא, סע\"א</a>. המשך תרס\"ו ע' טו. ובכ\"מ."],["2979","42","ב\"מ פה, א."],["2980","43","גירסת הרש\"ל שם, ועוד – ראה דק\"ס שם."],["2981","44","המשך תרס\"ו שם. המשך תער\"ב ח\"ב ע' א'נ ואילך."],["2982","45","ב\"מ לח, א."],["2983","46","משפטים עו, א. שם, ג. דרמ\"צ פג, א."],["2984","47","שלכן, גם העלאת התפלה היא ע\"י המלאכים (מקומות שבהערה 32)."],["2985","48","ויצא כח, יב. זח\"א רסו, ב. זח\"ג שו, ב. תקו\"ז תי' מה."],["2986","49","שהם לא רק רחוקים זמ\"ז אלא גם הפכים (ד\"ה זה היום תרצ\"ד ספ\"א – סה\"מ קונטרסים ח\"ב שיט, א)."],["2987","50","ד\"ה זה היום שם."],["2988","51","לשון כ\"ק מו\"ח אדמו\"ר בד\"ה זה היום הנ\"ל רפ\"ב."],["2989","52","ראה ד\"ה זה היום שם ספ\"ב (סה\"מ שם שיט, ב): דע\"י אותיות התפלה הוא ההעלאה של כל הענינים דארצה שהם עפ\"י התורה."],["2990","53","ראה <a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380591\" data-slug=\"likkutei-torah\" data-id=\"4001380591\">לקו\"ת יו\"כ סח, ב</a> (הובא באוה\"ת לתהלים שם) ש\"מלאכי אלקים\" (שעולים בהסולם דתפלה) הם המצוות."],["2991","54","ברכות כו, ב."],["2992","55","פינחס כח, ג."],["2993","56","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370175\" data-slug=\"torah-or\" data-id=\"3901370175\">תו\"א מקץ לח, ג</a>."],["2994","57","אוה\"ת לתהלים שם."],["2995","58","או\"ח סי' קח."],["2996","59","שו\"ע אדה\"ז שם ס\"ב."],["2997","60","תניא בקו\"א ד\"ה להבין מ\"ש בשער היחודים (קנד, ב)."],["2998","61","<a class=\"ft-cite\" href=\"#/read/likkutei-torah/4001380252\" data-slug=\"likkutei-torah\" data-id=\"4001380252\">לקו\"ת בהר מא, א</a>."],["2999","62","ב\"מ נט, ב."],["3000","63","רמב\"ם סוף הל' חנוכה."],["3001","64","ב\"ר פמ\"ד, א."],["3002","65","פל\"ז (מח, ב)."],["3003","66","<a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8158830262\" data-slug=\"or-hatorah-hb\" data-id=\"8158830262\">אוה\"ת משפטים ע' א'קכב</a>. <a class=\"ft-cite\" href=\"#/read/or-hatorah-hb/8159010084\" data-slug=\"or-hatorah-hb\" data-id=\"8159010084\">שבועות ע' צא</a>. בלק ס\"ע תתקמח. פינחס ע' א'קצט. וראה בארוכה לקו\"ש ח\"ד ע' 1194."],["3004","67","שעהיוה\"א פ\"ז (פב, רע\"א). וע\"פ מ\"ש בתורת לוי\"צ למסכת מדות (ריש ע' רעג), שמקום הוא בז\"א וזמן הוא במלכות – עיקר הענין דדירה בתחתונים שאין תחתון למטה ממנו הוא בבירור ותיקון הזמן."],["3005","68","ומה שעיקר ההדגשה הוא על הימים (וראה תורת הבעש\"ט שבתחילת המאמר) – הוא (כמבואר בלקו\"ש שם) לפי שבהם הוא עיקר ההתחלקות דזמן, כמרז\"ל (נזיר ז, א) \"יומי מפסקי מהדדי\". ולהעיר מאוה\"ת בלק שם ואילך."],["3006","69","ע\"פ לשון הזהר – ח\"ג צד, ב."],["3007","70","המשך תרס\"ו ע' תמו."],["3008","71","יבמות סא, א."],["3009","72","של\"ה כ, ב. שא, ב. ובכ\"מ."],["3010","73","ב\"ר פי\"ז, ד."],["3011","74","והיינו , שהצומח והחי נבראו ממאמר אלקי (תדשא הארץ, תוצא הארץ), משא\"כ \"גופו של אדה\"ר לא נברא ע\"י מאמר אלקי . . כשאר כל הברואים . . אלא רק צבר עפרו . . ועשה בו צורה גשמית שלא ע\"י מאמר כלל וכלל\". ומ\"ש נעשה אדם – \"פשוטו מורה שלא ע\"י מאמר זה נעשה אלא כמ\"ש צבר עפרו ועשאו גולם תחילה בלי מאמר כלל\" (<a class=\"ft-cite\" href=\"#/read/torat-chaim/2300670057\" data-slug=\"torat-chaim\" data-id=\"2300670057\">תו\"ח בראשית יט, ב</a>)."],["3012","75","תהלים קלט, טז. וראה סנהדרין לח, סע\"א ואילך."],["3013","76","<a class=\"ft-cite\" href=\"#/read/torah-or/3901370013\" data-slug=\"torah-or\" data-id=\"3901370013\">תו\"א בראשית ג, ד</a> ואילך. תו\"ח שם יח, ד ואילך. ובכ\"מ."],["3014","77","ד\"ה זה היום השי\"ת פ\"ב (סה\"מ ה'תש\"י ע' 97-96)."],["3015","78","והא שמבואר ב<a class=\"ft-cite\" href=\"#/read/torah-or/3901370154\" data-slug=\"torah-or\" data-id=\"3901370154\">תו\"א מקץ לג, ב</a> (נעתק לעיל הערה 16) שעתיק יומין הוא נבדל מבחי' היומין שהם הלבושים הנעשין מהמצוות – יש לומר, שהכוונה שם היא לענין המצוות (מצד עצמם), אבל לא לענין בירור הזמן שנעשה עי\"ז. ולהעיר מזה שמסיים בתו\"א שם: אך ע\"י בירור נה\"ב כו'. ועצ\"ע."],["3016","79","משפטים כג, כו."],["3017","80","משפטים עט, ריש ע\"ג."],["3018","81","תהלים יט, ב."],["3019","82","ח\"ב קלו, ב. ונתבאר בארוכה בסידור קעח, סע\"א ואילך. פיה\"מ לאדהאמ\"צ פ\"ט ואילך."],["3020","83","ראה לעיל הערה 67."]]]]});
